            <option value="user">普通用户</option>
        </select>
        <button onclick="changeRole()" id="confirmBtn" disabled>确认角色</button>
    </div>

    <!-- 所有内容默认隐藏，通过data-role控制 -->
    <div class="content hidden" data-role="admin" id="adminContent">
        <h3>🔐 管理员控制台</h3>
