            <h4>全部订单管理</h4>
            <ul>
                <li>🧾 Order ID: 101 - John Doe - $1299</li>
                <li>🧾 Order ID: 102 - Jane Smith - $999</li>
            </ul>
            <button onclick="adminAction()">批量操作</button>
        </div>
    </div>

