        <h3>❌ 无权限访问</h3>
        <p>请选择有效的角色并确认。</p>
    </div>
</div>

<script>
class SecureRBAC {
    constructor() {
        this.currentRole = sessionStorage.getItem('userRole') || null;
        this.init();
    }

    init() {
        this.attachEventListeners();
        this.validateCurrentRole();
        this.startSecurityMonitor();
    }

    attachEventListeners() {
        const selector = document.getElementById('roleSelector');
        const confirmBtn = document.getElementById('confirmBtn');

        selector.addEventListener('change', () => {
            confirmBtn.disabled = !selector.value;
        });

        // 防止直接调用
        window.changeRole = this.changeRole.bind(this);
        window.adminAction = this.adminAction.bind(this);
        window.userAction = this.userAction.bind(this);
    }

    validateCurrentRole() {
        if (this.currentRole) {
            this.renderRoleContent(this.currentRole);
            document.getElementById('roleSelector').value = this.currentRole;
            document.getElementById('confirmBtn').disabled = false;
        } else {
            this.showNoAccess();
        }
