    changeRole() {
        const role = document.getElementById('roleSelector').value;

        if (!role) {
            this.showSecurityAlert('请选择有效的角色');
            return;
        }

        // 模拟服务端验证
        this.simulateServerValidation(role)
            .then((isValid) => {
                if (isValid) {
                    this.setRole(role);
                } else {
                    this.showSecurityAlert('服务端验证失败：无效角色');
                    this.logout();
                }
            })
            .catch(() => {
                this.showSecurityAlert('网络验证失败，请重试');
            });
    }

    simulateServerValidation(role) {
        return new Promise((resolve) => {
            setTimeout(() => {
                // 模拟API延迟和验证
                const validRoles = ['admin', 'user'];
                resolve(validRoles.includes(role));
            }, 500);
        });
    }

    setRole(role) {
        this.currentRole = role;
        sessionStorage.setItem('userRole', role);
        this.renderRoleContent(role);
        this.updateSecurityStatus('正常');
    }

    renderRoleContent(role) {
        // 隐藏所有内容
        document.querySelectorAll('.content').forEach(el => {
            el.classList.add('hidden');
        });

        const targetContent = document.getElementById(
            role === 'admin' ? 'adminContent' : 
            role === 'user' ? 'userContent' : 'noAccessContent'
        );

        targetContent.classList.remove('hidden');

        // 移除之前的安全警告
        document.querySelector('.tamper-detected')?.classList.remove('tamper-detected');
    }

    showNoAccess() {
        this.renderRoleContent('');
        sessionStorage.removeItem('userRole');
        this.currentRole = null;
    }

    adminAction() {
        if (this.currentRole !== 'admin') {
            this.securityBreach('非法访问管理员功能');
            return;
