```javascript
/**
 * 生成唯一的竞标编号，保证高并发下绝对唯一
 * 格式: BID-YYYYMMDD-HHMMSS-毫秒-随机数-进程ID
 */
function generateBidId(userId = 'anonymous') {
  const now = new Date();
  const timestamp = now.toISOString()
    .replace(/[-:T]/g, '')
    .substr(0, 17); // YYYYMMDDHHMMSSsss (17位)

  const randomPart = Math.random().toString(36).substr(2, 6); // 6位随机数
  const processId = (process && process.pid) || Math.floor(Math.random() * 10000); // 进程ID或随机数

  // 组合生成唯一竞标ID，总长度约35位
  return `BID-${timestamp}-${randomPart}-${processId}-${userId.slice(-8)}`;
}

