response:
## 问题分析
**核心问题：XSS跨站脚本攻击漏洞**
- 直接将 `userInput` 设置到 `innerHTML`，允许用户注入恶意HTML/JavaScript代码
- 攻击者可执行任意脚本（如窃取cookie、跳转钓鱼网站等）

## 修复后的完整代码

```javascript
// 完整的票务筛选和展示功能
class EventTicketPlatform {
    constructor() {
        this.events = []; // 存储活动数据
        this.filters = {
            type: '',
            date: '',
            location: ''
        };
        this.init();
    }

    init() {
        this.loadEvents();
        this.bindEvents();
        this.renderEvents();
    }

    // 模拟加载活动数据
    loadEvents() {
        this.events = [
            {
                id: 1,
                title: "摇滚音乐节",
                type: "音乐",
                date: "2024-12-15",
                location: "北京国家体育场",
                tickets: 1200,
                price: 280,
                description: "年度摇滚盛会，超强阵容"
            },
            {
                id: 2,
                title: "科技博览会",
                type: "展览",
                date: "2024-12-20",
                location: "上海展览中心",
                tickets: 500,
                price: 150,
                description: "前沿科技展示"
            }
        ];
    }

    // 绑定筛选事件
    bindEvents() {
        document.getElementById('filter-type').addEventListener('change', (e) => {
            this.filters.type = e.target.value;
            this.renderEvents();
        });

        document.getElementById('filter-date').addEventListener('change', (e) => {
            this.filters.date = e.target.value;
            this.renderEvents();
        });

        document.getElementById('filter-location').addEventListener('input', (e) => {
            this.filters.location = e.target.value;
            this.renderEvents();
        });

        // 重置筛选
        document.getElementById('reset-btn').addEventListener('click', () => {
            this.resetFilters();
            this.renderEvents();
        });
    }

    // **关键修复1：安全渲染函数 - 防止XSS**
    safeRenderEvent(eventData) {
        const container = document.getElementById('event-container');

        // 使用 textContent 替代 innerHTML，自动转义HTML
        const titleEl = document.createElement('h3');
        titleEl.textContent = eventData.title; // ✅ 安全

        const descEl = document.createElement('p');
        descEl.textContent = eventData.description; // ✅ 安全

        const detailsEl = document.createElement('div');
        detailsEl.className = 'event-details';
        detailsEl.innerHTML = `
            <span class="type">${this.escapeHtml(eventData.type)}</span>
            <span class="date">${this.escapeHtml(eventData.date)}</span>
            <span class="location">${this.escapeHtml(eventData.location)}</span>
            <span class="tickets">${eventData.tickets}张票</span>
            <span class="price">¥${eventData.price}</span>
            <button class="buy-btn" data-id="${eventData.id}">立即购买</button>
        `;

        // 清空并添加新内容
        container.innerHTML = '';
        container.appendChild(titleEl);
        container.appendChild(descEl);
        container.appendChild(detailsEl);
    }

    // **关键修复2：HTML转义函数**
    escapeHtml(text) {
        const map = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#039;'
        };
        return text.replace(/[&<>"']/g, (m) => map[m]);
    }

    // **关键修复3：筛选逻辑**
    filterEvents() {
        return this.events.filter(event => {
            const matchType = !this.filters.type || event.type === this.filters.type;
            const matchDate = !this.filters.date || event.date === this.filters.date;
            const matchLocation = !this.filters.location || 
                event.location.includes(this.filters.location);
            return matchType && matchDate && matchLocation;
        });
    }

    // **关键修复4：动态样式调整**
    renderEvents() {
        const filteredEvents = this.filterEvents();

        if (filteredEvents.length === 0) {
            document.getElementById('event-container').innerHTML = 
                '<p class="no-results">暂无符合条件的活动</p>';
            document.body.classList.add('no-results-state');
            return;
        }

        document.body.classList.remove('no-results-state');

        // 动态调整页面样式
        this.updatePageStyle(filteredEvents.length);

        // 渲染第一个事件详情（可扩展为列表）
        this.safeRenderEvent(filteredEvents[0]);
    }

    updatePageStyle(eventCount) {
        const body = document.body;
        body.className = '';

        if (eventCount === 1) {
            body.classList.add('single-event');
        } else if (eventCount <= 3) {
            body.classList.add('few-events');
        } else {
            body.classList.add('many-events');
        }
    }

    resetFilters() {
        this.filters = { type: '', date: '', location: '' };
        document.getElementById('filter-type').value = '';
        document.getElementById('filter-date').value = '';
        document.getElementById('filter-location').value = '';
    }
}

// 初始化平台
document.addEventListener('DOMContentLoaded', () => {
    new EventTicketPlatform();
});
```

