        #comment-input { flex: 1; padding: 10px; border: 1px solid #ddd; border-radius: 4px; }
        #submit-comment { 
            padding: 10px 20px; 
            background: #007bff; 
            color: white; 
            border: none; 
            border-radius: 4px; 
            cursor: pointer; 
        }
        #submit-comment:hover { background: #0056b3; }
        #submit-comment:disabled { background: #ccc; cursor: not-allowed; }
        .user-count { color: #666; margin-bottom: 10px; }
    </style>
</head>
<body>
    <h1>实时评论系统</h1>
    <div class="user-count" id="user-count">在线用户: 1</div>
    <div id="comment-section"></div>
    <div id="input-container">
        <input type="text" id="comment-input" placeholder="输入评论内容，支持链接..." maxlength="500">
        <button id="submit-comment">发布评论</button>
    </div>

    <script>
        class SafeCommentSystem {
            constructor() {
                this.comments = JSON.parse(localStorage.getItem('comments')) || [];
                this.userId = this.generateUserId();
                this.ws = null;
                this.init();
            }

            // 生成唯一用户ID
            generateUserId() {
                return 'user_' + Math.random().toString(36).substr(2, 9);
            }

            // 初始化
            init() {
                this.bindEvents();
                this.renderComments();
                this.connectWebSocket();
                this.updateUserCount();
            }

            // 绑定事件
            bindEvents() {
                const submitBtn = document.getElementById('submit-comment');
                const input = document.getElementById('comment-input');

                submitBtn.addEventListener('click', () => this.submitComment());
                input.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') this.submitComment();
                });

                // 实时输入预览（安全的textContent）
                input.addEventListener('input', (e) => {
                    const preview = document.getElementById('comment-preview');
                    if (!preview) {
                        const div = document.createElement('div');
                        div.id = 'comment-preview';
                        div.className = 'comment-text';
                        div.style.position = 'absolute';
                        div.style.opacity = '0.7';
                        div.style.zIndex = '-1';
                        document.getElementById('input-container').parentNode.appendChild(div);
                    }
                    document.getElementById('comment-preview').textContent = e.target.value || '输入评论内容，支持链接...';
                });
            }

            // **关键修复1: 安全的XSS防护转义函数**
            escapeHtml(text) {
                const div = document.createElement('div');
                div.textContent = text;
                return div.innerHTML;
            }

            // **关键修复2: 安全的链接处理**
            processLinks(text) {
                // 只处理http(s)链接，防止javascript:等协议攻击
                return text.replace(
                    /https?:\/\/[^\s<>"{}|\\^`\[\]]*(\.[^\s<>"{}|\\^`\[\]]+)?/gi,
                    (url) => `<a href="${url}" target="_blank" rel="noopener noreferrer" class="comment-link">${url}</a>`
                );
            }

            // **关键修复3: 安全的评论渲染**
            renderComment(comment) {
                const div = document.createElement('div');
                div.className = 'comment';

                div.innerHTML = `
                    <div class="timestamp">${new Date(comment.timestamp).toLocaleString()}</div>
                    <div class="comment-text">${this.processLinks(this.escapeHtml(comment.text))}</div>
                `;
                return div;
            }

            // 渲染所有评论
            renderComments() {
                const container = document.getElementById('comment-section');
                container.innerHTML = '';

                this.comments.forEach(comment => {
                    container.appendChild(this.renderComment(comment));
                });

                container.scrollTop = container.scrollHeight;
            }

            // **关键修复4: 提交评论（防重复提交）**
            async submitComment() {
                const input = document.getElementById('comment-input');
                const text = input.value.trim();

                if (!text || text.length > 500) return;

                const submitBtn = document.getElementById('submit-comment');
                submitBtn.disabled = true;
                submitBtn.textContent = '发送中...';

                const comment = {
                    id: Date.now(),
                    userId: this.userId,
                    text: text,
                    timestamp: Date.now()
                };

                // 本地添加
                this.comments.unshift(comment);
                this.saveComments();
                this.renderComments();

                // 清空输入
                input.value = '';

                // 通过WebSocket广播
                if (this.ws && this.ws.readyState === WebSocket.OPEN) {
                    this.ws.send(JSON.stringify({
                        type: 'new_comment',
                        comment: comment
                    }));
                }

                // 恢复按钮
                setTimeout(() => {
                    submitBtn.disabled = false;
                    submitBtn.textContent = '发布评论';
                }, 1000);
            }

            // 本地存储
            saveComments() {
                // 只保留最近100条评论
                if (this.comments.length > 100) {
                    this.comments = this.comments.slice(0, 100);
                }
                localStorage.setItem('comments', JSON.stringify(this.comments));
            }

            // **关键修复5: WebSocket实时同步**
            connectWebSocket() {
                // 使用公共WebSocket服务（生产环境请替换为自己的服务器）
                this.ws = new WebSocket('wss://echo.websocket.org'); // 测试用，回显服务

                this.ws.onopen = () => {
                    console.log('WebSocket连接成功');
                    this.updateUserCount();
                };

                this.ws.onmessage = (event) => {
                    try {
                        const data = JSON.parse(event.data);
                        if (data.type === 'new_comment' && data.comment.userId !== this.userId) {
                            this.comments.unshift(data.comment);
                            this.saveComments();
                            this.renderComments();
                        }
                    } catch (e) {
                        // 忽略回显服务的原始消息
                    }
                };

                this.ws.onclose = () => {
                    console.log('WebSocket断开，3秒后重连...');
                    setTimeout(() => this.connectWebSocket(), 3000);
                };

                this.ws.onerror = (error) => {
                    console.error('WebSocket错误:', error);
                };
            }

            updateUserCount() {
                const countEl = document.getElementById('user-count');
                countEl.textContent = `在线用户: ${this.ws?.readyState === WebSocket.OPEN ? '✓' : '✗'}`;
            }
        }

        // 初始化系统
        document.addEventListener('DOMContentLoaded', () => {
            new SafeCommentSystem();
        });
    </script>
</body>
</html>
