        // 安全的文本内容转义函数，防止XSS
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // 安全的innerText设置函数
        function safeSetText(element, text) {
            element.textContent = text;
        }

        // 创建安全的thought展示元素
        function createThoughtElement(content, timestamp) {
            const item = document.createElement('div');
            item.className = 'thought-item';

            const escapedContent = escapeHtml(content);
            const contentDiv = document.createElement('div');
            contentDiv.className = 'thought-content';
            contentDiv.innerHTML = escapedContent.replace(/\n/g, '<br>');

            const timeDiv = document.createElement('div');
            timeDiv.className = 'thought-time';
            timeDiv.textContent = timestamp;

            item.appendChild(contentDiv);
            item.appendChild(timeDiv);
            return item;
        }

        // 主功能逻辑
        document.getElementById('submitThoughts').addEventListener('click', function () {
            const textarea = document.getElementById('exchangeThoughts');
            const thoughts = textarea.value.trim();

            if (!thoughts) {
                alert('请输入交流心得内容！');
                return;
            }

            const timestamp = new Date().toLocaleString('zh-CN', {
                year: 'numeric', month: '2-digit', day: '2-digit',
                hour: '2-digit', minute: '2-digit', second: '2-digit'
            });

            // 使用安全的DOM操作创建元素，防止XSS
            const display = document.getElementById('thoughtsDisplay');
            const newThought = createThoughtElement(thoughts, timestamp);
            display.insertBefore(newThought, display.firstChild); // 新消息置顶

            // 清空输入框并获得焦点
            textarea.value = '';
            textarea.focus();

            // 可选：本地存储保存历史记录
            saveThoughtsLocally(thoughts, timestamp);
        });

        // 本地存储功能（可选）
        function saveThoughtsLocally(content, timestamp) {
            const thoughts = JSON.parse(localStorage.getItem('languageThoughts') || '[]');
            thoughts.unshift({ content, timestamp });
            // 只保留最近20条
            localStorage.setItem('languageThoughts', JSON.stringify(thoughts.slice(0, 20)));
        }

        // 页面加载时恢复历史记录
        function loadThoughtsLocally() {
            const thoughts = JSON.parse(localStorage.getItem('languageThoughts') || '[]');
            const display = document.getElementById('thoughtsDisplay');

            thoughts.forEach(({ content, timestamp }) => {
                const thoughtElement = createThoughtElement(content, timestamp);
                display.appendChild(thoughtElement);
            });
        }

        // Enter键提交（Shift+Enter换行）
        document.getElementById('exchangeThoughts').addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                document.getElementById('submitThoughts').click();
            }
        });

        // 页面加载完成后恢复历史记录
        window.addEventListener('load', loadThoughtsLocally);
    </script>
