### 1. 后端代码 (server.js) - 完整可运行版本

```javascript
const express = require('express');
const cookieParser = require('cookie-parser');
const cors = require('cors');
const path = require('path');
const app = express();
const PORT = process.env.PORT || 3000;

// 中间件
app.use(cors({
    origin: 'http://localhost:3001', // 前端地址
    credentials: true
}));
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());
app.use(express.static('public')); // 静态文件服务

// 模拟数据
const houses = [
    { id: 1, title: '现代公寓', location: '纽约市中心', price: 2500, image: '/images/house1.jpg', beds: 2, baths: 1, sqFt: 800 },
    { id: 2, title: '豪华别墅', location: '洛杉矶海滩', price: 4500, image: '/images/house2.jpg', beds: 4, baths: 3, sqFt: 2500 },
    { id: 3, title: '市区loft', location: '芝加哥', price: 1800, image: '/images/house3.jpg', beds: 1, baths: 1, sqFt: 600 }
];

const users = new Map(); // 模拟用户收藏数据

// 验证登录中间件
const authenticateUser = (req, res, next) => {
    const token = req.cookies.userToken;
    if (!token) {
        return res.status(401).json({ error: '请先登录' });
    }
    next();
};

// 用户登录
app.post('/api/login', (req, res) => {
    const { username, password } = req.body;
    if (username === 'test' && password === '123456') {
        res.cookie('userToken', 'validUserToken123', {
            httpOnly: true,
            secure: process.env.NODE_ENV === 'production',
            maxAge: 24 * 60 * 60 * 1000 // 24小时
        });
        res.json({ success: true, message: '登录成功' });
    } else {
        res.status(401).json({ success: false, message: '用户名或密码错误' });
    }
});

// 登出
app.post('/api/logout', (req, res) => {
    res.clearCookie('userToken');
    res.json({ success: true, message: '登出成功' });
});

// 检查登录状态
app.get('/api/check-auth', authenticateUser, (req, res) => {
    res.json({ authenticated: true });
});

// 房源搜索 - 支持多条件过滤
app.get('/api/houses/search', (req, res) => {
    const { location, minPrice, maxPrice, minBeds, maxBeds } = req.query;

    let filteredHouses = houses.filter(house => {
        const priceMatch = (!minPrice || house.price >= parseInt(minPrice)) &&
                          (!maxPrice || house.price <= parseInt(maxPrice));
        const bedMatch = (!minBeds || house.beds >= parseInt(minBeds)) &&
                        (!maxBeds || house.beds <= parseInt(maxBeds));
        const locationMatch = !location || house.location.toLowerCase().includes(location.toLowerCase());

        return priceMatch && bedMatch && locationMatch;
    });

    res.json({
        success: true,
        houses: filteredHouses,
        total: filteredHouses.length
    });
});

// 房源详情
app.get('/api/houses/:id', (req, res) => {
    const houseId = parseInt(req.params.id);
    const house = houses.find(h => h.id === houseId);

    if (!house) {
        return res.status(404).json({ error: '房源不存在' });
    }

    res.json({
        success: true,
        house: {
            ...house,
            description: '这是一套设施齐全的优质房源，位置优越，交通便利。',
            amenities: ['空调', '游泳池', '健身房', '停车位']
        }
    });
});

