app.get('/api/favorites', authenticateUser, (req, res) => {
    const token = req.cookies.userToken;
    const userFavorites = users.get(token) || [];
    const favoriteHouses = houses.filter(house => userFavorites.includes(house.id));
    res.json({ success: true, favorites: favoriteHouses });
});

// 收藏/取消收藏房源
app.post('/api/favorites/:houseId', authenticateUser, (req, res) => {
    const token = req.cookies.userToken;
    const houseId = parseInt(req.params.houseId);

    if (!users.has(token)) {
        users.set(token, []);
    }

    const userFavorites = users.get(token);
    const index = userFavorites.indexOf(houseId);

    if (index > -1) {
        // 取消收藏
        userFavorites.splice(index, 1);
        res.json({ success: true, action: 'removed', message: '已取消收藏' });
    } else {
