## 优化后的完整代码

```javascript
/**
 * 安全的动态公式编辑器 - Google Docs风格
 * 支持解析、验证、安全执行、错误处理和性能优化
 */
class FormulaEditor {
  constructor() {
    this.formulaCache = new Map(); // 公式缓存
    this.safeParams = ['x', 'y', 'z', 'a', 'b', 'c', 'd', 'e']; // 允许的参数
    this.maxComplexity = 100; // 最大计算复杂度阈值
  }

  /**
   * 解析并验证公式
   */
  parseFormula(formula) {
    if (!formula || typeof formula !== 'string') {
      throw new Error('公式必须是非空字符串');
    }

    // 去除首尾空白
    const cleanFormula = formula.trim();

    // 禁止危险关键字
    const forbiddenKeywords = ['eval', 'Function', 'constructor', 'import', 'export'];
    if (forbiddenKeywords.some(keyword => cleanFormula.includes(keyword))) {
      throw new Error('公式包含禁止的关键字');
    }

    // 验证参数使用
    const usedParams = [...cleanFormula.matchAll(/[a-zA-Z][a-zA-Z0-9]*/g)]
      .map(match => match[0])
      .filter(param => this.safeParams.includes(param.toLowerCase()));

    return {
      formula: cleanFormula,
      params: usedParams,
      paramCount: usedParams.length
    };
  }

  /**
   * 生成安全的计算函数
   */
  generateCalculator(parsedFormula) {
    const { formula, params } = parsedFormula;

    // 检查缓存
    const cacheKey = `${formula}_${params.sort().join(',')}`;
    if (this.formulaCache.has(cacheKey)) {
      return this.formulaCache.get(cacheKey);
    }

    // 构建安全的函数体
    const safeFormula = `
      try {
        ${this.generateSafeWrapper(formula)}
        return result;
      } catch (error) {
        throw new Error('公式计算错误: ' + error.message);
      }
    `;

    // 使用安全的参数列表
    const paramList = [...new Set(params)].join(', ');
    const calculator = new Function(paramList, safeFormula);

    // 缓存函数
    this.formulaCache.set(cacheKey, calculator);
    return calculator;
  }

  /**
   * 生成安全的公式包装器
   */
  generateSafeWrapper(formula) {
    // 添加安全限制和调试信息
    return `
      const startTime = Date.now();
      const maxIterations = 10000;

      // 安全计算包装
      let result;
      let iteration = 0;

      // 替换常见函数为安全版本
      const safeMath = {
        sum: (...args) => args.reduce((a, b) => a + b, 0),
        avg: (...args) => args.reduce((a, b) => a + b, 0) / args.length,
        max: (...args) => Math.max(...args),
        min: (...args) => Math.min(...args)
      };

      // 执行公式
      result = ${formula};

      // 复杂度检查
      if (Date.now() - startTime > 100 || iteration > maxIterations) {
        throw new Error('计算复杂度过高');
      }

      return Number(result) || 0;
    `;
  }

  /**
   * 执行公式计算（核心API）
   */
  calculate(formula, values) {
    // 1. 解析公式
    const parsed = this.parseFormula(formula);

    // 2. 验证参数匹配
    const requiredParams = parsed.params;
    const providedParams = Object.keys(values);

    if (requiredParams.length !== providedParams.length) {
      throw new Error(`参数数量不匹配。需要: [${requiredParams.join(', ')}], 提供: [${providedParams.join(', ')}]`);
    }

    // 3. 参数类型验证
    for (const param of requiredParams) {
      const value = values[param];
      if (typeof value !== 'number' || isNaN(value)) {
        throw new Error(`参数 ${param} 必须是有效数字，收到: ${value}`);
      }
    }

    // 4. 生成并执行计算器
    const calculator = this.generateCalculator(parsed);
    const result = calculator(...requiredParams.map(p => values[p]));

    return {
      success: true,
      formula,
      params: parsed.params,
      values,
      result: Number(result.toFixed(6)), // 精度控制
      executionTime: Date.now() // 微秒级性能监控
    };
  }

  /**
   * 批量计算（性能优化）
   */
  batchCalculate(formulas) {
    const results = [];
    for (const { formula, values } of formulas) {
      try {
        results.push(this.calculate(formula, values));
      } catch (error) {
        results.push({
          success: false,
          formula,
          values,
          error: error.message
        });
      }
    }
    return results;
  }

  /**
   * 公式验证（预检查）
   */
  validateFormula(formula) {
    try {
      const parsed = this.parseFormula(formula);
      this.generateCalculator(parsed);
      return { valid: true, parsed };
    } catch (error) {
      return { valid: false, error: error.message };
    }
  }
}

