  const result1 = editor.calculate("x * y + z", { x: 5, y: 10, z: 3 });
  console.log("✅ 单个计算结果:", result1);
  // 输出: { success: true, result: 53, ... }
} catch (error) {
  console.error("❌ 计算失败:", error.message);
}

// 2. 支持函数调用
try {
  const result2 = editor.calculate("sum(x, y, z) * 2", { x: 1, y: 2, z: 3 });
  console.log("✅ 函数调用结果:", result2);
} catch (error) {
  console.error("❌ 计算失败:", error.message);
}

// 3. 批量计算
const batchResults = editor.batchCalculate([
  { formula: "x + y", values: { x: 5, y: 10 } },
  { formula: "x * 2", values: { x: 7 } },
  { formula: "invalid", values: { x: 1 } } // 会捕获错误
]);
console.log("✅ 批量计算:", batchResults);

// 4. 公式验证
const validation = editor.validateFormula("a + b * c");
console.log("✅ 公式验证:", validation);

// 5. 性能测试
console.time("性能测试-1000次计算");
for (let i = 0; i < 1000; i++) {
  editor.calculate("x * y + z", { x: i % 10, y: 2, z: 3 });
}
console.timeEnd("性能测试-1000次计算");
