            questionContainer: document.getElementById('questionContainer'),
            submitBtn: document.getElementById('submitBtn') // 可选：提交按钮
        };

        // 绑定事件
        this.bindEvents();
    }

    /**
     * 绑定事件监听器
     */
    bindEvents() {
        if (this.elements.submitBtn) {
            this.elements.submitBtn.addEventListener('click', () => this.displayUserQuestion());
        }

        // 支持回车提交
        if (this.elements.userQuestion) {
            this.elements.userQuestion.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    this.displayUserQuestion();
                }
            });
        }
    }

    /**
     * 安全的显示用户问题
     */
    displayUserQuestion() {
        try {
            // 输入验证
            if (!this.elements.userQuestion || !this.elements.questionContainer) {
                console.error('DOM元素未找到');
                return;
            }

            const userInput = this.elements.userQuestion.value.trim();

            // 空输入检查
            if (!userInput) {
                this.showFeedback('请输入问题内容', 'error');
                return;
            }

            // 长度限制（防止过长内容影响性能）
            if (userInput.length > 1000) {
                this.showFeedback('内容过长，请精简到1000字以内', 'error');
                return;
            }

            // 安全显示：使用textContent防止XSS
            this.elements.questionContainer.textContent = userInput;

            // 清空输入框（可选）
            this.elements.userQuestion.value = '';

            // 成功反馈
            this.showFeedback('问题显示成功', 'success');

        } catch (error) {
            console.error('显示用户问题时出错:', error);
            this.showFeedback('操作失败，请重试', 'error');
        }
    }

    /**
     * 显示用户反馈信息
     * @param {string} message - 反馈消息
     * @param {'success'|'error'|'info'} type - 消息类型
     */
    showFeedback(message, type = 'info') {
        // 创建反馈元素
        const feedback = document.createElement('div');
        feedback.className = `feedback feedback-${type}`;
        feedback.textContent = message;

        // 插入到页面（假设有反馈容器，或插入到questionContainer前）
        const container = this.elements.questionContainer.parentNode;
        container.insertBefore(feedback, this.elements.questionContainer);

        // 3秒后自动移除
        setTimeout(() => {
            if (feedback.parentNode) {
                feedback.parentNode.removeChild(feedback);
            }
        }, 3000);
    }
}

