        function renderSafeContent() {
            const containers = ['info1', 'info2', 'info3'];
            containers.forEach((id, index) => {
                const container = document.getElementById(id);
                if (container && safeDisasterData[index]) {
                    // ✅ textContent自动转义，防止XSS
                    container.innerHTML = `
