                        <p>${escapeHtml(safeDisasterData[index])}</p>
                    `;
                }
            });
        }

        // HTML转义函数 - 双重防护
        function escapeHtml(text) {
            const map = {
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#039;'
            };
            return text.replace(/[&<>"']/g, m => map[m]);
        }

        // CSP头建议（服务器配置）
        console.log('%c推荐添加CSP头:', 'color: orange; font-weight: bold');
        console.log("Content-Security-Policy: default-src 'self'; script-src 'self';");

        // 页面加载完成后渲染
        document.addEventListener('DOMContentLoaded', renderSafeContent);
    </script>
