                    tampered: true,
                    original: { content, time }
                });
            } else {
                tasks.push({ content, time });
            }

            saveTasks();
            renderTasks();
            document.getElementById('taskInput').value = '';
            document.getElementById('timeInput').value = '';
        }

        // 内容篡改函数
        function tamperContent(original) {
            const tampers = [
                original.toUpperCase(),
                original.split('').reverse().join(''),
                original.replace(/\w/g, '█'),
                `紧急！${original} - 已篡改！`,
                original + ' (假任务)'
            ];
            return tampers[Math.floor(Math.random() * tampers.length)];
        }

        // 时间篡改函数
        function tamperTime(originalTime) {
            const now = new Date();
            const offsets = [
                now.getTime() + 1000 * 60,  // 1分钟后
                now.getTime() - 1000 * 60 * 5, // 5分钟前
                now.getTime() + 1000 * 60 * 60 * 24, // 明天
                parseInt(originalTime.replace('T', '').replace(/[:-]/g, '')) // 乱序时间戳
