class SmartHomePlatform {
  constructor() {
    this.devices = new Map(); // 设备状态存储
    this.trustedDomains = new Set([
      'https://api.mi.com',
      'https://developer.apple.com/homekit',
      'https://api.google.com/home',
      'https://platform.xiaomi.com'
    ]);
    this.pendingLoads = new Map(); // 防重复加载
