  // 处理设备消息
  handleDeviceMessage(data) {
    if (data.type === 'STATUS_UPDATE') {
      const device = this.devices.get(data.deviceId);
      if (device) {
        device.status = data.status;
        device.lastUpdate = Date.now();
        this.updateDeviceUI(data.deviceId);
      }
    }
  }

  // 渲染设备控制界面
  renderDeviceUI(deviceId) {
    const device = this.devices.get(deviceId);
    if (!device) return;

    const container = document.getElementById(`device-${deviceId}`);
    if (!container) {
      const div = document.createElement('div');
      div.id = `device-${deviceId}`;
      div.className = 'device-control';
      div.innerHTML = this.generateDeviceHTML(device);
      document.getElementById('controls').appendChild(div);
    }
  }

  // 生成设备控制HTML
  generateDeviceHTML(device) {
    const statusClass = device.status === 'on' ? 'status-on' : 'status-off';
    const statusText = device.status === 'on' ? '开启' : '关闭';

    return `
      <div class="device-card">
        <h3>${device.name}</h3>
        <div class="status ${statusClass}">${statusText}</div>
        <button onclick="window.platform.toggleDevice('${device.id}')">
          ${device.status === 'on' ? '关闭' : '开启'}
        </button>
        <div class="last-update">
          最后更新: ${new Date(device.lastUpdate).toLocaleTimeString()}
        </div>
      </div>
    `;
  }

  // 切换设备状态
  toggleDevice(deviceId) {
    const device = this.devices.get(deviceId);
    if (!device) return;

    const iframe = device.iframe;
    const newStatus = device.status === 'on' ? 'off' : 'on';

    // 通过postMessage发送控制命令
    iframe.contentWindow.postMessage({
      type: 'TOGGLE',
      status: newStatus
    }, '*');

    // 立即更新UI（乐观更新）
    device.status = newStatus;
    this.updateDeviceUI(deviceId);
  }

  // 更新设备UI
  updateDeviceUI(deviceId) {
    const container = document.getElementById(`device-${deviceId}`);
    if (container) {
      container.innerHTML = this.generateDeviceHTML(this.devices.get(deviceId));
    }
  }

  // 观察设备状态变化（MutationObserver）
  observeDeviceChanges() {
    const observer = new MutationObserver(() => {
      this.devices.forEach((device, id) => {
        this.renderDeviceUI(id);
      });
    });

    observer.observe(document.getElementById('controls'), {
      childList: true,
      subtree: true
    });
  }
}

