// 🔐 SVG安全清理函数 - 核心安全措施
function sanitizeSVG(svgElement) {
  // 1. 移除所有<style>元素（防止CSS注入）
  const styles = svgElement.querySelectorAll('style');
  styles.forEach(style => style.remove());

  // 2. 移除危险的全局属性
  const dangerousAttrs = [
    'onload', 'onerror', 'onclick', 'onmouseover', 'onfocus', 'onloadstart',
    'xmlns', 'xlink:href', 'href', 'style'
  ];

  // 遍历所有子元素进行深度清理
  function cleanElement(element) {
    dangerousAttrs.forEach(attr => {
      element.removeAttribute(attr);
    });

    // 只允许安全的外部引用（data URL）
    const links = element.querySelectorAll('[xlink\\:href], [href]');
    links.forEach(link => {
      const href = link.getAttribute('xlink:href') || link.getAttribute('href');
      if (href && !href.startsWith('data:') && href !== '#') {
        link.removeAttribute('xlink:href');
        link.removeAttribute('href');
      }
    });

    // 递归清理子元素
    Array.from(element.children).forEach(child => cleanElement(child));
  }

  cleanElement(svgElement);

  // 3. 添加CSP沙箱属性
  svgElement.setAttribute('sandbox', 'allow-same-origin');
}

