// 智能家居设备控制平台 - 外部资源动态加载管理器
class DeviceControlManager {
    constructor() {
        this.deviceResources = new Map();
        this.loadingPromises = new Map();
    }

    /**
     * 加载设备控制外部资源
     * @param {string} url - 外部JS资源URL
     * @param {string} deviceId - 设备ID
     * @returns {Promise<void>}
     */
    async loadDeviceControl(url, deviceId = 'default') {
        // 防止重复加载
        if (this.loadingPromises.has(deviceId)) {
            return this.loadingPromises.get(deviceId);
        }

        const promise = this._fetchAndExecuteScript(url, deviceId);
        this.loadingPromises.set(deviceId, promise);

        try {
            await promise;
            console.log(`✅ 设备 ${deviceId} 控制资源加载成功`);
            this._updateControlUI(deviceId);
        } catch (error) {
            console.error(`❌ 加载设备 ${deviceId} 外部资源失败:`, error);
            this._showErrorUI(deviceId, error.message);
        } finally {
            this.loadingPromises.delete(deviceId);
        }
    }

    /**
     * 核心加载和执行逻辑
     */
    async _fetchAndExecuteScript(url, deviceId) {
        const response = await fetch(url, {
            method: 'GET',
            headers: {
                'Cache-Control': 'no-cache'
            }
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const scriptContent = await response.text();
        this.deviceResources.set(deviceId, scriptContent);

        // 动态创建script标签执行外部JS
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.id = `device-control-${deviceId}`;
            script.textContent = scriptContent;
            script.onload = () => resolve();
            script.onerror = () => reject(new Error('脚本执行失败'));

            // 清理旧脚本
            const oldScript = document.getElementById(script.id);
            if (oldScript) {
                oldScript.remove();
            }

            document.head.appendChild(script);
        });
    }

    /**
     * 更新控制界面
     */
    _updateControlUI(deviceId) {
        const container = document.getElementById(`device-control-${deviceId}`);
        if (container) {
            container.classList.add('loaded');
            container.innerHTML = `
                <div class="device-status">
                    <h3>设备 ${deviceId} 已连接</h3>
                    <div class="control-panel">
                        <button onclick="toggleDevice('${deviceId}')">切换状态</button>
                        <span id="status-${deviceId}">待机中...</span>
                    </div>
                </div>
            `;
        }
    }

    /**
     * 显示错误界面
     */
    _showErrorUI(deviceId, errorMsg) {
        const container = document.getElementById(`device-control-${deviceId}`);
        if (container) {
            container.innerHTML = `
                <div class="error-panel">
                    <h3>设备 ${deviceId} 连接失败</h3>
                    <p>${errorMsg}</p>
                    <button onclick="retryLoad('${deviceId}')">重试</button>
                </div>
            `;
        }
    }

    /**
     * 实时监听设备状态变化并自动加载资源
     * @param {Array} devices - 设备列表 [{id, url, status}]
     */
    watchDeviceStatus(devices) {
        devices.forEach(device => {
            // 模拟实时状态变化监听
            this._simulateStatusChange(device);
        });
    }

    _simulateStatusChange(device) {
        // 模拟设备状态变化（实际项目中替换为WebSocket或轮询）
        setInterval(async () => {
            const randomStatus = Math.random() > 0.5 ? 'online' : 'offline';
            if (randomStatus === 'online' && !this.deviceResources.has(device.id)) {
                await this.loadDeviceControl(device.url, device.id);
            }
        }, 5000);
    }
}

