/**
 * 加载法律服务相关文档和案例内容的函数
 * @param {string|number} serviceId - 法律服务ID
 * @param {HTMLElement} container - 内容显示容器
 * @param {Object} options - 可选配置
 * @returns {Promise<void>}
 */
async function loadLegalContent(serviceId, container, options = {}) {
    const {
        baseUrl = 'https://example.com/legal_services',
        loadingText = '加载中...',
        errorText = '加载失败，请稍后重试',
        onSuccess = null,
        onError = null
    } = options;

    try {
        // 显示加载状态
        if (container) {
            container.innerHTML = `<div class="loading">${loadingText}</div>`;
        }

        const url = `${baseUrl}/${serviceId}.json`;
        const response = await fetch(url, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            cache: 'default'
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const data = await response.json();

        // 渲染内容到容器
        if (container && data.content) {
            renderLegalContent(container, data);
        }

        // 成功回调
        if (onSuccess) {
            onSuccess(data);
        }

        console.log('法律内容加载成功:', data);

    } catch (error) {
        console.error('加载法律内容失败:', error);

        if (container) {
            container.innerHTML = `<div class="error">${errorText}</div>`;
        }

        if (onError) {
            onError(error);
        }
    }
}

/**
 * 渲染法律内容到页面
 * @param {HTMLElement} container - 容器元素
 * @param {Object} data - 法律内容数据
 */
function renderLegalContent(container, data) {
    const { title, documents = [], cases = [], description } = data;

    let html = `
        <div class="legal-content">
            ${title ? `<h2 class="legal-title">${title}</h2>` : ''}
            ${description ? `<div class="legal-description">${description}</div>` : ''}

            ${documents.length ? `
                <section class="legal-documents">
                    <h3>相关法规</h3>
                    <ul>${documents.map(doc => 
                        `<li><a href="${doc.url}" target="_blank">${doc.name}</a></li>`
                    ).join('')}</ul>
                </section>
            ` : ''}

            ${cases.length ? `
                <section class="legal-cases">
                    <h3>相关案例</h3>
                    <div class="cases-grid">${cases.map(caseItem => 
                        `<div class="case-card">
                            <h4>${caseItem.title}</h4>
                            <p>${caseItem.summary}</p>
                            ${caseItem.judgement ? `<span class="judgement">${caseItem.judgement}</span>` : ''}
                        </div>`
                    ).join('')}</div>
                </section>
            ` : ''}
        </div>
    `;

    container.innerHTML = html;
}

/**
 * 服务选择事件处理
 */
function initLegalServiceSelector() {
    const serviceSelector = document.getElementById('service-selector');
    const contentContainer = document.getElementById('legal-content');

    if (!serviceSelector || !contentContainer) return;

    serviceSelector.addEventListener('change', async (event) => {
        const serviceId = event.target.value;
        if (!serviceId) return;

        await loadLegalContent(
            serviceId, 
            contentContainer, 
            {
                loadingText: '正在为您加载相关法律资料...',
                errorText: '加载法律资料失败，请检查网络连接',
                onSuccess: (data) => {
                    // 可以添加GA或其他分析
                    console.log(`服务 ${serviceId} 内容加载完成`);
                }
            }
        );
    });
}

// 页面加载完成后初始化
document.addEventListener('DOMContentLoaded', initLegalServiceSelector);

// 导出供其他模块使用
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { loadLegalContent, renderLegalContent, initLegalServiceSelector };
}
