        // 提交评论函数 - 核心逻辑
        function submitComment() {
            const commentInput = document.getElementById('commentInput');
            const commentDisplay = document.getElementById('commentDisplay');
            const submitButton = document.getElementById('submitButton');

            // 获取输入框内容并去除首尾空白
            const comment = commentInput.value.trim();

            if (comment === '') {
                alert('请输入评论内容！');
                return;
            }

            // 创建XML格式展示内容（安全处理）
            const xmlContent = createDisplayXML(comment);

            // 更新展示区域
            commentDisplay.textContent = xmlContent;
            commentDisplay.classList.remove('empty-state');

            // 清空输入框并聚焦
            commentInput.value = '';
            commentInput.focus();

            // 视觉反馈
            submitButton.textContent = '提交成功！';
            submitButton.style.backgroundColor = '#28a745';
            setTimeout(() => {
                submitButton.textContent = '提交评论';
                submitButton.style.backgroundColor = '#007bff';
            }, 1500);
        }

        // 创建安全的XML展示内容
        function createDisplayXML(comment) {
            // 转义特殊字符防止XSS
            const escapedComment = comment
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');

            return `<?xml version="1.0" encoding="UTF-8"?>
<display>
    <comment>${escapedComment}</comment>
</display>`;
        }

        // 事件绑定
        document.addEventListener('DOMContentLoaded', function() {
            const commentInput = document.getElementById('commentInput');
            const submitButton = document.getElementById('submitButton');

            // 按钮点击事件
            submitButton.addEventListener('click', submitComment);

            // Enter键提交（Ctrl+Enter）
            commentInput.addEventListener('keydown', function(e) {
                if (e.ctrlKey && e.key === 'Enter') {
                    submitComment();
                }
            });

            // 输入时自动调整高度
            commentInput.addEventListener('input', function() {
                this.style.height = 'auto';
                this.style.height = (this.scrollHeight) + 'px';
            });
        });
    </script>
