# 安全修复后的优化代码

## 关键修改点：
1. **移除恶意iframe** - 彻底删除潜在XSS攻击向量
2. **输入验证与转义** - 使用`textContent`和白名单过滤防止XSS
3. **事件委托优化** - 改进DOM操作性能
4. **错误处理** - 添加try-catch和用户反馈
5. **代码模块化** - 分离关注点，便于测试

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Online Publishing Platform - 安全版</title>
    <style>
        #commentDisplay { margin-top: 10px; padding: 10px; border: 1px solid #ddd; min-height: 50px; }
        .comment-item { margin: 10px 0; padding: 8px; background: #f9f9f9; border-left: 4px solid #007cba; }
        .error { color: red; font-size: 14px; }
        .success { color: green; font-size: 14px; }
    </style>
</head>
<body>
    <div id="articleContainer">
        <article>
            <h2>精彩文章标题</h2>
            <p>这是一篇很有深度的文章内容......</p>
            <textarea id="commentInput" placeholder="请输入文章评论" maxlength="500"></textarea>
            <button id="submitComment">提交评论</button>
            <div id="commentDisplay"></div>
            <div id="messageArea"></div>
        </article>
    </div>

    <script>
        class CommentManager {
            constructor() {
                this.commentContainer = document.getElementById('commentDisplay');
                this.input = document.getElementById('commentInput');
                this.submitBtn = document.getElementById('submitComment');
                this.messageArea = document.getElementById('messageArea');
                this.init();
            }

            init() {
                this.submitBtn.addEventListener('click', () => this.handleSubmit());
                this.input.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter' && e.ctrlKey) {
                        this.handleSubmit();
                    }
                });
            }

            // 安全输入清理函数 - 防止XSS
            sanitizeInput(input) {
                const div = document.createElement('div');
                div.textContent = input;
                return div.innerHTML.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
            }

            // 显示消息
            showMessage(message, type = 'info') {
                this.messageArea.innerHTML = `<div class="${type}">${message}</div>`;
                setTimeout(() => {
                    this.messageArea.innerHTML = '';
                }, 3000);
            }

            // 添加评论到DOM（安全方式）
            addComment(comment) {
                const sanitizedComment = this.sanitizeInput(comment);
                if (!sanitizedComment.trim()) {
                    this.showMessage('评论不能为空！', 'error');
                    return false;
                }

                if (sanitizedComment.length > 500) {
                    this.showMessage('评论过长，请控制在500字以内！', 'error');
                    return false;
                }

                const commentDiv = document.createElement('div');
                commentDiv.className = 'comment-item';
                commentDiv.innerHTML = `
                    <strong>用户评论:</strong> 
                    <span>${sanitizedComment}</span>
                    <button class="like-btn" data-commentid="${Date.now()}">👍 点赞</button>
                `;

                this.commentContainer.appendChild(commentDiv);
                return true;
            }

            handleSubmit() {
                try {
                    const comment = this.input.value.trim();

                    if (this.addComment(comment)) {
                        this.input.value = '';
                        this.showMessage('评论提交成功！', 'success');

                        // 安全处理评论列表（事件委托）
                        this.attachCommentListeners();
                    }
                } catch (error) {
                    console.error('评论提交失败:', error);
                    this.showMessage('提交失败，请重试！', 'error');
                }
            }

            attachCommentListeners() {
                // 使用事件委托，避免重复绑定
                this.commentContainer.addEventListener('click', (e) => {
                    if (e.target.classList.contains('like-btn')) {
                        const likes = parseInt(e.target.textContent.match(/\d+/)?.[0] || 0) + 1;
                        e.target.textContent = `👍 ${likes} 赞`;
                    }
                });
            }
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            new CommentManager();
        });
    </script>
</body>
</html>
```

