<body>
    <!-- 输入区域 -->
    <div class="input-container">
        <textarea 
            class="input-area" 
            id="contentInput" 
            placeholder="分享你的动态吧！支持文字、图片链接、视频链接..."
            maxlength="1000"
        ></textarea>
        <button class="submit-btn" onclick="submitPost()">发布动态</button>
    </div>

    <!-- 动态列表 -->
    <ul class="post-list" id="postList"></ul>

    <script>
        // 全局数据存储
        let posts = JSON.parse(localStorage.getItem('socialPosts')) || [];
        let postIdCounter = parseInt(localStorage.getItem('postIdCounter')) || 0;

        // 初始化：渲染已有动态
        renderPosts();

        // 提交动态
        function submitPost() {
            const contentInput = document.getElementById('contentInput');
            const content = contentInput.value.trim();

            // 输入验证
            if (!content) {
                alert('请输入内容！');
                contentInput.focus();
                return;
            }

            if (content.length > 1000) {
                alert('内容不能超过1000字符！');
                return;
            }

            // 创建新动态
            const newPost = {
                id: ++postIdCounter,
                content: content,
                timestamp: Date.now(),
                author: `用户${Math.floor(Math.random() * 1000) + 1}`
            };

            // 添加到数据存储
            posts.unshift(newPost); // 新动态插到最前面

            // 持久化存储
            localStorage.setItem('socialPosts', JSON.stringify(posts));
            localStorage.setItem('postIdCounter', postIdCounter);

            // 清空输入并重新渲染
            contentInput.value = '';
            contentInput.style.height = '100px';
            renderPosts();
        }

        // 渲染所有动态
        function renderPosts() {
            const postList = document.getElementById('postList');

            if (posts.length === 0) {
                postList.innerHTML = `
                    <div class="empty-state">
                        <div style="font-size: 48px; margin-bottom: 16px;">📱</div>
                        <p>还没有动态，快来发布第一条吧！</p>
                    </div>
                `;
                return;
            }

            postList.innerHTML = posts.map(post => createPostHTML(post)).join('');
        }

        // 创建单条动态HTML
        function createPostHTML(post) {
            const timeAgo = formatTimeAgo(post.timestamp);
            const { textContent, mediaHTML } = parseContent(post.content);

            return `
                <li class="post-item">
                    <div class="post-header">
                        <div class="post-author">${post.author}</div>
                        <div class="post-time">${timeAgo}</div>
                    </div>
                    <div class="post-content">
                        ${textContent ? `<div class="post-text">${escapeHtml(textContent)}</div>` : ''}
                        ${mediaHTML}
                    </div>
                </li>
            `;
        }

