<body>
    <!-- 示例课程页面结构 -->
    <div id="course-container">
        <h1 id="course-title" data-course-id="12345">JavaScript高级编程</h1>
        <div id="course-info">
            <span id="course-teacher">张老师</span>
            <span id="course-price">¥299</span>
            <span id="course-duration">20小时</span>
