    <script>
        class CourseIntegrityVerifier {
            constructor(options = {}) {
                this.options = {
                    selectors: [
                        '#course-title',
                        '#course-teacher', 
                        '#course-price',
                        '#course-duration',
                        '#course-content'
                    ],
                    serverVerifyUrl: '/api/course/integrity/verify',
                    toleranceThreshold: 0.1, // 10%容忍度
                    ...options
                };
                this.baselineHash = null;
                this.currentHash = null;
                this.isVerified = false;
            }

            // 计算DOM元素的序列化哈希
            serializeElement(element) {
                if (!element) return '';

                const walker = document.createTreeWalker(
                    element,
                    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT
                );

                let content = '';
                let node;

                while (node = walker.nextNode()) {
                    if (node.nodeType === Node.TEXT_NODE) {
                        content += node.textContent.trim();
                    } else if (node.nodeType === Node.ELEMENT_NODE) {
                        // 只包含关键属性
                        const attrs = ['data-*', 'class', 'id'].reduce((acc, attr) => {
                            if (attr === 'data-*') {
                                Array.from(node.attributes).forEach(attr => {
                                    if (attr.name.startsWith('data-')) {
                                        acc += `${attr.name}=${attr.value};`;
                                    }
                                });
                            } else {
                                const attrValue = node.getAttribute(attr);
                                if (attrValue) acc += `${attr}=${attrValue};`;
                            }
                            return acc;
                        }, '');
                        content += `<${node.tagName.toLowerCase()}${attrs}>`;
                    }
                }
                return content;
            }

            // 计算完整性哈希
            calculatePageHash() {
                let combinedContent = '';

                this.options.selectors.forEach(selector => {
                    const element = document.querySelector(selector);
                    if (element) {
                        combinedContent += this.serializeElement(element);
                    }
                });

                // 添加时间戳防止缓存攻击
                combinedContent += `|${Date.now()}`;

                return CryptoJS.SHA256(combinedContent).toString();
            }

            // 相似度计算（编辑距离算法优化版）
            similarityScore(hash1, hash2) {
                if (hash1 === hash2) return 1.0;

                // 简化的哈希距离计算
                let diffCount = 0;
                const maxLen = Math.max(hash1.length, hash2.length);

                for (let i = 0; i < maxLen; i++) {
                    if (hash1[i] !== hash2[i]) diffCount++;
                }

                return 1 - (diffCount / maxLen);
            }

            // 验证完整性
            async verifyIntegrity() {
                try {
                    this.currentHash = this.calculatePageHash();

                    if (!this.baselineHash) {
                        // 首次运行，建立基准哈希（实际应从服务器获取）
                        this.baselineHash = await this.fetchBaselineHash();
                    }

                    const similarity = this.similarityScore(this.baselineHash, this.currentHash);

                    console.log(`完整性校验: ${similarity.toFixed(4)}`);

                    if (similarity < this.options.toleranceThreshold) {
                        await this.handleTamperDetected();
                        return false;
                    }

                    this.isVerified = true;
                    console.log('✅ 页面完整性验证通过');
                    return true;

                } catch (error) {
                    console.error('验证失败:', error);
                    return false;
                }
            }

            // 从服务器获取基准哈希
            async fetchBaselineHash() {
                const courseId = document.querySelector('[data-course-id]')?.dataset.courseId;
                if (!courseId) throw new Error('未找到课程ID');

                const response = await fetch(`${this.options.serverVerifyUrl}?courseId=${courseId}`, {
                    method: 'GET',
                    headers: { 'X-Requested-With': 'XMLHttpRequest' }
                });

                if (!response.ok) throw new Error('获取基准哈希失败');

                const data = await response.json();
                return data.baselineHash;
            }

            // 处理篡改检测
            async handleTamperDetected() {
                console.error('🚨 检测到页面篡改！');

                // 立即上报
                await fetch('/api/security/tamper-detected', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        courseId: document.querySelector('[data-course-id]')?.dataset.courseId,
                        baselineHash: this.baselineHash,
                        currentHash: this.currentHash,
                        userAgent: navigator.userAgent,
                        url: window.location.href
                    })
                });

                // 页面保护措施
                this.protectPage();
            }

            // 页面保护
            protectPage() {
                // 禁用交互
                document.body.style.pointerEvents = 'none';
                document.body.innerHTML += `
                    <div style="
                        position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
                        background: rgba(0,0,0,0.9); z-index: 9999; color: white; 
                        display: flex; align-items: center; justify-content: center; font-size: 24px;
                    ">
                        <div>检测到安全异常，请刷新页面或联系管理员</div>
                    </div>
                `;
            }

            // 定时重新验证
            startContinuousVerification(interval = 5000) {
                this.verifyIntegrity();

                setInterval(() => {
                    if (this.isVerified) {
                        this.verifyIntegrity();
                    }
                }, interval);
            }

            // 监听DOM变化
            startDOMWatch() {
                const observer = new MutationObserver((mutations) => {
                    let hasCriticalChange = false;

                    mutations.forEach((mutation) => {
                        if (mutation.type === 'childList' || mutation.type === 'characterData') {
                            const target = mutation.target;
                            // 检查是否关键元素被修改
                            if (this.options.selectors.some(selector => 
                                target.matches?.(selector) || target.closest?.(selector)
                            )) {
                                hasCriticalChange = true;
                            }
                        }
                    });

                    if (hasCriticalChange) {
                        console.warn('DOM变化检测，重新验证...');
                        this.verifyIntegrity();
                    }
                });

                observer.observe(document.body, {
                    childList: true,
                    subtree: true,
                    characterData: true,
                    attributes: true,
                    attributeFilter: ['class', 'id', 'data-*']
                });
            }
        }

        // 初始化验证器
        document.addEventListener('DOMContentLoaded', () => {
            const verifier = new CourseIntegrityVerifier({
                serverVerifyUrl: '/api/course/integrity/verify'
            });

            // 页面加载完成立即验证
            verifier.verifyIntegrity()
                .then(verified => {
                    if (verified) {
                        // 启动持续监控
                        verifier.startContinuousVerification(3000);
                        verifier.startDOMWatch();
                    }
                });
        });
    </script>
