function encryptPaymentData($plaintext, $key) {
    $iv = openssl_random_pseudo_bytes($IV_LENGTH);
    $encrypted = openssl_encrypt($plaintext, 'AES-256-CBC', $key, OPENSSL_RAW_DATA, $iv);

    if ($encrypted === false) {
        throw new Exception('加密失败: ' . openssl_error_string());
    }

    // IV + 密文 (Base64编码便于数据库存储)
    return base64_encode($iv . $encrypted);
}

/**
 * 解密支付数据
 */
function decryptPaymentData($encryptedData, $key) {
    $data = base64_decode($encryptedData);
    if ($data === false || strlen($data) < $IV_LENGTH) {
        throw new Exception('无效的加密数据');
    }

    $iv = substr($data, 0, $IV_LENGTH);
    $encrypted = substr($data, $IV_LENGTH);

    $decrypted = openssl_decrypt($encrypted, 'AES-256-CBC', $key, OPENSSL_RAW_DATA, $iv);

    if ($decrypted === false) {
        throw new Exception('解密失败: ' . openssl_error_string());
    }

    return rtrim($decrypted, "\0"); // 移除PKCS7填充
}

