<?php
session_start();

// 配置
define('SESSION_TIMEOUT', 30 * 60); // 30分钟
define('MAX_LOGIN_ATTEMPTS', 5);
define('LOGIN_BLOCK_TIME', 15 * 60); // 15分钟

// 安全过滤函数
function sanitize_input($data) {
    return htmlspecialchars(strip_tags(trim($data)), ENT_QUOTES, 'UTF-8');
}

// 检查是否被锁定
function check_login_lock($username) {
    if (!isset($_SESSION['login_attempts'][$username])) {
        return false;
    }

    $attempts = $_SESSION['login_attempts'][$username];
    if ($attempts['count'] >= MAX_LOGIN_ATTEMPTS && 
        (time() - $attempts['time']) < LOGIN_BLOCK_TIME) {
        return true;
    }
    return false;
}

// 清理过期尝试记录
function cleanup_attempts($username) {
    if (isset($_SESSION['login_attempts'][$username])) {
        $attempts = $_SESSION['login_attempts'][$username];
        if ((time() - $attempts['time']) > LOGIN_BLOCK_TIME) {
            unset($_SESSION['login_attempts'][$username]);
        }
    }
}

// 模拟用户验证（实际项目中替换为数据库验证）
