    $users = [
        'admin' => password_hash('admin123', PASSWORD_DEFAULT),
        'user' => password_hash('password123', PASSWORD_DEFAULT)
    ];

    if (!isset($users[$username])) {
        return false;
    }

    return password_verify($password, $users[$username]);
}

