$error_class = '';

if ($_SERVER["REQUEST_METHOD"] == "POST") {
    $username = sanitize_input($_POST['username'] ?? '');
    $password = $_POST['password'] ?? '';

    // 检查锁定状态
    cleanup_attempts($username);
    if (check_login_lock($username)) {
        $login_message = "账户已被锁定，请" . (LOGIN_BLOCK_TIME / 60) . "分钟后重试";
        $error_class = 'error';
    } else {
