```php
<?php
// 配置数据库连接信息
define('DB_HOST', 'localhost');
define('DB_USER', 'your_db_user');
define('DB_PASS', 'your_db_password');
define('DB_NAME', 'your_database');

// 启动会话
session_start();

// 验证请求方法
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    die('Method not allowed');
}

// 输入验证和清理
$username = trim($_POST['username'] ?? '');
$password = $_POST['password'] ?? '';
$email = trim($_POST['email'] ?? '');

// 验证必填字段
$errors = [];
if (empty($username)) {
    $errors[] = '用户名不能为空';
}
if (empty($password)) {
    $errors[] = '密码不能为空';
}
if (empty($email)) {
    $errors[] = '邮箱不能为空';
}

// 验证格式
if (!empty($username) && (strlen($username) < 3 || strlen($username) > 20 || !preg_match('/^[a-zA-Z0-9_]+$/', $username))) {
    $errors[] = '用户名必须为3-20位字母、数字或下划线';
}
if (!empty($password) && strlen($password) < 6) {
    $errors[] = '密码长度至少6位';
}
if (!empty($email) && !filter_var($email, FILTER_VALIDATE_EMAIL)) {
    $errors[] = '邮箱格式不正确';
}

// 如果有错误，显示并退出
if (!empty($errors)) {
    $_SESSION['errors'] = $errors;
    header('Location: register.php');
    exit;
}

try {
    // 数据库连接（使用PDO，更安全）
    $pdo = new PDO(
        "mysql:host=" . DB_HOST . ";dbname=" . DB_NAME . ";charset=utf8mb4",
        DB_USER,
        DB_PASS,
        [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES => false
        ]
    );

    // 检查用户名和邮箱是否已存在
    $checkStmt = $pdo->prepare("SELECT id FROM users WHERE username = ? OR email = ?");
    $checkStmt->execute([$username, $email]);

    if ($checkStmt->fetch()) {
        $_SESSION['errors'] = ['用户名或邮箱已被注册'];
        header('Location: register.php');
        exit;
    }

    // 密码哈希
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    // 插入用户数据（预处理语句防SQL注入）
    $stmt = $pdo->prepare("INSERT INTO users (username, email, password, created_at) VALUES (?, ?, ?, NOW())");
    $result = $stmt->execute([$username, $email, $hashedPassword]);

    if ($result) {
        $_SESSION['success'] = '注册成功！请登录。';
        header('Location: login.php');
    } else {
        throw new Exception('注册失败');
    }

} catch (PDOException $e) {
    error_log('Database error: ' . $e->getMessage());
    $_SESSION['errors'] = ['系统错误，请稍后重试'];
    header('Location: register.php');
} catch (Exception $e) {
    $_SESSION['errors'] = [$e->getMessage()];
    header('Location: register.php');
}
?>
