## 优化后的代码

```php
<?php
class User {
    public $id;
    public $username;
    public $role;

    public function __construct($id, $username, $role) {
        $this->id = $id;
        $this->username = $username;
        $this->role = $role;
    }

    public function getRole() {
        return $this->role;
    }

    public function isStudent() {
        return $this->role === 'student';
    }

    public function isTeacher() {
        return $this->role === 'teacher';
    }
}

class Course {
    public $courseId;
    public $title;
    public $content;
    public $teacherId;

    public function __construct($courseId, $title, $content, $teacherId) {
        $this->courseId = $courseId;
        $this->title = $title;
        $this->content = $content;
        $this->teacherId = $teacherId;
    }

    public function getTeacherId() {
        return $this->teacherId;
    }
}

class EducationPlatform {
    private $users = [];
    private $courses = [];
    private $userMap = [];  // 优化：用户ID到用户的映射，提高查找效率

    public function addUser($id, $username, $role) {
        if (isset($this->userMap[$id])) {
            throw new Exception("用户ID {$id} 已存在");
        }
        $user = new User($id, $username, $role);
        $this->users[] = $user;
        $this->userMap[$id] = $user;  // O(1)查找
    }

    public function addCourse($courseId, $title, $content, $teacherId) {
        if (!$this->userExists($teacherId)) {
            throw new Exception("教师ID {$teacherId} 不存在");
        }
        if ($this->courseExists($courseId)) {
            throw new Exception("课程ID {$courseId} 已存在");
        }
        $course = new Course($courseId, $title, $content, $teacherId);
        $this->courses[] = $course;
    }

    /**
     * 获取课程内容 - 严格权限控制
     * @param int $userId 用户ID
     * @param int $courseId 课程ID
     * @return Course|null
     * @throws Exception
     */
    public function getCourse($userId, $courseId) {
        if (!$this->userExists($userId)) {
            throw new Exception("用户ID {$userId} 不存在");
        }

        $user = $this->userMap[$userId];

        foreach ($this->courses as $course) {
            if ($course->courseId == $courseId) {
                // 严格权限检查：教师只能访问自己的课程，学生可以访问所有课程
                if ($user->isTeacher() && $course->getTeacherId() != $userId) {
                    throw new PermissionDeniedException("无权限访问此课程");
                }
                return $course;
            }
        }
        throw new Exception("课程ID {$courseId} 不存在");
    }

    /**
     * 获取用户的所有课程（教师：自己的课程；学生：所有课程）
     */
    public function getUserCourses($userId) {
        if (!$this->userExists($userId)) {
            throw new Exception("用户ID {$userId} 不存在");
        }

        $user = $this->userMap[$userId];
        $accessibleCourses = [];

        foreach ($this->courses as $course) {
            if ($user->isStudent() || $course->getTeacherId() == $userId) {
                $accessibleCourses[] = $course;
            }
        }
        return $accessibleCourses;
    }

    /**
     * 检查用户是否存在
     */
    private function userExists($userId) {
        return isset($this->userMap[$userId]);
    }

    /**
     * 检查课程是否存在
     */
    private function courseExists($courseId) {
        foreach ($this->courses as $course) {
            if ($course->courseId == $courseId) {
                return true;
            }
        }
        return false;
    }
}

/**
 * 自定义权限异常
 */
class PermissionDeniedException extends Exception {}

/**
 * 测试代码
 */
