    $course = $platform->getCourse(2, 101);
    echo "学生可以访问课程: " . $course->title . "\n";
} catch (Exception $e) {
    echo "错误: " . $e->getMessage() . "\n";
}

echo "\n=== 测试教师访问自己的课程 ===\n";
try {
    $course = $platform->getCourse(1, 101);
    echo "教师可以访问自己的课程: " . $course->title . "\n";
} catch (Exception $e) {
    echo "错误: " . $e->getMessage() . "\n";
}

echo "\n=== 测试教师访问其他课程（应失败） ===\n";
