<?php
// 数据库连接配置
define('DB_HOST', 'localhost');
define('DB_USER', 'user');
define('DB_PASS', 'password');
define('DB_NAME', 'database');

// 错误处理函数
function handleDbError($error_type, $error_msg = '') {
    error_log("数据库{$error_type}: {$error_msg}");
    http_response_code(500);
    die('系统繁忙，请稍后重试');
}

try {
    // 数据库连接
    $mysqli = new mysqli(DB_HOST, DB_USER, DB_PASS, DB_NAME);

    // 设置字符集
    $mysqli->set_charset("utf8mb4");

    // 检查连接
    if ($mysqli->connect_error) {
        handleDbError('连接失败', $mysqli->connect_error);
    }

    // 执行查询
    $query = "SELECT * FROM posts WHERE id = 1";
    $result = $mysqli->query($query);

    // 检查查询是否成功
    if (!$result) {
        handleDbError('查询失败', $mysqli->error);
    }

    echo "查询成功";

} catch (Exception $e) {
    handleDbError('异常', $e->getMessage());
} finally {
    // 关闭连接
    if (isset($mysqli) && $mysqli instanceof mysqli) {
        $mysqli->close();
    }
}
?>
```

