## 优化后的安全文件上传代码

```php
<?php
// 配置上传参数
$allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'application/zip'];
$maxFileSize = 10 * 1024 * 1024; // 10MB
$uploadDir = 'uploads/';
$fileExtBlacklist = ['php', 'phtml', 'php3', 'php4', 'php5', 'pl', 'py', 'jsp', 'asp', 'sh', 'cgi'];

if ($_SERVER['REQUEST_METHOD'] == 'POST') {
    // 创建上传目录
    if (!is_dir($uploadDir)) {
        mkdir($uploadDir, 0755, true);
    }

    $file = $_FILES['courseFile'];

    // 详细错误检查和输出（仅用于开发环境）
    $errors = [];

    // 1. 检查是否选择了文件
    if ($file['error'] === UPLOAD_ERR_NO_FILE) {
        $errors[] = "错误: 未选择文件 (UPLOAD_ERR_NO_FILE)";
    }

    // 2. 检查上传错误
    if ($file['error'] !== UPLOAD_ERR_OK) {
        $errorMessages = [
            UPLOAD_ERR_INI_SIZE => "文件超过服务器最大上传限制 (upload_max_filesize)",
            UPLOAD_ERR_FORM_SIZE => "文件超过表单最大上传限制 (MAX_FILE_SIZE)",
            UPLOAD_ERR_PARTIAL => "文件只上传了一部分 (UPLOAD_ERR_PARTIAL)",
            UPLOAD_ERR_NO_TMP_DIR => "缺少临时目录 (UPLOAD_ERR_NO_TMP_DIR)",
            UPLOAD_ERR_CANT_WRITE => "无法写入文件到磁盘 (UPLOAD_ERR_CANT_WRITE)",
            UPLOAD_ERR_EXTENSION => "上传被PHP扩展阻止 (UPLOAD_ERR_EXTENSION)"
        ];
        $errors[] = "上传错误: " . ($errorMessages[$file['error']] ?? '未知错误 ' . $file['error']);
    }

    // 3. 检查文件大小
    if ($file['size'] > $maxFileSize) {
        $errors[] = "错误: 文件过大，最大允许 " . ($maxFileSize/1024/1024) . "MB";
    }

    // 4. 检查MIME类型
    $finfo = finfo_open(FILEINFO_MIME_TYPE);
    $mimeType = finfo_file($finfo, $file['tmp_name']);
    finfo_close($finfo);

    if (!in_array($mimeType, $allowedTypes)) {
        $errors[] = "错误: 不允许的文件类型。检测到MIME: $mimeType，允许: " . implode(', ', $allowedTypes);
    }

    // 5. 检查文件扩展名（双重验证）
    $fileExt = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
    if (in_array($fileExt, $fileExtBlacklist)) {
        $errors[] = "错误: 禁止的扩展名: $fileExt";
    }

    // 6. 生成安全的文件名
    $safeName = preg_replace('/[^a-zA-Z0-9._-]/', '_', basename($file['name']));
    $safeName = uniqid() . '_' . $safeName;
    $uploadFile = $uploadDir . $safeName;

    // 7. 检查目标文件是否可写
    if (file_exists($uploadFile)) {
        $errors[] = "错误: 目标文件已存在: $safeName";
    }

    // 如果没有错误，执行上传
    if (empty($errors)) {
        if (move_uploaded_file($file['tmp_name'], $uploadFile)) {
            // 设置安全权限
            chmod($uploadDir . $safeName, 0644);
            echo "✅ 文件上传成功: $safeName<br>";
            echo "文件大小: " . number_format($file['size']) . " bytes<br>";
            echo "MIME类型: $mimeType";
        } else {
            $errors[] = "移动文件失败。检查目录权限: " . is_writable($uploadDir) ? '可写' : '不可写';
        }
    }

    // 输出所有详细错误信息
    if (!empty($errors)) {
        echo "<div style='color: red; background: #fee; padding: 10px; border: 1px solid red;'>";
        echo "<h3>❌ 上传失败 - 详细错误信息:</h3><ul>";
        foreach ($errors as $error) {
            echo "<li>$error</li>";
        }
        echo "</ul>";

        // 额外调试信息
        echo "<h4>调试信息:</h4>";
        echo "<ul>";
        echo "<li>原始文件名: " . htmlspecialchars($file['name']) . "</li>";
        echo "<li>临时文件: " . htmlspecialchars($file['tmp_name']) . "</li>";
        echo "<li>文件大小: " . $file['size'] . " bytes</li>";
        echo "<li>错误代码: " . $file['error'] . "</li>";
        echo "<li>上传目录可写: " . (is_writable($uploadDir) ? '是' : '否') . "</li>";
        echo "</ul></div>";
    }
} else {
    // 显示上传表单
    echo '
    <form method="post" enctype="multipart/form-data">
        <h3>课程文件上传</h3>
        <input type="file" name="courseFile" accept=".pdf,.jpg,.jpeg,.png,.zip" required>
        <br><br>
        <input type="submit" value="上传文件">
    </form>
    ';
}
?>
```

