        $phone = trim(filter_input(INPUT_POST, 'phone', FILTER_SANITIZE_STRING));

        // 输入验证
        $errors = [];

        // 姓名验证：长度2-50字符，中文/英文
        if (empty($name) || !preg_match('/^[\x{4e00}-\x{9fa5}a-zA-Z\s]{2,50}$/u', $name)) {
            $errors[] = "姓名必须是2-50个中文或英文字符";
        }

        // 邮箱验证
        if (empty($email) || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
            $errors[] = "请输入有效的电子邮件地址";
        }

        // 电话号码验证：支持中国大陆手机号和座机
        if (empty($phone) || !preg_match('/^1[3-9]\d{9}$|^(0\d{2,3}-?)?\d{7,8}$/', $phone)) {
            $errors[] = "请输入有效的电话号码";
        }

        if (empty($errors)) {
            // 准备安全的数据格式
            $timestamp = date('Y-m-d H:i:s');
            $data = sprintf(
                "[%s]\n姓名: %s\n邮箱: %s\n电话: %s\n---\n",
                $timestamp,
                htmlspecialchars($name, ENT_QUOTES, 'UTF-8'),
                htmlspecialchars($email, ENT_QUOTES, 'UTF-8'),
                htmlspecialchars($phone, ENT_QUOTES, 'UTF-8')
            );

            // 安全写入文件（原子操作）
            if (file_put_contents("user_data.txt", $data, FILE_APPEND | LOCK_EX) !== false) {
                // 提交成功，重置CSRF令牌
                $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
                $_SESSION['success_message'] = "您的信息已成功提交！";
            } else {
                throw new Exception("数据保存失败");
            }
        } else {
            $_SESSION['error_messages'] = $errors;
        }

    } catch (Exception $e) {
        $_SESSION['error_messages'] = ["提交失败：" . $e->getMessage()];
        // 记录错误日志（生产环境）
        error_log("表单提交错误: " . $e->getMessage());
    }

    // 重定向防止重复提交
    header("Location: " . $_SERVER['PHP_SELF']);
    exit();
}
