## 优化后代码

```php
<?php
// 引入TCPDF库
require_once('tcpdf_include.php');

/**
 * 安全的金融票据PDF生成器
 * 防止数据篡改，所有关键字段硬编码或严格验证
 */
class SecureInvoicePDF extends TCPDF {

    private $invoiceData;

    public function __construct($invoiceData = []) {
        parent::__construct();
        $this->invoiceData = $this->sanitizeInvoiceData($invoiceData);
    }

    // 数据清理和验证
    private function sanitizeInvoiceData($data) {
        $defaults = [
            'invoiceNumber' => 'F' . str_pad(rand(100000, 999999), 9, '0', STR_PAD_LEFT),
            'issueDate' => date('Y-m-d'),
            'amount' => 0.00,
            'amountInWords' => '零元整',
            'payee' => '默认收款人',
            'payer' => '默认付款方',
            'paymentMethod' => '银行转账',
            'validUntil' => date('Y-m-d', strtotime('+1 year'))
        ];

        // 只允许预定义字段，严格过滤
        $allowed = array_keys($defaults);
        foreach ($allowed as $key) {
            if (isset($data[$key])) {
                $value = $this->cleanInput($data[$key], $key);
                $defaults[$key] = $value;
            }
        }
        return $defaults;
    }

    // 输入清理函数
    private function cleanInput($input, $field) {
        $input = trim(htmlspecialchars($input, ENT_QUOTES, 'UTF-8'));
        switch ($field) {
            case 'invoiceNumber':
                return preg_replace('/[^A-Z0-9]/', '', strtoupper($input));
            case 'amount':
                $amount = floatval($input);
                return $amount >= 0 ? $amount : 0;
            case 'payee':
            case 'payer':
                return mb_strlen($input, 'UTF-8') > 50 ? mb_substr($input, 0, 50, 'UTF-8') : $input;
            default:
                return $input;
        }
    }

    public function Header() {
        $this->SetFont('helvetica', 'B', 18);
        $this->SetFillColor(240, 240, 240);
        $this->Cell(0, 12, '【金融票据】', 1, 1, 'C', true);
        $this->Ln(2);
    }

    public function Footer() {
        $this->SetY(-20);
        $this->SetFont('helvetica', 'I', 9);
        $this->SetFillColor(200, 220, 255);
        $this->Cell(0, 12, '第 ' . $this->PageNo() . ' 页  |  生成时间: ' . date('Y-m-d H:i:s'), 1, 0, 'C', true);
    }

    public function generate() {
        $this->AddPage('P', 'A4');
        $this->SetFont('helvetica', '', 12);
        $this->SetMargins(20, 30, 20);

        // 票据基本信息表格
        $this->SetFillColor(248, 248, 255);
        $this->SetTextColor(0, 0, 100);

        $fields = [
            '票据编号' => $this->invoiceData['invoiceNumber'],
            '出票日期' => $this->invoiceData['issueDate'],
            '收款人' => $this->invoiceData['payee'],
            '付款方' => $this->invoiceData['payer'],
            '付款方式' => $this->invoiceData['paymentMethod']
        ];

        foreach ($fields as $label => $value) {
            $this->Cell(40, 8, $label . ':', 1, 0, 'L', true);
            $this->Cell(0, 8, $value, 1, 1, 'L');
        }

        // 金额突出显示
        $this->Ln(5);
        $this->SetFont('helvetica', 'B', 16);
        $this->SetFillColor(255, 235, 200);
        $this->Cell(45, 12, '金额(数字)', 1, 0, 'L', true);
        $this->Cell(0, 12, '¥ ' . number_format($this->invoiceData['amount'], 2), 1, 1, 'C');

        $this->SetFont('helvetica', 'B', 14);
        $this->SetFillColor(255, 245, 220);
        $this->Cell(45, 12, '金额(大写)', 1, 0, 'L', true);
        $this->Cell(0, 12, $this->invoiceData['amountInWords'], 1, 1, 'C');

        // 有效期和防伪标记
        $this->SetFont('helvetica', '', 11);
        $this->Cell(45, 8, '有效期至', 1, 0, 'L', true);
        $this->Cell(0, 8, $this->invoiceData['validUntil'], 1, 1, 'C');

        // 防伪水印
        $this->SetAlpha(0.1);
        $this->SetFont('helvetica', 'B', 60);
        $this->RotatedText(60, 100, '正式票据', 45);
        $this->SetAlpha(1.0);
    }

    // 旋转文本水印
    private function RotatedText($x, $y, $txt, $angle) {
        $this->StartTransform();
        $this->Rotate($angle, $x, $y);
        $this->Text($x, $y, $txt);
        $this->StopTransform();
    }
}

// 使用示例（安全方式）
