```php
<?php
/**
 * 完整的文件上传处理类 - 安全的CMS文件上传系统
 * 支持多文件上传、文件类型验证、大小限制、唯一文件名生成
 */

class FileUploader {
    private $uploadDir;
    private $allowedTypes = [
        'image' => ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'],
        'document' => ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'],
        'video' => ['mp4', 'avi', 'mov', 'wmv', 'flv', 'webm'],
        'audio' => ['mp3', 'wav', 'ogg', 'flac']
    ];
    private $maxFileSize = 10 * 1024 * 1024; // 10MB
    private $maxWidth = 1920;
    private $maxHeight = 1080;

    public function __construct($uploadDir = 'uploads/') {
        $this->uploadDir = $this->normalizePath($uploadDir);
        $this->createUploadDir();
    }

    /**
     * 处理单文件或多文件上传
     */
    public function handleUpload($inputName = 'file') {
        $uploadResult = [
            'success' => false,
            'files' => [],
            'errors' => []
        ];

        if (!isset($_FILES[$inputName])) {
            $uploadResult['errors'][] = '没有找到上传文件';
            return $uploadResult;
        }

        $files = $this->normalizeFilesArray($_FILES[$inputName]);

        foreach ($files as $file) {
            $result = $this->uploadSingleFile($file);
            $uploadResult['files'][] = $result;

            if (!$result['success']) {
                $uploadResult['errors'] = array_merge($uploadResult['errors'], $result['errors']);
            }
        }

        $uploadResult['success'] = empty($uploadResult['errors']);
        return $uploadResult;
    }

    /**
     * 上传单个文件
     */
    private function uploadSingleFile($file) {
        $result = [
            'success' => false,
            'original_name' => '',
            'file_path' => '',
            'file_url' => '',
            'file_size' => 0,
            'mime_type' => '',
            'errors' => []
        ];

        // 基本验证
        if ($file['error'] !== UPLOAD_ERR_OK) {
            $result['errors'][] = $this->getUploadErrorMessage($file['error']);
            return $result;
        }

        $result['original_name'] = $file['name'];
        $result['file_size'] = $file['size'];
        $result['mime_type'] = $file['type'];

        // 文件大小验证
        if ($file['size'] > $this->maxFileSize) {
            $result['errors'][] = '文件大小超过限制 (' . $this->formatBytes($this->maxFileSize) . ')';
            return $result;
        }

        // MIME类型和扩展名验证
        $extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
        if (!$this->isAllowedType($extension)) {
            $result['errors'][] = '不支持的文件类型: ' . $extension;
            return $result;
        }

        // 生成唯一文件名
        $uniqueFilename = $this->generateUniqueFileName($file['name']);
        $filePath = $this->uploadDir . $uniqueFilename;

        // 移动文件
        if (!move_uploaded_file($file['tmp_name'], $filePath)) {
            $result['errors'][] = '文件上传失败';
            return $result;
        }

        // 图像尺寸验证
        if (in_array($extension, $this->allowedTypes['image']) && !$this->validateImageSize($filePath)) {
            unlink($filePath); // 删除不符合尺寸的图片
            $result['errors'][] = '图片尺寸超过限制 (' . $this->maxWidth . 'x' . $this->maxHeight . ')';
            return $result;
        }

        $result['success'] = true;
        $result['file_path'] = $filePath;
        $result['file_url'] = str_replace($_SERVER['DOCUMENT_ROOT'], '', $filePath);
        return $result;
    }

    /**
     * 优化后的唯一文件名生成函数
     */
    private function generateUniqueFileName($originalFileName) {
        $extension = strtolower(pathinfo($originalFileName, PATHINFO_EXTENSION));
        $basename = pathinfo($originalFileName, PATHINFO_FILENAME);

        // 清理文件名中的非法字符
        $basename = preg_replace('/[^a-zA-Z0-9_\-\.]/', '_', $basename);

        // 使用时间戳 + 随机数 + 文件名哈希生成唯一名
        $timestamp = time();
        $random = substr(str_shuffle('0123456789abcdefghijklmnopqrstuvwxyz'), 0, 8);
        $hash = substr(md5($basename . $timestamp), 0, 8);

        return "{$timestamp}_{$random}_{$hash}.{$extension}";
    }

    /**
     * 标准化文件数组（支持多文件上传）
     */
    private function normalizeFilesArray($files) {
        if ($files['name'] === '') {
            return [$files];
        }

        $normalized = [];
        $count = count($files['name']);

        for ($i = 0; $i < $count; $i++) {
            $normalized[] = [
                'name' => $files['name'][$i],
                'type' => $files['type'][$i],
                'tmp_name' => $files['tmp_name'][$i],
                'error' => $files['error'][$i],
                'size' => $files['size'][$i]
            ];
        }

        return $normalized;
    }

    /**
     * 创建上传目录
     */
    private function createUploadDir() {
        if (!is_dir($this->uploadDir)) {
            mkdir($this->uploadDir, 0755, true);
        }
    }

    /**
     * 标准化路径
     */
    private function normalizePath($path) {
        $path = rtrim($path, '/') . '/';
        return $path;
    }

    /**
     * 验证文件类型
     */
    private function isAllowedType($extension) {
        foreach ($this->allowedTypes as $types) {
            if (in_array($extension, $types)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 验证图片尺寸
     */
    private function validateImageSize($filePath) {
        $imageInfo = getimagesize($filePath);
        if (!$imageInfo) return true;

        return $imageInfo[0] <= $this->maxWidth && $imageInfo[1] <= $this->maxHeight;
    }

    /**
     * 获取上传错误信息
     */
    private function getUploadErrorMessage($errorCode) {
        $messages = [
            UPLOAD_ERR_INI_SIZE => '文件超过服务器限制',
            UPLOAD_ERR_FORM_SIZE => '文件超过表单限制',
            UPLOAD_ERR_PARTIAL => '文件只上传了一部分',
            UPLOAD_ERR_NO_FILE => '没有选择文件',
            UPLOAD_ERR_NO_TMP_DIR => '缺少临时目录',
            UPLOAD_ERR_CANT_WRITE => '无法写入文件',
            UPLOAD_ERR_EXTENSION => '上传被扩展阻止'
        ];
        return $messages[$errorCode] ?? '未知错误';
    }

    /**
     * 格式化字节大小
     */
    private function formatBytes($bytes, $precision = 2) {
        $units = ['B', 'KB', 'MB', 'GB'];
        for ($i = 0; $bytes > 1024 && $i < count($units) - 1; $i++) {
            $bytes /= 1024;
        }
        return round($bytes, $precision) . ' ' . $units[$i];
    }

    /**
     * 获取允许的文件类型
     */
    public function getAllowedTypes() {
        return $this->allowedTypes;
    }

    /**
     * 设置最大文件大小
     */
    public function setMaxFileSize($size) {
        $this->maxFileSize = $size;
    }
}

// 使用示例
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $uploader = new FileUploader('uploads/');

    // 可选：自定义配置
    // $uploader->setMaxFileSize(5 * 1024 * 1024); // 5MB

    $result = $uploader->handleUpload('files'); // 支持多文件，input name="files[]"

    if ($result['success']) {
        echo json_encode([
            'success' => true,
            'message' => '上传成功',
            'files' => $result['files']
        ]);
