<?php
session_start();

// 配置
define('MAX_SUBMISSIONS_PER_MINUTE', 5);
define('DATA_FILE', 'user_data.txt');
define('LOG_FILE', 'submission_log.txt');

// CSRF令牌验证
function verifyCSRF($token) {
    return isset($_SESSION['csrf_token']) && hash_equals($_SESSION['csrf_token'], $token);
}

// 速率限制检查
function checkRateLimit($ip) {
    $key = 'rate_' . md5($ip);
    $count = $_SESSION[$key] ?? 0;
    $time = $_SESSION[$key . '_time'] ?? time();

    if (time() - $time > 60) { // 重置计数
        $_SESSION[$key] = 1;
        $_SESSION[$key . '_time'] = time();
        return true;
    }

    if ($count >= MAX_SUBMISSIONS_PER_MINUTE) {
        return false;
    }

    $_SESSION[$key]++;
    return true;
}

// 输入验证函数
function validateInput($name, $email, $phone) {
    return [
        'name' => preg_match('/^[\p{Han}A-Za-z\s]{2,20}$/u', trim($name)),
        'email' => filter_var($email, FILTER_VALIDATE_EMAIL) && strlen($email) <= 100,
        'phone' => preg_match('/^1[3-9]\d{9}$/', $phone)
    ];
}

// 生成CSRF令牌
if (!isset($_SESSION['csrf_token'])) {
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
}

$message = '';
$error = '';

if ($_SERVER["REQUEST_METHOD"] == "POST") {
    $clientIP = $_SERVER['REMOTE_ADDR'] ?? 'unknown';

    // 1. 速率限制检查
