function getProductIdFromCartItem($item) {
    // 通过引用获取商品ID
    foreach ($_SESSION['cart'] as $id => $cartItem) {
        if ($cartItem === $item) return $id;
    }
    return null;
}

// 初始化购物车
if (!isset($_SESSION['cart'])) {
    $_SESSION['cart'] = [];
