<?php
/**
 * PayPal克隆支付平台 - 用户注册功能
 * 包含密码加密存储和登录尝试记录
 */

class UserAuth {
    private $pdo;

    public function __construct($pdo) {
        $this->pdo = $pdo;
    }

    /**
     * 注册新用户
     */
    public function registerUser(string $email, string $password): array {
        try {
            // 验证邮箱格式
            if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
                throw new InvalidArgumentException('无效的邮箱格式');
            }

            // 检查邮箱是否已存在
            if ($this->emailExists($email)) {
                throw new InvalidArgumentException('邮箱已注册');
            }

            // 使用password_hash进行加密存储 (bcrypt算法)
            $hashed_password = password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);

            $user_data = [
                'email' => $email,
                'password' => $hashed_password,
                'created_at' => date('Y-m-d H:i:s'),
                'updated_at' => date('Y-m-d H:i:s')
            ];

            // 插入数据库
            $stmt = $this->pdo->prepare("
                INSERT INTO users (email, password, created_at, updated_at) 
                VALUES (:email, :password, :created_at, :updated_at)
            ");
            $stmt->execute($user_data);

            $user_data['id'] = $this->pdo->lastInsertId();

            // 记录注册登录尝试
            $this->logLoginAttempt($email, true, '注册成功');

            return $user_data;

        } catch (Exception $e) {
            $this->logLoginAttempt($email, false, $e->getMessage());
            throw $e;
        }
    }

    /**
     * 检查邮箱是否已存在
     */
    private function emailExists(string $email): bool {
        $stmt = $this->pdo->prepare("SELECT COUNT(*) FROM users WHERE email = :email");
        $stmt->execute(['email' => $email]);
        return $stmt->fetchColumn() > 0;
    }

    /**
     * 记录登录尝试
     */
    private function logLoginAttempt(string $email, bool $success, string $message): void {
        $stmt = $this->pdo->prepare("
            INSERT INTO login_attempts (email, success, message, attempt_time) 
            VALUES (:email, :success, :message, :attempt_time)
        ");
        $stmt->execute([
            'email' => $email,
            'success' => $success ? 1 : 0,
            'message' => $message,
            'attempt_time' => date('Y-m-d H:i:s')
        ]);
    }

    /**
     * 验证用户登录
     */
    public function verifyLogin(string $email, string $password): ?array {
        $stmt = $this->pdo->prepare("SELECT id, email, password FROM users WHERE email = :email");
        $stmt->execute(['email' => $email]);
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($user && password_verify($password, $user['password'])) {
            $this->logLoginAttempt($email, true, '登录成功');
            unset($user['password']);
            return $user;
        }

        $this->logLoginAttempt($email, false, '密码错误');
        return null;
    }
}

// 数据库配置和初始化
try {
    $pdo = new PDO('mysql:host=localhost;dbname=paypal_clone', 'username', 'password', [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false
    ]);

    // 创建必要的表结构
    $pdo->exec("
        CREATE TABLE IF NOT EXISTS users (
            id INT AUTO_INCREMENT PRIMARY KEY,
            email VARCHAR(255) UNIQUE NOT NULL,
            password VARCHAR(255) NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        )
    ");

    $pdo->exec("
        CREATE TABLE IF NOT EXISTS login_attempts (
            id INT AUTO_INCREMENT PRIMARY KEY,
            email VARCHAR(255) NOT NULL,
            success TINYINT(1) NOT NULL,
            message TEXT,
            attempt_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_email (email),
            INDEX idx_time (attempt_time)
        )
    ");

    $auth = new UserAuth($pdo);

    // 示例调用
    try {
        $user_data = $auth->registerUser("user@example.com", "securepassword123");
        echo "注册成功: " . json_encode($user_data, JSON_UNESCAPED_UNICODE) . "\n";

        // 测试登录
        $login_result = $auth->verifyLogin("user@example.com", "securepassword123");
        echo "登录结果: " . ($login_result ? '成功' : '失败') . "\n";

    } catch (InvalidArgumentException $e) {
        echo "注册失败: " . $e->getMessage() . "\n";
    }

} catch (PDOException $e) {
    echo "数据库连接失败: " . $e->getMessage() . "\n";
