function uploadFile($uploadedFile, $path) {
    $baseDir = './uploads/'; // 相对路径，更安全
    $cleanPath = preg_replace('/[^a-zA-Z0-9\/_\-\.]/', '', $path); // 严格清理
    $cleanPath = ltrim($cleanPath, '/'); // 移除开头的/
    $uploadPath = $baseDir . $cleanPath;

    // 防止路径遍历
    if (strpos(realpath($uploadPath) ?? '', realpath($baseDir)) !== 0) {
        throw new Exception('非法路径');
    }

    // 创建目录
    $dir = dirname($uploadPath);
    if (!is_dir($dir) && !mkdir($dir, 0755, true)) {
        throw new Exception("无法创建目录: $dir");
    }

    // 检查文件类型（可选）
    $allowedTypes = ['jpg', 'png', 'pdf', 'txt', 'docx'];
    $extension = strtolower(pathinfo($uploadPath, PATHINFO_EXTENSION));
    if (!in_array($extension, $allowedTypes)) {
        throw new Exception('不支持的文件类型');
    }

    if (!$uploadedFile->moveTo($uploadPath)) {
        throw new Exception('文件移动失败');
    }

    return $uploadPath;
}
