## 优化后的PHP单元测试代码

```php
<?php

use PHPUnit\Framework\TestCase;

interface CSPPolicyInterface {
    public function allowsInlineScripts(): bool;
    public function getPolicyString(): string;
}

/**
 * 改进的CSP服务 - 支持nonce和哈希的安全内联脚本
 */
class SecureCSPService implements CSPPolicyInterface {
    private bool $allowInlineScripts;
    private array $nonceList = [];
    private array $scriptHashes = [];

    public function __construct(bool $allowInlineScripts = false) {
        $this->allowInlineScripts = $allowInlineScripts;
    }

    public function addNonce(string $nonce): self {
        $this->nonceList[] = $nonce;
        return $this;
    }

    public function addScriptHash(string $scriptContent): self {
        $hash = base64_encode(hash('sha256', $scriptContent, true));
        $this->scriptHashes[] = "'sha256-{$hash}'";
        return $this;
    }

    public function allowsInlineScripts(): bool {
        return $this->allowInlineScripts;
    }

    public function getPolicyString(): string {
        $basePolicy = "default-src 'self';";
        $scriptSrc = $this->buildScriptSrc();
        return $basePolicy . " " . $scriptSrc;
    }

    private function buildScriptSrc(): string {
        $scriptSrc = "script-src 'self'";

        if ($this->allowInlineScripts) {
            $scriptSrc .= " 'unsafe-inline'";
        } elseif (!empty($this->nonceList)) {
            $nonces = implode(' ', array_map(fn($n) => "'nonce-{$n}'", $this->nonceList));
            $scriptSrc .= " {$nonces}";
        } elseif (!empty($this->scriptHashes)) {
            $scriptSrc .= ' ' . implode(' ', $this->scriptHashes);
        }

        return $scriptSrc . ";";
    }
}

/**
 * 改进的页面服务 - 模拟真实的前端脚本生成
 */
class SecurePageService {
    private CSPPolicyInterface $cspService;

    public function __construct(CSPPolicyInterface $cspService) {
        $this->cspService = $cspService;
    }

    public function renderPage(string $nonce = '', string $inlineScript = ''): string {
        $cspHeader = $this->cspService->getPolicyString();
        $scriptTag = '';

        if ($nonce && !$this->cspService->allowsInlineScripts()) {
            $scriptTag = "<script nonce=\"{$nonce}\">{$inlineScript}</script>";
        } elseif ($inlineScript && $this->cspService->allowsInlineScripts()) {
            $scriptTag = "<script>{$inlineScript}</script>";
        } else {
            $scriptTag = "<script src=\"/static/edu-player.js\"></script>";
        }

        return "<!DOCTYPE html><html><head>
            <meta http-equiv='Content-Security-Policy' content='{$cspHeader}'>
        </head><body>{$scriptTag}</body></html>";
    }

    public function isSecureAgainstXSS(string $pageContent, string $maliciousPayload): bool {
        // 模拟浏览器CSP检查
        $hasUnsafeInline = strpos($pageContent, "'unsafe-inline'") !== false;
        $containsPayload = strpos($pageContent, $maliciousPayload) !== false;
        return !$hasUnsafeInline || !$containsPayload;
    }
}

/**
 * 全面的CSP安全测试套件
 */
class SecureCSPServiceTest extends TestCase {

    public function testUnsafeInlineScriptsAreDetected(): void {
        $cspService = new SecureCSPService(true);
        $pageService = new SecurePageService($cspService);

        $pageContent = $pageService->renderPage('', 'console.log("Inline script")');

        $this->assertStringContainsString("'unsafe-inline'", $pageContent, "应检测到不安全的内联脚本策略");
        $this->assertStringContainsString("Inline script", $pageContent);
    }

    public function testNonceBasedInlineScripts(): void {
        $nonce = bin2hex(random_bytes(16));
        $cspService = (new SecureCSPService(false))->addNonce($nonce);
        $pageService = new SecurePageService($cspService);

        $pageContent = $pageService->renderPage($nonce, 'playVideo();');

        $this->assertStringContainsString("nonce-{$nonce}", $pageContent);
        $this->assertStringNotContainsString("'unsafe-inline'", $pageContent);
        $this->assertStringContainsString("playVideo()", $pageContent);
    }

    public function testScriptHashProtection(): void {
        $trustedScript = "initializeCoursePlayer();";
        $cspService = (new SecureCSPService(false))->addScriptHash($trustedScript);
        $pageService = new SecurePageService($cspService);

        $pageContent = $pageService->renderPage('', $trustedScript);

        $this->assertStringContainsString('sha256-', $pageContent);
        $this->assertStringNotContainsString("'unsafe-inline'", $pageContent);
        $this->assertStringContainsString($trustedScript, $pageContent);
    }

    public function testXSSProtection(): void {
        $maliciousPayload = "<script>alert('XSS')</script>";
        $cspService = new SecureCSPService(false); // 不允许内联脚本
        $pageService = new SecurePageService($cspService);

        $pageContent = $pageService->renderPage('', $maliciousPayload);

        $this->assertStringNotContainsString("'unsafe-inline'", $pageContent);
        $this->assertTrue($pageService->isSecureAgainstXSS($pageContent, $maliciousPayload));
    }

    /**
     * @dataProvider cspConfigurationProvider
     */
    public function testVariousCSPConfigurations(
        bool $allowInline, 
        string $nonce, 
        string $expectedPolicyFragment
    ): void {
        $cspService = new SecureCSPService($allowInline);
        if ($nonce) {
            $cspService->addNonce($nonce);
        }

        $policy = $cspService->getPolicyString();
        $this->assertStringContainsString($expectedPolicyFragment, $policy);
    }

    public function cspConfigurationProvider(): array {
        return [
            'Unsafe Inline Allowed' => [true, '', "'unsafe-inline'"],
            'Nonce Protected' => [false, 'abc123', 'nonce-abc123'],
            'Strict Policy' => [false, '', "script-src 'self'"],
        ];
    }

    public function testProductionEnvironmentPolicy(): void {
        // 模拟生产环境 - 必须使用安全策略
        $cspService = new SecureCSPService(false);
        $policy = $cspService->getPolicyString();

        $this->assertStringNotContainsString("'unsafe-inline'", $policy);
        $this->assertStringContainsString("script-src 'self'", $policy);
    }
}
```

## 关键优化点

