```php
<?php
interface DatabaseConnectionInterface {
    public function prepare(string $query): mysqli_stmt|false;
    public function close(): bool;
}

class PaymentService {
    private DatabaseConnectionInterface $connection;
    private string $logPrefix = 'PaymentService';

    public function __construct(DatabaseConnectionInterface $connection = null) {
        $this->connection = $connection ?? $this->createDefaultConnection();
    }

    private function createDefaultConnection(): DatabaseConnectionInterface {
        return new class implements DatabaseConnectionInterface {
            private mysqli $mysqli;
            public function __construct() {
                $this->mysqli = new mysqli("localhost", "root", "", "payment_system");
            }
            public function prepare(string $query): mysqli_stmt|false {
                return $this->mysqli->prepare($query);
            }
            public function close(): bool {
                return $this->mysqli->close();
            }
        };
    }

    public function processPayment(int $userId, float $amount, string $paymentMethod): bool {
        if ($userId <= 0 || $amount < 0 || empty(trim($paymentMethod))) {
            error_log("{$this->logPrefix}: Invalid parameters - userId: {$userId}, amount: {$amount}, method: '{$paymentMethod}'");
            return false;
        }

        $stmt = $this->connection->prepare(
            "INSERT INTO payments (user_id, amount, payment_method, created_at) VALUES (?, ?, ?, NOW())"
        );

        if (!$stmt) {
            error_log("{$this->logPrefix}: Database prepare failed: " . $this->connection->error);
            return false;
        }

        $result = $stmt->bind_param("ids", $userId, $amount, $paymentMethod) && $stmt->execute();
        $stmt->close();

        if (!$result) {
            error_log("{$this->logPrefix}: Payment record failed for user: {$userId}");
            return false;
        }

        // 业务支付逻辑
        if ($amount <= 0) {
            error_log("{$this->logPrefix}: Payment failed - invalid amount: {$amount} for user: {$userId}");
            return false;
        }

        return true;
    }
}
?>
```

