<?php
declare(strict_types=1);

use PHPUnit\Framework\TestCase;

class PaymentServiceTest extends TestCase
{
    private MockDatabaseConnection $mockConnection;
    private PaymentService $paymentService;

    protected function setUp(): void
    {
        $this->mockConnection = new MockDatabaseConnection();
        $this->paymentService = new PaymentService($this->mockConnection);
    }

    /** @test */
    public function it_returns_true_for_valid_positive_amount_payment(): void
    {
        // Arrange
        $this->mockConnection->setPrepareSuccess(true);
        $this->mockConnection->setExecuteSuccess(true);

        // Act
        $result = $this->paymentService->processPayment(123, 100.50, 'credit_card');

        // Assert
        $this->assertTrue($result);
        $this->assertEquals(1, $this->mockConnection->getPrepareCallCount());
        $this->assertEquals(1, $this->mockConnection->getExecuteCallCount());
        $this->assertEquals([123, 100.50, 'credit_card'], $this->mockConnection->getLastBindParams());
    }

    /** @test */
    public function it_returns_false_for_zero_amount(): void
    {
        // Arrange
        $this->mockConnection->setPrepareSuccess(true);
        $this->mockConnection->setExecuteSuccess(true);

        // Act
        $result = $this->paymentService->processPayment(123, 0.0, 'credit_card');

        // Assert
        $this->assertFalse($result);
        $this->assertEquals(1, $this->mockConnection->getPrepareCallCount()); // Still tries to insert
    }

    /** @test */
    public function it_returns_false_for_negative_amount(): void
    {
        // Act & Assert
        $result = $this->paymentService->processPayment(123, -10.0, 'credit_card');
        $this->assertFalse($result);
        $this->assertEquals(0, $this->mockConnection->getPrepareCallCount()); // Input validation prevents DB call
    }

    /** @test */
    public function it_returns_false_for_invalid_user_id(): void
    {
        // Act & Assert
        $result = $this->paymentService->processPayment(0, 100.0, 'credit_card');
        $this->assertFalse($result);
        $this->assertEquals(0, $this->mockConnection->getPrepareCallCount());
    }

    /** @test */
    public function it_returns_false_for_empty_payment_method(): void
    {
        // Act & Assert
        $result = $this->paymentService->processPayment(123, 100.0, '');
        $this->assertFalse($result);
        $this->assertEquals(0, $this->mockConnection->getPrepareCallCount());
    }

    /** @test */
    public function it_returns_false_on_database_prepare_failure(): void
    {
        // Arrange
        $this->mockConnection->setPrepareSuccess(false);

        // Act
        $result = $this->paymentService->processPayment(123, 100.0, 'credit_card');

        // Assert
        $this->assertFalse($result);
        $this->assertEquals(1, $this->mockConnection->getPrepareCallCount());
    }

    /** @test */
    public function it_returns_false_on_database_execute_failure(): void
    {
        // Arrange
        $this->mockConnection->setPrepareSuccess(true);
        $this->mockConnection->setExecuteSuccess(false);

        // Act
        $result = $this->paymentService->processPayment(123, 100.0, 'credit_card');

        // Assert
        $this->assertFalse($result);
        $this->assertEquals(1, $this->mockConnection->getExecuteCallCount());
    }
}

class MockDatabaseConnection implements DatabaseConnectionInterface
{
    private bool $prepareSuccess = true;
    private bool $executeSuccess = true;
    private array $bindParams = [];
    private int $prepareCallCount = 0;
    private int $executeCallCount = 0;

    public function setPrepareSuccess(bool $success): void
    {
        $this->prepareSuccess = $success;
    }

    public function setExecuteSuccess(bool $success): void
    {
        $this->executeSuccess = $success;
    }

    public function prepare(string $query): mysqli_stmt|false
    {
        $this->prepareCallCount++;
        return $this->prepareSuccess ? new MockStatement($this) : false;
    }

    public function getPrepareCallCount(): int
    {
        return $this->prepareCallCount;
    }

    public function getExecuteCallCount(): int
    {
        return $this->executeCallCount;
    }

    public function getLastBindParams(): array
    {
        return $this->bindParams;
    }

    public function close(): bool
    {
        return true;
    }
}

class MockStatement
{
    private MockDatabaseConnection $mockConnection;
    private array $params = [];

    public function __construct(MockDatabaseConnection $mockConnection)
    {
        $this->mockConnection = $mockConnection;
    }

    public function bind_param(string $types, ...$vars): bool
    {
        $this->params = $vars;
        $this->mockConnection->bindParams = $vars;
        return true;
    }

    public function execute(): bool
    {
        $this->mockConnection->executeCallCount++;
        return $this->mockConnection->executeSuccess;
    }

    public function close(): bool
    {
        return true;
    }
}
?>
