/**
 * 评论渲染服务 - 安全HTML净化器
 */
class CommentService {
    private const ALLOWED_TAGS = [
        'b', 'i', 'u', 'strong', 'em', 'br', 'p', 'a', 'img'
    ];

    private const ALLOWED_ATTRS = [
        'a' => ['href', 'title', 'target'],
        'img' => ['src', 'alt', 'title', 'width', 'height']
    ];

    /**
     * 安全渲染评论内容
     */
    public function renderComment(Comment $comment): string {
        $content = trim($comment->getContent());

        // 空内容检查
        if (empty($content)) {
            return '<p>评论内容不能为空</p>';
        }

        // 检查常见XSS攻击模式
        if ($this->containsXssPattern($content)) {
            return '<p>评论包含不安全内容，已被屏蔽</p>';
        }

        // 转换换行符并净化HTML
        $content = nl2br($content);
        return $this->purifyHtml($content);
    }

    /**
     * 检查XSS攻击模式
     */
    private function containsXssPattern(string $content): bool {
        $xssPatterns = [
            '/<script\b/i',
            '/javascript\s*:/i',
            '/on\w+\s*=/i',
            '/vbscript\s*:/i',
            '/data\s*:/i',
            '/expression\s*\(/i'
        ];

        foreach ($xssPatterns as $pattern) {
            if (preg_match($pattern, $content)) {
                return true;
            }
        }
        return false;
    }

    /**
     * 净化HTML，只允许白名单标签和属性
     */
    private function purifyHtml(string $html): string {
        $dom = new DOMDocument();
        $dom->formatOutput = false;

        // 加载HTML（忽略解析错误）
        if (!$dom->loadHTML('<?xml encoding="UTF-8">' . $html, LIBXML_HTML_NOIMPLIED | LIBXML_HTML_NODEFDTD)) {
            return htmlspecialchars($html, ENT_QUOTES, 'UTF-8');
        }

        $xpath = new DOMXPath($dom);
        $elements = $xpath->query('//*');

        foreach ($elements as $element) {
            $tagName = strtolower($element->tagName);

            // 非允许标签，直接移除
            if (!in_array($tagName, self::ALLOWED_TAGS, true)) {
                $element->parentNode->replaceChild($element->ownerDocument->createTextNode($element->textContent), $element);
                continue;
            }

            // 清理不允许的属性
            $allowedAttrs = self::ALLOWED_ATTRS[$tagName] ?? [];
            $attributes = [];

            foreach ($element->attributes as $attr) {
                if (in_array($attr->name, $allowedAttrs, true)) {
                    $value = $attr->value;
                    // 清理危险的href/src值
                    $value = $this->sanitizeUrl($tagName, $attr->name, $value);
                    $attributes[] = $attr->name . '="' . htmlspecialchars($value, ENT_QUOTES, 'UTF-8') . '"';
                }
            }

            // 重建安全属性
            $element->removeAttributeNode(...$element->attributes);
            foreach ($attributes as $attrStr) {
                list($name, $value) = explode('=', $attrStr, 2);
                $element->setAttribute(trim($name), trim($value, '"'));
            }
        }

        $body = $dom->getElementsByTagName('body')->item(0);
        return $body ? $body->ownerDocument->saveHTML($body) : '';
    }

    /**
     * 清理URL属性值
     */
    private function sanitizeUrl(string $tag, string $attr, string $url): string {
        // 禁止javascript: 等协议
        if (preg_match('/^(javascript|vbscript|data):/i', $url)) {
            return '#';
        }

        // img标签允许相对路径和data URI（表情）
        if ($tag === 'img' && $attr === 'src') {
            return $url;
        }

        // a标签只允许http/https
        if ($tag === 'a' && $attr === 'href') {
            if (!preg_match('/^https?:\/\//i', $url)) {
                return '#';
            }
        }

        return $url;
    }
}

