## 关键安全问题修复

**原代码存在严重安全漏洞：**
1. 无文件类型验证（可上传恶意脚本）
2. 无文件名验证（目录穿越）
3. 无大小限制
4. 无权限控制（其他用户可访问所有文件）
5. 上传目录权限未验证

## 优化后的安全代码

```php
<?php
class ProductImageUploader {
    private $allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    private $maxFileSize = 5 * 1024 * 1024; // 5MB
    private $uploadDir = __DIR__ . '/uploads/products/';
    private $publicUrlBase = '/uploads/products/';

    public function uploadProductImage($userId) {
        if (!isset($_FILES['productImage']) || $_FILES['productImage']['error'] !== UPLOAD_ERR_OK) {
            throw new Exception('文件上传失败: ' . $_FILES['productImage']['error']);
        }

        $file = $_FILES['productImage'];

        // 1. 验证文件大小
        if ($file['size'] > $this->maxFileSize) {
            throw new Exception('文件大小超过5MB限制');
        }

        // 2. 验证文件类型
        $finfo = finfo_open(FILEINFO_MIME_TYPE);
        $mimeType = finfo_file($finfo, $file['tmp_name']);
        finfo_close($finfo);

        if (!in_array($mimeType, $this->allowedTypes)) {
            throw new Exception('不支持的文件类型，只允许图片文件');
        }

        // 3. 创建用户专用目录
        $userDir = $this->uploadDir . $userId . '/';
        if (!is_dir($userDir)) {
            if (!mkdir($userDir, 0755, true)) {
                throw new Exception('创建用户目录失败');
            }
        }

        // 4. 生成安全文件名
        $extension = pathinfo($file['name'], PATHINFO_EXTENSION);
        $safeFilename = uniqid('img_', true) . '.' . $extension;
        $targetPath = $userDir . $safeFilename;

        // 5. 验证目录权限
        if (!is_writable($this->uploadDir)) {
            throw new Exception('上传目录无写权限');
        }

        // 6. 移动文件
        if (!move_uploaded_file($file['tmp_name'], $targetPath)) {
            throw new Exception('文件移动失败');
        }

        // 7. 设置文件权限（仅用户可读，其他用户不可访问）
        chmod($targetPath, 0644);
        chmod($userDir, 0755);

        return [
            'filename' => $safeFilename,
            'url' => $this->publicUrlBase . $userId . '/' . $safeFilename,
            'path' => $targetPath
        ];
    }
}

// 使用示例
try {
    session_start();
    $userId = $_SESSION['user_id'] ?? 'guest_' . session_id();
    $uploader = new ProductImageUploader();
    $result = $uploader->uploadProductImage($userId);
    echo json_encode(['success' => true, 'data' => $result]);
} catch (Exception $e) {
    http_response_code(400);
    echo json_encode(['success' => false, 'error' => $e->getMessage()]);
}
?>
