    die("数据库连接失败: " . $e->getMessage());
}

// 处理搜索请求
$searchResults = [];
$error = '';
$searchParams = [];

if ($_SERVER['REQUEST_METHOD'] === 'GET') {
    $location = trim($_GET['location'] ?? '');
    $checkIn = $_GET['check_in'] ?? '';
    $checkOut = $_GET['check_out'] ?? '';

    // 验证日期
    if ($checkIn && $checkOut) {
        $checkInDate = new DateTime($checkIn);
        $checkOutDate = new DateTime($checkOut);

        if ($checkInDate >= $checkOutDate) {
            $error = '退房日期必须晚于入住日期';
        }
    }

    if (empty($error)) {
        // 构建查询条件
        $whereConditions = ['1=1'];
        $params = [];

        if (!empty($location)) {
            $whereConditions[] = "location LIKE :location";
            $params[':location'] = "%$location%";
        }

        if ($checkIn && $checkOut) {
            // 检查指定日期范围内无冲突预订
            $whereConditions[] = "id NOT IN (
                SELECT listing_id FROM bookings 
                WHERE status = 'confirmed'
                AND (
                    (:check_in BETWEEN check_in_date AND check_out_date) OR
                    (:check_out BETWEEN check_in_date AND check_out_date) OR
                    (check_in_date BETWEEN :check_in AND :check_out)
                )
            )";
            $params[':check_in'] = $checkIn;
            $params[':check_out'] = $checkOut;
        }

        $searchParams = $params;

        // 执行查询
        $sql = "SELECT * FROM listings WHERE " . implode(' AND ', $whereConditions) . " ORDER BY created_at DESC";
        $stmt = $pdo->prepare($sql);
        $stmt->execute($params);
        $searchResults = $stmt->fetchAll(PDO::FETCH_ASSOC);
    }
}
