<?php
/**
 * 安全的用户账户信息和交易数据加密/解密类
 * 使用AES-256-GCM对称加密，确保数据机密性和完整性
 */

class PaymentEncryption {
    private $key;
    private $nonceLength = 12; // GCM nonce长度

    /**
     * 构造函数 - 从环境变量加载密钥（推荐生产环境方式）
     * @throws Exception
     */
    public function __construct() {
        $key = getenv('ENCRYPTION_KEY');
        if (!$key || strlen($key) !== 32) { // AES-256需要32字节密钥
            throw new Exception('ENCRYPTION_KEY环境变量未设置或密钥长度错误（必须32字节）');
        }
        $this->key = $key;
    }

    /**
     * 加密数据
     * @param string $data 要加密的数据（JSON格式推荐）
     * @return string 加密后的数据（base64编码）
     */
    public function encrypt(string $data): string {
        $nonce = random_bytes($this->nonceLength);
        $ciphertext = openssl_encrypt(
            $data,
            'aes-256-gcm',
            $this->key,
            OPENSSL_RAW_DATA,
            $nonce,
            $tag
        );

        if ($ciphertext === false) {
            throw new Exception('加密失败: ' . openssl_error_string());
        }

        // nonce(12) + ciphertext + tag(16)
        return base64_encode($nonce . $ciphertext . $tag);
    }

    /**
     * 解密数据
     * @param string $encryptedData base64编码的加密数据
     * @return string 解密后的原始数据
     */
    public function decrypt(string $encryptedData): string {
        $decoded = base64_decode($encryptedData);
        if ($decoded === false || strlen($decoded) < 28) { // nonce(12)+tag(16)=28
            throw new Exception('无效的加密数据');
        }

        $nonce = substr($decoded, 0, $this->nonceLength);
        $ciphertext = substr($decoded, $this->nonceLength, -16);
        $tag = substr($decoded, -$this->nonceLength);

        $plaintext = openssl_decrypt(
            $ciphertext,
            'aes-256-gcm',
            $this->key,
            OPENSSL_RAW_DATA,
            $nonce,
            $tag
        );

        if ($plaintext === false) {
            throw new Exception('解密失败: ' . openssl_error_string());
        }

        return $plaintext;
    }
}

