#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <unordered_map>
#include <iomanip>

using namespace std;

class ActivityTracker {
private:
    struct DailyActivity {
        string activityName;
        array<int, 7> durationMinutes{}; // 使用std::array替代C风格数组，自动初始化为0
    };

    // 使用unordered_map提高查找性能，string作为key
    unordered_map<string, DailyActivity> activities; 
    // 或者使用vector + unordered_map<string, size_t> indexMap; 进一步优化

public:
    // 添加/更新活动，支持指定日期时长
    void addActivity(const string& activityName, int day = -1, int minutes = 0);

    // 按活动名称获取每周总时长（O(1)查找）
    int getWeeklyTotal(const string& activityName) const;

    // 显示所有活动每周记录
    void displayWeeklyActivity() const;

    // 按活动名称显示记录
    void displayActivity(const string& activityName) const;
};

void ActivityTracker::addActivity(const string& activityName, int day, int minutes) {
    auto& activity = activities[activityName]; // 自动创建/获取记录，O(1)查找
    activity.activityName = activityName;

    if (day >= 0 && day < 7 && minutes > 0) {
        activity.durationMinutes[day] = minutes; // 支持指定日期记录
    }
}

int ActivityTracker::getWeeklyTotal(const string& activityName) const {
    auto it = activities.find(activityName);
    if (it == activities.end()) return 0;

    int total = 0;
    for (int min : it->second.durationMinutes) {
        total += min;
    }
    return total;
}

void ActivityTracker::displayWeeklyActivity() const {
    cout << "=== Weekly Activity Summary ===\n\n";

    if (activities.empty()) {
        cout << "No activities recorded.\n";
        return;
    }

    for (const auto& [name, activity] : activities) {
        cout << "Activity: " << activity.activityName << endl;
        int weeklyTotal = 0;

        for (int day = 0; day < 7; ++day) {
            int minutes = activity.durationMinutes[day];
            weeklyTotal += minutes;
            cout << "Day " << (day + 1) << ": " 
                 << setw(3) << minutes << " minutes" << endl;
        }
        cout << "Weekly Total: " << weeklyTotal << " minutes\n\n";
    }
}

void ActivityTracker::displayActivity(const string& activityName) const {
    auto it = activities.find(activityName);
    if (it == activities.end()) {
        cout << "Activity '" << activityName << "' not found.\n";
        return;
    }

    const auto& activity = it->second;
    cout << "Activity: " << activity.activityName << endl;
    for (int day = 0; day < 7; ++day) {
        cout << "Day " << (day + 1) << ": " 
             << setw(3) << activity.durationMinutes[day] << " minutes" << endl;
    }
}

int main() {
    ActivityTracker tracker;

    // 添加活动并记录具体日期时长（更真实的使用场景）
    tracker.addActivity("Running", 1, 45);   // 周二跑步45分钟
    tracker.addActivity("Running", 3, 60);   // 周四跑步60分钟
    tracker.addActivity("Cycling", 2, 90);   // 周三骑行90分钟
    tracker.addActivity("Cycling", 5, 75);   // 周六骑行75分钟
    tracker.addActivity("Swimming");         // 添加无时长记录的活动

    // 显示所有活动
    tracker.displayWeeklyActivity();

    // 快速查询特定活动总时长
    cout << "Running weekly total: " << tracker.getWeeklyTotal("Running") << " minutes\n";
    cout << "Cycling weekly total: " << tracker.getWeeklyTotal("Cycling") << " minutes\n";

    return 0;
}
