```cpp
#include <iostream>
#include <cstdio>
#include <vector>
#include <string>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <atomic>

class Topic {
public:
    std::string title;
    int id;
    std::atomic<size_t> reply_count{0};

    Topic(std::string t, int i) : title(std::move(t)), id(i) {}
};

class DiscussionForum {
private:
    std::vector<std::unique_ptr<Topic>> topics_;
    std::unordered_map<int, size_t> topic_index_; // id -> vector index
    std::mutex topics_mutex_;
    std::atomic<int> next_id_{0};

    static constexpr size_t BUFFER_SIZE = 1024;
    static thread_local char buffer_[BUFFER_SIZE];

public:
    void postTopic(const char* format, ...) {
        va_list args;
        va_start(args, format);
        int len = vsnprintf(buffer_, BUFFER_SIZE, format, args);
        va_end(args);

        if (len < 0 || len >= BUFFER_SIZE) {
            std::cerr << "Topic too long\n";
            return;
        }

        std::lock_guard<std::mutex> lock(topics_mutex_);
        int id = next_id_++;

        auto topic = std::make_unique<Topic>(std::string(buffer_, len), id);
        size_t index = topics_.size();
        topics_.push_back(std::move(topic));
        topic_index_[id] = index;

        std::cout << "Posted topic ID:" << id << " - " 
                  << buffer_ << '\n';
    }

    bool getTopic(int id, std::string& title) {
        std::lock_guard<std::mutex> lock(topics_mutex_);
        auto it = topic_index_.find(id);
        if (it != topic_index_.end()) {
            title = topics_[it->second]->title;
            return true;
        }
        return false;
    }

    size_t getTopicCount() const {
        std::lock_guard<std::mutex> lock(topics_mutex_);
        return topics_.size();
    }
};

thread_local char DiscussionForum::buffer_[DiscussionForum::BUFFER_SIZE];

int main() {
    DiscussionForum forum;

    forum.postTopic("%s %d", "Example Topic", 42);
    forum.postTopic("Performance Optimized Forum %s", "v2.0");
    forum.postTopic("C++ Best Practices #%d", 2024);

    std::string title;
    if (forum.getTopic(0, title)) {
        std::cout << "Retrieved topic 0: " << title << '\n';
    }

    std::cout << "Total topics: " << forum.getTopicCount() << '\n';

    return 0;
}
```

## 关键优化点

