// 安全转义HTML特殊字符
std::string htmlEscape(const std::string& input) {
    std::string result;
    result.reserve(input.size());
    for (char c : input) {
        switch (c) {
            case '&':  result += "&amp;";  break;
            case '<':  result += "&lt;";   break;
            case '>':  result += "&gt;";   break;
            case '"':  result += "&quot;"; break;
            case '\'': result += "&#39;";  break;
            default:   result += c;        break;
        }
    }
    return result;
}

// 从文件路径提取安全文件名作为标题
std::string extractSafeTitle(const std::string& path) {
    size_t pos = path.find_last_of("/\\");
    std::string filename = (pos != std::string::npos) ? path.substr(pos + 1) : path;

    // 移除扩展名
    pos = filename.find_last_of('.');
    if (pos != std::string::npos) {
        filename = filename.substr(0, pos);
    }

    return htmlEscape(filename);
}

// 生成优化的视频播放器页面
std::string generateVideoPlayerPage(const std::vector<std::string>& videoPaths, 
                                  const std::string& coverImagePath = "") {
    if (videoPaths.empty()) {
        return HTML_TEMPLATE + "<p style='text-align:center;color:white;font-size:1.2em;'>暂无视频文件</p>" + HTML_FOOTER;
    }

    std::ostringstream htmlStream;
    htmlStream << HTML_TEMPLATE;

    // 响应式网格布局
    htmlStream << "  <div class=\"video-grid\">";

    for (size_t i = 0; i < videoPaths.size(); ++i) {
        const auto& path = videoPaths[i];
        std::string title = extractSafeTitle(path);
        std::string poster = coverImagePath.empty() ? "" : "poster=\"" + htmlEscape(coverImagePath) + "\"";

        htmlStream << R"(
    <div class="video-container">
      <video controls preload="metadata" )" << poster << R"(
           data-index=")" << i << R"(">
        <source src=")"" << htmlEscape(path) << R"(" type="video/mp4">
        您的浏览器不支持视频播放。
      </video>
      <div class="video-title">📹 )" << title << R"(</div>
    </div>
)";
    }

    htmlStream << "  </div>" << HTML_FOOTER;
    return htmlStream.str();
}

int main() {
    std::vector<std::string> videoPaths = {
        "videos/video1.mp4",
        "videos/video2.mp4", 
        "videos/video3.mp4"
    };

    std::string coverImagePath = "images/cover.jpg"; // 可选封面图

    std::string htmlContent = generateVideoPlayerPage(videoPaths, coverImagePath);
    std::cout << htmlContent << std::endl;

    return 0;
}
