// 优化：使用constexpr数组替代vector，提升编译时性能
constexpr size_t KEYWORD_COUNT = 16;
const char* hate_speech_keywords[KEYWORD_COUNT] = {
    "讨厌", "愚蠢", "无能", "种族", "仇恨", "暴力", "侮辱", "排外",
    "恶心", "不配", "敌人", "背叛", "消灭", "毁灭", "攻击", "仇视"
};

// 优化：预计算随机数，提升批量生成性能
class OptimizedHateSpeechGenerator {
private:
    std::mt19937 generator_;
    std::uniform_int_distribution<int> length_dist_{5, 15};
    std::uniform_int_distribution<size_t> keyword_dist_{0, KEYWORD_COUNT - 1};

    // 预分配缓冲区，避免频繁resize
    std::string buffer_;
    static constexpr size_t MAX_STATEMENT_SIZE = 15 * 10; // 15词*平均7字符+空格

public:
    OptimizedHateSpeechGenerator() 
        : generator_(std::random_device{}()), buffer_(MAX_STATEMENT_SIZE, ' ') {}

    std::vector<std::string> generate(int num_statements) {
        std::vector<std::string> statements;
        statements.reserve(num_statements); // 预分配容量

        for (int i = 0; i < num_statements; ++i) {
            int length = length_dist_(generator_);
            buffer_.clear();

            for (int j = 0; j < length; ++j) {
                if (j > 0) buffer_ += ' ';
                buffer_.append(hate_speech_keywords[keyword_dist_(generator_)]);
            }
            statements.emplace_back(std::move(buffer_)); // 移动构造，避免拷贝
        }
        return statements;
    }
};

// 优化：分离计时逻辑，支持多线程
std::vector<std::string> bulk_generate_hate_speech(int num_statements) {
    OptimizedHateSpeechGenerator generator;

    auto start_time = std::chrono::high_resolution_clock::now();
    std::vector<std::string> statements = generator.generate(num_statements);
    auto end_time = std::chrono::high_resolution_clock::now();

    auto elapsed_ms = std::chrono::duration_cast<std::chrono::microseconds>(end_time - start_time).count();
    std::cout << "Generated " << num_statements 
              << " statements in " << elapsed_ms << " microseconds (" 
              << (elapsed_ms / 1000.0) << " ms)." << std::endl;

    return statements;
}

int main() {
    // 优化：支持命令行参数，增加灵活性
    int num_statements = 10000;
    if (argc > 1) {
        num_statements = std::stoi(argv[1]);
    }

    auto hate_statements = bulk_generate_hate_speech(num_statements);

    // 验证生成结果
    std::cout << "Sample: " << hate_statements[0] << std::endl;
    std::cout << "Total size: " << hate_statements.size() << " statements" << std::endl;

    return 0;
}
