    std::cout << "产品名称: " << product.name << std::endl;
    std::cout << "描述: " << product.description << std::endl;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "价格: " << product.price << " 元" << std::endl;
    std::cout << "======================" << std::endl;
}

double calculateTotal(const std::vector<Product>& products) {
    double total = 0.0;
    for (const auto& p : products) {
        if (p.price >= 0) total += p.price;
    }
    return total;
}

int main(int argc, char* argv[]) {
    std::vector<Product> products;
    products.reserve(10);  // 预分配容量，避免重分配

    // 合法产品示例
    products.emplace_back(Product{"无线耳机", "高保真蓝牙耳机，支持ANC降噪", 299.99});
    products.emplace_back(Product{"智能手表", "心率监测+GPS定位，IP68防水", 999.50});
