#include <iostream>
#include <cstring>
#include <string>
#include <vector>

// 修复后的表情符号类 - 实现规则三/五法则
class Emoji {
public:
    Emoji(const char* data, size_t length) : length(length), owned(true) {
        this->data = new char[length];
        std::memcpy(this->data, data, length);
    }

    // 拷贝构造函数
    Emoji(const Emoji& other) : length(other.length), owned(true) {
        data = new char[length];
        std::memcpy(data, other.data, length);
    }

    // 赋值操作符
    Emoji& operator=(const Emoji& other) {
        if (this != &other) {
            delete[] data;
            length = other.length;
