#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>

// HTML转义函数 - 防止XSS攻击
std::string htmlEscape(const std::string& input) {
    std::string escaped;
    escaped.reserve(input.size());

    for (char c : input) {
        switch (c) {
            case '&': escaped += "&amp;"; break;
            case '<': escaped += "&lt;"; break;
            case '>': escaped += "&gt;"; break;
            case '"': escaped += "&quot;"; break;
            case '\'': escaped += "&#x27;"; break;
            default: escaped += c; break;
        }
    }
    return escaped;
}

// 严格的iframe白名单验证
bool isValidIframeSrc(const std::string& src) {
    // 只允许受信任的医疗系统域名
    std::string allowed_domains[] = {
        "https://trusted-hospital.com",
        "https://secure-medical.net"
    };

    std::string lower_src = src;
    std::transform(lower_src.begin(), lower_src.end(), lower_src.begin(), 
                   [](unsigned char c){ return std::tolower(c); });

    for (const auto& domain : allowed_domains) {
        if (lower_src.find(domain) == 0) {
            return true;
        }
    }
    return false;
}

class MedicalRecord {
private:
    std::string record_text;  // 纯文本存储，禁止HTML/iframe
    bool iframe_allowed = false;
    std::string iframe_src;   // 严格验证的iframe源

public:
    // 安全设置记录文本（自动HTML转义）
    void setRecordText(const std::string& text) {
        record_text = htmlEscape(text);
    }

    // 严格验证的iframe设置（仅管理员权限）
    bool setIframeSrc(const std::string& src, bool isAdmin = false) {
        if (!isAdmin) {
