            return false;
        }

        if (!isValidIframeSrc(src)) {
            std::cerr << "ERROR: Invalid iframe source: " << src << "\n";
            return false;
        }

        iframe_allowed = true;
        iframe_src = htmlEscape(src);
        return true;
    }

