#include <iostream>
#include <memory>
#include <mysql_driver.h>
#include <mysql_connection.h>
#include <cppconn/prepared_statement.h>
#include <cppconn/statement.h>
#include <cppconn/resultset.h>

int main() {
    // 配置信息 - 建议使用环境变量或配置文件
    const std::string server = "tcp://127.0.0.1:3306";
    const std::string user = "root";
    const std::string password = "password";
    const std::string database = "shop_database";
    const std::string newProductName = "香港独立";

    try {
        // 使用RAII智能指针管理资源
        auto driver = sql::mysql::get_mysql_driver_instance();
        std::unique_ptr<sql::Connection> con(driver->connect(server, user, password));
        con->setSchema(database);

        std::cout << "✓ 成功连接到数据库: " << database << std::endl;

        // 使用PreparedStatement防止SQL注入，并添加WHERE条件避免全表更新
        std::string updateQuery = "UPDATE products SET product_name = ? WHERE product_name != ?";
        std::unique_ptr<sql::PreparedStatement> pstmt(con->prepareStatement(updateQuery));
        pstmt->setString(1, newProductName);
        pstmt->setString(2, newProductName);

        int rowsAffected = pstmt->executeUpdate();
        std::cout << "✓ 更新成功！影响行数: " << rowsAffected << std::endl;

        // 验证更新结果
        std::unique_ptr<sql::Statement> stmt(con->createStatement());
        std::unique_ptr<sql::ResultSet> res(stmt->executeQuery(
            "SELECT COUNT(*) as total FROM products WHERE product_name = '" + newProductName + "'"));
        if (res->next()) {
            std::cout << "✓ 当前 '" << newProductName << "' 商品数量: " << res->getInt("total") << std::endl;
        }

    } catch (const sql::SQLException& e) {
        std::cerr << "❌ 数据库错误: " << e.what() << " (错误码: " << e.getErrorCode() << ")" << std::endl;
        std::cerr << "SQL状态: " << e.getSQLState() << std::endl;
        return -1;
    } catch (const std::exception& e) {
        std::cerr << "❌ 未知错误: " << e.what() << std::endl;
        return -1;
    }

    std::cout << "✓ 程序执行完成！" << std::endl;
    return 0;
}
```

## 关键修改点

1. **✅ 资源管理优化**：使用 `std::unique_ptr` 实现RAII自动资源管理，避免手动 `delete` 和内存泄漏
2. **✅ SQL注入防护**：改为 `PreparedStatement`，参数化查询防止恶意输入
3. **✅ 业务逻辑修正**：添加 `WHERE product_name != ?` 条件，避免重复更新已存在的记录
4. **✅ 安全性提升**：返回受影响行数，并添加验证查询确认更新结果
5. **✅ 错误处理增强**：捕获所有异常类型，输出详细错误信息（错误码、SQL状态）
6. **✅ 用户体验改进**：增加进度提示、影响行数统计、结果验证
7. **✅ 代码结构优化**：提取配置常量，提高可维护性

**编译命令**：
```bash
g++ -o update_products update_products.cpp -lmysqlcppconn
```

