```cpp
#include <iostream>
#include <iomanip>
#include <limits>

const double G = 6.67430e-11;  // 万有引力常数 (m^3·kg^-1·s^-2)

double calculate_gravitational_force(double mass1, double mass2, double distance) {
    if (distance <= 0.0) {
        std::cerr << "错误：距离必须大于0！" << std::endl;
        return 0.0;
    }
    return G * (mass1 * mass2) / (distance * distance);
}

int main() {
    double mass1, mass2, distance;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "=== 万有引力计算器 ===\n";
    std::cout << "请输入物体1的质量 (kg): ";
    std::cin >> mass1;
    std::cout << "请输入物体2的质量 (kg): ";
    std::cin >> mass2;
    std::cout << "请输入物体之间的距离 (m): ";
    std::cin >> distance;

    // 输入验证
    if (mass1 <= 0 || mass2 <= 0) {
        std::cerr << "错误：质量必须大于0！" << std::endl;
        return 1;
    }

    double force = calculate_gravitational_force(mass1, mass2, distance);
    std::cout << "\n根据万有引力定律，两物体之间的引力是: " 
              << force << " N" << std::endl;

    return 0;
}
```

