```cpp
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>
#include <functional>

// 智能设备状态结构体 - 添加初始化和边界值
struct SmartDevice {
    std::string name;
    bool isOn = false;
    int brightness = 0;  // 默认0，关闭时无意义

    // 构造函数
    SmartDevice(const std::string& n = "Unknown") : name(n), isOn(false), brightness(0) {}

    // 亮度边界检查
    void setBrightness(int value) {
        brightness = std::max(0, std::min(100, value));
    }

    // 获取状态描述
    std::string getStatus() const {
        if (!isOn) return "off";
        return "on (brightness: " + std::to_string(brightness) + "%)";
    }
};

// 命令处理器 - 支持模糊匹配
class VoiceCommandProcessor {
private:
    std::vector<std::pair<std::string, std::function<void(SmartDevice&)>>> commands;

    // 模糊匹配（忽略大小写，忽略多余空格）
    bool matches(const std::string& input, const std::string& pattern) const {
        std::string cleanInput = toLower(trim(input));
        std::string cleanPattern = toLower(trim(pattern));
        return cleanInput.find(cleanPattern) != std::string::npos;
    }

    std::string trim(const std::string& str) const {
        size_t first = str.find_first_not_of(" \t");
        if (first == std::string::npos) return "";
        size_t last = str.find_last_not_of(" \t");
        return str.substr(first, last - first + 1);
    }

    std::string toLower(std::string str) const {
        std::transform(str.begin(), str.end(), str.begin(),
                      [](unsigned char c) { return std::tolower(c); });
        return str;
    }

public:
    VoiceCommandProcessor() {
        // 注册命令处理器
        commands.emplace_back("turn on", [](SmartDevice& device) {
            device.isOn = true;
        });

        commands.emplace_back("turn off", [](SmartDevice& device) {
            device.isOn = false;
            device.brightness = 0;  // 关闭时重置亮度
        });

        commands.emplace_back("increase brightness", [](SmartDevice& device) {
            if (device.isOn) {
                device.setBrightness(device.brightness + 10);
            }
        });

        commands.emplace_back("decrease brightness", [](SmartDevice& device) {
            if (device.isOn) {
                device.setBrightness(device.brightness - 10);
            }
        });

        commands.emplace_back("set brightness 50", [](SmartDevice& device) {
            if (device.isOn) {
                device.setBrightness(50);
            }
        });
    }

    bool process(SmartDevice& device, const std::string& command) {
        for (const auto& cmd : commands) {
            if (matches(command, cmd.first)) {
                cmd.second(device);
                std::cout << device.name << " is now " << device.getStatus() << std::endl;
                return true;
            }
        }
        std::cout << "Sorry, I didn't understand '" << command << "'. Try 'turn on/off', 'increase/decrease brightness'" << std::endl;
        return false;
    }
};

int main() {
    // 多设备管理
    std::vector<SmartDevice> devices = {
        SmartDevice("Living Room Light"),
        SmartDevice("Kitchen Light"),
        SmartDevice("Bedroom Fan")
    };

    VoiceCommandProcessor processor;

    // 模拟连续语音命令
    std::vector<std::string> commands = {
        "turn on",
        "  TURN OFF  ",
        "turn on living room light",
        "increase brightness",
        "increase brightness",
        "decrease brightness",
        "unknown command",
        "set brightness 50"
    };

    std::cout << "=== Smart Home Voice Control Demo ===" << std::endl;
    for (const auto& cmd : commands) {
        std::cout << "\nVoice command: " << cmd << std::endl;
        processor.process(devices[0], cmd);  // 处理客厅灯
    }

    return 0;
}
