        switch (c) {
            case '<': escaped += "&lt;"; break;
            case '>': escaped += "&gt;"; break;
            case '&': escaped += "&amp;"; break;
            case '"': escaped += "&quot;"; break;
            case '\'': escaped += "&#39;"; break;
            case '\\': escaped += "&#92;"; break;  // ✅ 修复：转义反斜杠
            case '\n': escaped += "<br>"; break;   // ✅ 新增：换行转义
            case '\r': break;                      // 忽略回车
            case '\t': escaped += "    "; break;   // Tab转空格
            default:
                if (std::isprint(static_cast<unsigned char>(c))) {
                    escaped += c;
                } else {
                    escaped += "&#" + std::to_string(static_cast<int>(c)) + ";";
                }
                break;
        }
    }
    return escaped;
}

// 输入验证和清理
std::string sanitizeInput(const std::string& input, size_t maxLength = 500) {
    std::string cleaned = input.substr(0, maxLength); // 长度限制
    cleaned.erase(std::remove_if(cleaned.begin(), cleaned.end(),
                   [](char c) { return c == 0x00 || c == 0xFF; }), // 移除控制字符
             cleaned.end());
    return cleaned;
}

// 终端安全的输出函数
void safeTerminalOutput(const std::string& text) {
    std::string safeText;
    for (char c : text) {
        if (std::isprint(static_cast<unsigned char>(c)) || c == '\n') {
            safeText += c;
        } else {
            safeText += '?';
        }
    }
    std::cout << safeText << std::endl;
}

