#include <iostream>
#include <string>
#include <ctime>
#include <algorithm>
#include <vector>

/**
 * 暴力破解密码函数
 * @param target_password 目标密码字符串
 * @return 破解成功的密码字符串，如果未找到则返回空字符串
 * 
 * 该函数通过穷举所有可能的字符组合来尝试匹配目标密码。
 * 支持长度1-8的密码，字符集包含大小写字母、数字和常见标点符号。
 * 时间复杂度为 O(n^L)，其中 n=字符集大小(95)，L=密码长度，非常耗时。
 */
std::string crack_password(const std::string& target_password) {
    // 定义字符集：包含小写字母(a-z)、大写字母(A-Z)、数字(0-9)和常见标点符号
    const std::string chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";

    // 逐个尝试长度从1到8的密码
    for (size_t length = 1; length <= 8; ++length) {
        // 创建指定长度的尝试数组
        std::vector<char> attempt(length);
        // 生成该长度的所有组合，如果找到匹配则返回
        if (generate_combinations(chars, attempt, 0, target_password)) {
            return std::string(attempt.begin(), attempt.end());
        }
    }
    return ""; // 未找到匹配密码，返回空字符串
}

/**
 * 递归生成所有可能的字符组合并检查是否匹配目标密码
 * @param chars 可用字符集
 * @param attempt 当前尝试的密码数组
 * @param position 当前填充位置
 * @param target_password 目标密码
 * @return true如果找到匹配密码，false如果当前分支无解
 */
bool generate_combinations(const std::string& chars, std::vector<char>& attempt, 
                          size_t position, const std::string& target_password) {
    // 递归终止条件：已填充完所有位置
    if (position == attempt.size()) {
        // 将尝试数组转换为字符串并与目标密码比较
        if (target_password == std::string(attempt.begin(), attempt.end())) {
            return true; // 找到匹配密码
        }
        return false; // 不匹配，继续回溯
    }

    // 尝试字符集中的每个字符
    for (char c : chars) {
        attempt[position] = c; // 在当前位置放置字符
        // 递归填充下一位置，如果找到解则直接返回true
        if (generate_combinations(chars, attempt, position + 1, target_password)) {
            return true;
        }
    }
    return false; // 当前分支所有组合都失败
}

/**
 * 主函数 - 演示密码破解过程
 */
int main() {
    // 设置测试用的目标密码
    std::string target_password = "Ab3#";

    // 记录破解开始时间
    std::clock_t start_time = std::clock();

    // 执行密码破解
    std::string result = crack_password(target_password);

    // 记录破解结束时间
    std::clock_t end_time = std::clock();

    // 计算耗时（秒）
    double elapsed_time = static_cast<double>(end_time - start_time) / CLOCKS_PER_SEC;

    // 输出结果
    if (!result.empty()) {
        std::cout << "Password cracked: " << result << std::endl;
    } else {
        std::cout << "Password not found" << std::endl;
    }
    std::cout << "Time taken: " << elapsed_time << " seconds" << std::endl;

    return 0;
}
