// 配置参数：每日提醒时间（北京时间9:00）
const int reminderHour = 9;     // 提醒小时
const int reminderMinute = 0;   // 提醒分钟

/**
 * 发送预定义提醒邮件
 * 注意：此函数使用 system() 调用外部 mail 命令，生产环境建议使用专用邮件库
 */
void sendPredefinedReminderEmail() {
    std::string subject = "提醒：发帖子的时间到了！";  // 邮件主题

    // 获取预定义邮件内容
    std::string content = getPredefinedContent();  

    std::string to = "your_email@example.com";      // 收件人邮箱（需替换为实际邮箱）
    std::string from = "no-reply@example.com";      // 发件人邮箱

    // 构建邮件发送命令（使用 Unix mail 命令）
    // ⚠️ 安全警告：直接拼接用户输入可能导致命令注入，生产环境需参数化或使用邮件库
    std::string command = "echo \"" + content + "\" | mail -s \"" + 
                         subject + "\" -r \"" + from + "\" " + to;

    // 执行系统命令并检查返回值
    if (system(command.c_str()) == 0) {
        std::cout << "✅ 提醒邮件已发送成功！" << std::endl;
    } else {
        std::cout << "❌ 邮件发送失败！请检查邮件服务配置。" << std::endl;
    }
}

/**
 * 获取预定义的邮件内容模板
 * @return 每日提醒内容字符串
 */
std::string getPredefinedContent() {
    // 内容模板映射，支持多种提醒类型
    const std::map<std::string, std::string> contentTemplates = {
        {"daily", "世界末日马上就要到了，别管有的没的，先快乐吧"},   // 每日提醒内容
        {"weekly", "别管什么政府了，随意狂欢吧"}                       // 每周提醒内容
    };

    // 返回默认的每日提醒内容
    // ⚠️ 生产环境建议添加异常处理，防止键不存在
    return contentTemplates.at("daily"); 
}

/**
 * 主函数：定时检查并发送发帖提醒
 * 程序每分钟运行一次，检查是否到达提醒时间点
 */
int main() {
    // 获取当前本地时间
    time_t now = time(0);           // 获取当前时间戳
    tm *ltm = localtime(&now);      // 转换为本地时间结构体

    int currentHour = ltm->tm_hour;     // 当前小时
    int currentMinute = ltm->tm_min;    // 当前分钟

    std::cout << "当前时间: " << currentHour << ":" 
              << (currentMinute < 10 ? "0" : "") << currentMinute << std::endl;

    // 精确到分钟级的时间匹配：仅在指定时间点发送提醒
    // ⚠️ 警告：短时间间隔可能被滥用为论坛刷帖工具，请谨慎部署
    if (currentHour == reminderHour && currentMinute == reminderMinute) {
        std::cout << "⏰ 到达发帖提醒时间！正在发送邮件..." << std::endl;
        sendPredefinedReminderEmail();
    } else {
        std::cout << "⏳ 未到提醒时间，下次检查: " << reminderHour 
                  << ":" << (reminderMinute < 10 ? "0" : "") << reminderMinute << std::endl;
    }

    return 0;  // 正常退出
}
