```cpp
#include <iostream>
#include <unordered_map>
#include <string>
#include <sstream>
#include <iomanip>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <openssl/sha.h>
#include <openssl/rand.h>

// 安全的加盐SHA256哈希
std::string salted_sha256(const std::string& password, const std::string& salt) {
    std::string salted = password + salt;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, salted.c_str(), salted.size());
    SHA256_Final(hash, &sha256);
    std::stringstream ss;
    ss << std::hex << std::setfill('0');
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::setw(2) << static_cast<int>(hash[i]);
    }
    return ss.str();
}

// 生成随机盐值
std::string generate_salt() {
    unsigned char salt[16];
    RAND_bytes(salt, 16);
    std::stringstream ss;
    ss << std::hex << std::setfill('0');
    for (int i = 0; i < 16; ++i) {
        ss << std::setw(2) << static_cast<int>(salt[i]);
    }
    return ss.str();
}

// 密码强度检查
bool is_strong_password(const std::string& password) {
    if (password.length() < 8) return false;
    bool has_upper = false, has_lower = false, has_digit = false;
    for (char c : password) {
        if (isupper(c)) has_upper = true;
        else if (islower(c)) has_lower = true;
        else if (isdigit(c)) has_digit = true;
    }
    return has_upper && has_lower && has_digit;
}

// 用户结构体
struct User {
    std::string password_hash;
    std::string salt;
    double balance;
    std::chrono::steady_clock::time_point last_login;
    int failed_attempts;
    mutable std::mutex mtx;
};

// 安全的用户数据库（单例模式）
class UserDatabase {
private:
    std::unordered_map<std::string, User> users;
    mutable std::mutex db_mutex;
    static const int MAX_FAILED_ATTEMPTS = 5;
    static const int LOCKOUT_DURATION = 300; // 5分钟

    UserDatabase() {
        // 初始化用户数据（密码: StrongPass123!）
        std::string salt = generate_salt();
        std::string password = "StrongPass123!";
        users["user1"] = {
            salted_sha256(password, salt), salt, 1000.0,
            std::chrono::steady_clock::now(), 0
        };
    }

public:
    static UserDatabase& getInstance() {
        static UserDatabase instance;
        return instance;
    }

    bool authenticate(const std::string& user_id, const std::string& password) {
        std::lock_guard<std::mutex> lock(db_mutex);

        auto it = users.find(user_id);
        if (it == users.end()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // 时间延迟防枚举
            return false;
        }

        User& user = it->second;
        {
            std::lock_guard<std::mutex> user_lock(user.mtx);

            // 检查锁定期
            auto now = std::chrono::steady_clock::now();
            if (user.failed_attempts >= MAX_FAILED_ATTEMPTS) {
                auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - user.last_login).count();
                if (elapsed < LOCKOUT_DURATION) {
                    return false;
                } else {
                    user.failed_attempts = 0; // 重置失败计数
                }
            }

            // 验证密码
            if (user.password_hash != salted_sha256(password, user.salt)) {
                user.failed_attempts++;
                user.last_login = now;
                return false;
            }

            // 认证成功，重置失败计数
            user.failed_attempts = 0;
            user.last_login = now;
        }
        return true;
    }

    bool process_payment(const std::string& user_id, double amount) {
        std::lock_guard<std::mutex> lock(db_mutex);

        auto it = users.find(user_id);
        if (it == users.end()) {
            std::cout << "认证失败" << std::endl;
            return false;
        }

        User& user = it->second;
        std::lock_guard<std::mutex> user_lock(user.mtx);

        if (user.balance < amount) {
            std::cout << "余额不足" << std::endl;
            return false;
        }

        user.balance -= amount;
        std::cout << "支付成功，余额: " << user.balance << std::endl;
        return true;
    }
};

int main() {
    auto& db = UserDatabase::getInstance();

    // 测试1: 正确认证 + 支付
    std::cout << "=== 测试1: 正确认证 ===" << std::endl;
    if (db.authenticate("user1", "StrongPass123!")) {
        db.process_payment("user1", 300);
    }

    std::cout << "\n=== 测试2: 错误密码（触发速率限制）===" << std::endl;
    for (int i = 0; i < 6; ++i) {
        if (!db.authenticate("user1", "wrongpass")) {
            std::cout << "认证失败 (尝试 " << (i+1) << ")" << std::endl;
        }
    }

    std::cout << "\n=== 测试3: 锁定期后重新认证 ===" << std::endl;
    std::this_thread::sleep_for(std::chrono::seconds(1)); // 模拟时间流逝
    if (db.authenticate("user1", "StrongPass123!")) {
        db.process_payment("user1", 200);
    }

    return 0;
}
