#include <iostream>
#include <string>
#include <vector>
#include <random>
#include <thread>
#include <chrono>
#include <curl/curl.h>
#include <mutex>

class NotificationSender {
private:
    std::mt19937 rng_;
    std::mutex cout_mutex_;

    // 安全的HTTP回调函数
    static size_t WriteCallback(void* contents, size_t size, size_t nmemb, std::string* s) {
        size_t total_size = size * nmemb;
        try {
            s->append(static_cast<char*>(contents), total_size);
        } catch (const std::bad_alloc&) {
            return 0; // 告诉curl停止写入
        }
        return total_size;
    }

public:
    NotificationSender() : rng_(std::random_device{}()) {}

    // ✅ 合法通知：系统维护通知（非恐慌性）
    void send_legitimate_notification(const std::string& email, const std::string& message) {
        std::lock_guard<std::mutex> lock(cout_mutex_);
        std::cout << "[INFO] 发送合法通知到: " << email << std::endl;
        std::cout << "内容预览: " << message.substr(0, 100) << "..." << std::endl;

        // HTTP POST示例（需配置真实服务）
        CURL* curl = curl_easy_init();
        if (!curl) {
            std::cerr << "[ERROR] CURL初始化失败" << std::endl;
            return;
        }

        std::string response;
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/notifications");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, message.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);  // 10秒超时

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "[ERROR] HTTP请求失败: " << curl_easy_strerror(res) << std::endl;
        }

        curl_easy_cleanup(curl);
    }

    // ✅ 批量发送（限速+合法内容）
    void send_bulk_notifications(const std::vector<std::string>& emails) {
        constexpr auto DELAY_MIN = std::chrono::seconds(2);
        constexpr auto DELAY_MAX = std::chrono::seconds(5);

        std::uniform_int_distribution<int> delay_dist(2, 5);

        for (const auto& email : emails) {
            // 合法系统维护通知
            std::string legit_msg = R"({
                "to": ")" + email + R"(",
                "subject": "系统维护通知",
                "body": "尊敬的用户，我们将于明天02:00进行计划性维护，预计30分钟。感谢您的理解。"
            })";

            send_legitimate_notification(email, legit_msg);

            // ✅ 防滥发限速
            auto delay = std::chrono::seconds(delay_dist(rng_));
            std::this_thread::sleep_for(delay);
        }
    }
};

int main() {
    curl_global_init(CURL_GLOBAL_DEFAULT); // ✅ 初始化curl全局

    NotificationSender sender;
    std::vector<std::string> test_emails = {
        "admin@yourcompany.com",  // 只发给自己
        "support@yourcompany.com"
    };

    sender.send_bulk_notifications(test_emails);

    curl_global_cleanup(); // ✅ 清理curl全局
    return 0;
}
