// 日志和错误报告系统
class Logger {
private:
    mutex log_mutex;
    atomic<bool> error_occurred{false};

public:
    void log(const string& message, const string& level = "INFO") {
        lock_guard<mutex> lock(log_mutex);
        auto now = chrono::system_clock::now();
        auto time_t = chrono::system_clock::to_time_t(now);
        cout << "[" << put_time(localtime(&time_t), "%Y-%m-%d %H:%M:%S") 
             << "] [" << level << "] " << message << endl;
    }

    void reportError(const string& error, const string& context) {
        error_occurred = true;
        log("ERROR: " + error + " | Context: " + context, "ERROR");
        generateInternalReport(error, context);
    }

private:
    void generateInternalReport(const string& error, const string& context) {
        ofstream report("error_report.txt", ios::app);
        if (report.is_open()) {
            auto now = chrono::system_clock::now();
            auto time_t = chrono::system_clock::to_time_t(now);
            report << "Timestamp: " << put_time(localtime(&time_t), "%Y-%m-%d %H:%M:%S") << endl;
            report << "Error: " << error << endl;
            report << "Context: " << context << endl;
            report << "User Session: " << this_thread::get_id() << endl;
            report << "----------------------------------------" << endl;
            report.close();
        }
    }
};

// 数据模型
struct Flight {
    string flightId;
    string from;
    string to;
    string departure;
    string arrival;
    double price;
    int seatsAvailable;

    bool operator<(const Flight& other) const { return price < other.price; }
};

struct Hotel {
    string hotelId;
    string name;
    string location;
    string checkIn;
    string checkOut;
    double pricePerNight;
    int roomsAvailable;
    int rating;

    bool operator<(const Hotel& other) const { return pricePerNight < other.pricePerNight; }
};

struct TravelPackage {
    Flight flight;
    Hotel hotel;
    double totalPrice() const { return flight.price + (hotel.pricePerNight * 2); } // 假设2晚
    int score() const { return (hotel.rating * 10) + (flight.seatsAvailable > 5 ? 20 : 0); }
};

// 数据中心模拟（实际项目中替换为真实API）
class DataCenter {
private:
    vector<Flight> flights;
    vector<Hotel> hotels;
    Logger logger;

public:
    DataCenter() {
        initializeMockData();
    }

    vector<Flight> queryFlights(const string& from, const string& to, const string& date) {
        try {
            vector<Flight> results;
            for (const auto& flight : flights) {
                if (flight.from == from && flight.to == to && 
                    flight.departure.find(date) != string::npos &&
                    flight.seatsAvailable > 0) {
                    results.push_back(flight);
                }
            }
            sort(results.begin(), results.end());
            logger.log("Found " + to_string(results.size()) + " flights from " + from + " to " + to);
            return results;
        } catch (const exception& e) {
            logger.reportError(e.what(), "Flight query: " + from + "->" + to + " on " + date);
            return {};
        }
    }

    vector<Hotel> queryHotels(const string& location, const string& checkIn, const string& checkOut) {
        try {
            vector<Hotel> results;
            for (const auto& hotel : hotels) {
                if (hotel.location == location &&
                    hotel.checkIn.find(checkIn) != string::npos &&
                    hotel.roomsAvailable > 0 &&
                    hotel.rating >= 3) {
                    results.push_back(hotel);
                }
            }
            sort(results.begin(), results.end(), 
                 [](const Hotel& a, const Hotel& b) { 
                     return a.pricePerNight * a.rating < b.pricePerNight * b.rating; 
                 });
            logger.log("Found " + to_string(results.size()) + " hotels in " + location);
            return results;
        } catch (const exception& e) {
            logger.reportError(e.what(), "Hotel query: " + location);
            return {};
        }
    }

