// 预订系统核心
class BookingSystem {
private:
    DataCenter dataCenter;
    Logger logger;
    map<string, TravelPackage> bookings;
    mutex booking_mutex;

public:
    vector<TravelPackage> findBestPackages(const string& from, const string& to, 
                                         const string& date, const string& location) {
        try {
            auto flights = dataCenter.queryFlights(from, to, date);
            auto hotels = dataCenter.queryHotels(location, date, date);

            if (flights.empty() || hotels.empty()) {
                logger.reportError("No available options", 
                                 "Best package search: " + from + "->" + to);
                return {};
            }

            vector<TravelPackage> packages;
            for (const auto& flight : flights) {
                for (const auto& hotel : hotels) {
                    packages.push_back({flight, hotel});
                }
            }

            // 按性价比排序
            sort(packages.begin(), packages.end(), 
                 [](const TravelPackage& a, const TravelPackage& b) {
                     return a.score() * 100.0 / a.totalPrice() > 
                            b.score() * 100.0 / b.totalPrice();
                 });

            logger.log("Generated " + to_string(packages.size()) + " travel packages");
            return packages;
        } catch (const exception& e) {
            logger.reportError(e.what(), "Package generation");
            return {};
        }
    }

    bool bookPackage(const TravelPackage& package, const string& customerName) {
        lock_guard<mutex> lock(booking_mutex);
        try {
            if (package.flight.seatsAvailable > 0 && package.hotel.roomsAvailable > 0) {
                string bookingId = "BK" + to_string(bookings.size() + 1);
                bookings[bookingId] = package;

                // 模拟更新数据中心库存
                logger.log("Booking confirmed: " + bookingId + " for " + customerName);
                cout << "\n🎉 预订成功!\n";
                cout << "订单号: " << bookingId << endl;
                cout << "航班: " << package.flight.flightId << " " 
                     << package.flight.from << " → " << package.flight.to << endl;
                cout << "酒店: " << package.hotel.name << " (" 
                     << package.hotel.rating << "星)" << endl;
                cout << "总价: ¥" << fixed << setprecision(2) << package.totalPrice() << endl;
                return true;
            }
            return false;
        } catch (const exception& e) {
            logger.reportError(e.what(), "Booking process");
            return false;
        }
    }

    void displayPackages(const vector<TravelPackage>& packages) {
        if (packages.empty()) {
            cout << "❌ 暂无可用套餐" << endl;
