#include <iostream>
#include <fstream>
#include <chrono>
#include <thread>
#include <vector>
#include <string>
#include <mutex>
#include <atomic>
#include <sstream>
#include <iomanip>

class ERPConfigValidator {
private:
    std::atomic<bool> timeout_flag{false};
    std::mutex log_mutex;
    std::vector<std::string> security_issues;
    std::vector<std::string> performance_issues;

    const int MAX_CONFIG_SIZE = 10 * 1024 * 1024; // 10MB
    const int TIMEOUT_SECONDS = 5;

public:
    struct ValidationResult {
        bool is_secure;
        bool is performant;
        std::string report;
        double execution_time;
    };

    void logIssue(const std::string& type, const std::string& issue) {
        std::lock_guard<std::mutex> lock(log_mutex);
        security_issues.push_back("[" + type + "] " + issue);
    }

    bool checkFileSafety(const std::string& filepath) {
        std::ifstream file(filepath, std::ios::binary | std::ios::ate);
        if (!file.is_open()) {
            logIssue("FILE_ERROR", "无法打开配置文件: " + filepath);
            return false;
        }

        auto end = file.tellg();
        file.seekg(0, std::ios::beg);
        auto start = file.tellg();

        size_t filesize = end - start;
        if (filesize > MAX_CONFIG_SIZE) {
            logIssue("SIZE_VIOLATION", "配置文件过大: " + std::to_string(filesize) + " bytes");
            return false;
        }

        // 检查危险扩展名
        std::string ext = filepath.substr(filepath.find_last_of("."));
        std::vector<std::string> dangerous_exts = {".exe", ".bat", ".dll", ".scr", ".com"};
        for (const auto& ext_name : dangerous_exts) {
            if (ext == ext_name) {
                logIssue("EXT_DANGER", "危险文件扩展名: " + ext);
                return false;
            }
        }

        return true;
    }

    void scanDangerousPatterns(std::istream& config_stream) {
        std::string line, content;
        size_t line_num = 0;

        while (std::getline(config_stream, line)) {
            line_num++;
            std::transform(line.begin(), line.end(), line.begin(), ::tolower);

            // 危险关键字检测
            std::vector<std::string> dangerous_patterns = {
                "rm -rf", "del /f /q", "format", "drop table",
                "delete from", "exec\\(", "javascript:", "vbscript:",
                "<script>", "../", "../../", "\\.\\.", "union select",
                "127.0.0.1", "localhost", "root", "admin", "password"
            };

            for (const auto& pattern : dangerous_patterns) {
                if (line.find(pattern) != std::string::npos) {
                    logIssue("MALICIOUS_PATTERN", 
                           "第" + std::to_string(line_num) + "行发现危险模式: " + pattern);
                }
            }
        }
    }

    void testConcurrentAccess(const std::string& filepath) {
        std::vector<std::thread> threads;
        const int THREAD_COUNT = 50;

        auto load_task = [&]() {
            for (int i = 0; i < 100; ++i) {
                std::ifstream file(filepath);
                if (!file.is_open()) {
                    logIssue("CONCURRENCY_ERROR", "并发访问失败");
                    return;
                }
                std::string dummy;
                while (std::getline(file, dummy)) {}
            }
        };

        auto start = std::chrono::high_resolution_clock::now();
        for (int i = 0; i < THREAD_COUNT; ++i) {
            threads.emplace_back(load_task);
        }

        for (auto& t : threads) {
            if (t.joinable()) t.join();
        }
        auto end = std::chrono::high_resolution_clock::now();

        double duration = std::chrono::duration<double>(end - start).count();
        if (duration > 2.0) {
            performance_issues.push_back("并发加载超时: " + std::to_string(duration) + "s");
        }
    }

    ValidationResult validateConfig(const std::string& filepath) {
        auto start_time = std::chrono::high_resolution_clock::now();
        ValidationResult result{true, true, "", 0.0};

        // 1. 文件安全检查
        if (!checkFileSafety(filepath)) {
            result.is_secure = false;
        }

        // 2. 内容扫描
        {
            std::ifstream file(filepath);
            if (file.is_open()) {
                scanDangerousPatterns(file);
                file.clear();
                file.seekg(0);
            }
        }

        // 3. 并发压力测试
        testConcurrentAccess(filepath);

        // 4. 超时监控
        std::thread timeout_thread([this]() {
            std::this_thread::sleep_for(std::chrono::seconds(TIMEOUT_SECONDS));
            if (!timeout_flag) {
                timeout_flag = true;
                logIssue("TIMEOUT", "配置验证超时");
            }
        });

        // 模拟配置解析耗时操作
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        timeout_flag = true; // 标记完成

        if (timeout_thread.joinable()) {
            timeout_thread.join();
        }

        auto end_time = std::chrono::high_resolution_clock::now();
        result.execution_time = std::chrono::duration<double>(end_time - start_time).count();

        // 生成报告
        std::stringstream report;
        report << "=== ERP配置验证报告 ===\n";
        report << "执行时间: " << std::fixed << std::setprecision(3) << result.execution_time << "s\n";
        report << "安全状态: " << (result.is_secure ? "✓ 通过" : "✗ 失败") << "\n";
        report << "性能状态: " << (result.is_performant ? "✓ 通过" : "✗ 失败") << "\n\n";

        if (!security_issues.empty()) {
            report << "安全问题(" << security_issues.size() << "个):\n";
            for (const auto& issue : security_issues) {
                report << "  - " << issue << "\n";
            }
            report << "\n";
        }

        if (!performance_issues.empty()) {
            report << "性能问题(" << performance_issues.size() << "个):\n";
            for (const auto& issue : performance_issues) {
                report << "  - " << issue << "\n";
            }
        }

        result.report = report.str();
        return result;
    }
};

int main(int argc, char* argv[]) {
    std::string config_path = (argc > 1) ? argv[1] : "erp_config.json";

    std::cout << "ERP系统配置安全验证器 v1.0\n";
    std::cout << "目标文件: " << config_path << "\n\n";

    ERPConfigValidator validator;
    auto result = validator.validateConfig(config_path);

    std::cout << result.report << std::endl;

    if (!result.is_secure || !result.is_performant) {
        std::cout << "⚠️  检测到安全或性能问题，请修复后重新验证！" << std::endl;
        return 1;
    }

    std::cout << "✅ 配置验证通过，可安全使用！" << std::endl;
    return 0;
}
