#include <iostream>
#include <fstream>
#include <thread>
#include <mutex>
#include <queue>
#include <chrono>
#include <memory>
#include <string>
#include <atomic>
#include <condition_variable>
#include <sstream>
#include <iomanip>
#include <ctime>
#include <filesystem>

class Logger {
public:
    enum class LogLevel {
        DEBUG = 0,
        INFO  = 1,
        WARN  = 2,
        ERROR = 3,
        FATAL = 4
    };

    static Logger& getInstance() {
        static Logger instance;
        return instance;
    }

    ~Logger() {
        stop();
    }

    // 设置日志文件路径和级别
    void init(const std::string& logFile, LogLevel level = LogLevel::DEBUG, size_t maxFileSize = 10 * 1024 * 1024) {
        logFile_ = logFile;
        minLevel_ = level;
        maxFileSize_ = maxFileSize;
        start();
    }

    // 日志记录接口
    void log(LogLevel level, const std::string& file, int line, const std::string& func, const std::string& message) {
        if (level < minLevel_) return;

        LogEntry entry;
        entry.level = level;
        entry.timestamp = std::chrono::system_clock::now();
        entry.file = file;
        entry.line = line;
        entry.func = func;
        entry.message = message;

        {
            std::lock_guard<std::mutex> lock(queueMutex_);
            if (logQueue_.size() < MAX_QUEUE_SIZE) {
                logQueue_.push(std::move(entry));
                queueCv_.notify_one();
            }
        }
    }

    // 便捷的日志宏接口
    void debug(const std::string& message) { log(LogLevel::DEBUG, "", 0, "", message); }
    void info(const std::string& message)  { log(LogLevel::INFO, "", 0, "", message); }
    void warn(const std::string& message)  { log(LogLevel::WARN, "", 0, "", message); }
    void error(const std::string& message) { log(LogLevel::ERROR, "", 0, "", message); }
    void fatal(const std::string& message) { log(LogLevel::FATAL, "", 0, "", message); }

private:
    struct LogEntry {
        LogLevel level;
        std::chrono::system_clock::time_point timestamp;
        std::string file;
        int line;
        std::string func;
        std::string message;
    };

    Logger() : running_(false), minLevel_(LogLevel::INFO), maxFileSize_(10 * 1024 * 1024) {}

    Logger(const Logger&) = delete;
    Logger& operator=(const Logger&) = delete;

    void start() {
        running_ = true;
        worker_ = std::thread(&Logger::workerThread, this);
    }

    void stop() {
        if (running_) {
            {
                std::lock_guard<std::mutex> lock(queueMutex_);
                running_ = false;
                queueCv_.notify_all();
            }
            if (worker_.joinable()) {
                worker_.join();
            }
            flush();
        }
    }

    void workerThread() {
        while (running_) {
            LogEntry entry;
            {
                std::unique_lock<std::mutex> lock(queueMutex_);
                queueCv_.wait(lock, [this] { return !logQueue_.empty() || !running_; });

                if (logQueue_.empty() || !running_) break;

                entry = std::move(logQueue_.front());
                logQueue_.pop();
            }

            writeLog(entry);
        }

        // 退出时写入剩余日志
        std::lock_guard<std::mutex> lock(queueMutex_);
        while (!logQueue_.empty()) {
            LogEntry entry = std::move(logQueue_.front());
            logQueue_.pop();
            writeLog(entry);
        }
    }

    void writeLog(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(fileMutex_);

        // 检查文件大小，必要时轮转
        if (std::filesystem::exists(logFile_) && 
            std::filesystem::file_size(logFile_) > maxFileSize_) {
            rotateLogFile();
        }

        // 打开文件（追加模式）
        std::ofstream ofs(logFile_, std::ios::app);
        if (!ofs.is_open()) {
            std::cerr << "Failed to open log file: " << logFile_ << std::endl;
            return;
        }

        // 格式化日志
        auto now = std::chrono::system_clock::to_time_t(entry.timestamp);
        auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
            entry.timestamp.time_since_epoch()) % 1000;

        std::string levelStr;
        switch (entry.level) {
            case LogLevel::DEBUG: levelStr = "DEBUG"; break;
            case LogLevel::INFO:  levelStr = "INFO";  break;
            case LogLevel::WARN:  levelStr = "WARN";  break;
            case LogLevel::ERROR: levelStr = "ERROR"; break;
            case LogLevel::FATAL: levelStr = "FATAL"; break;
        }

        ofs << std::put_time(std::localtime(&now), "%Y-%m-%d %H:%M:%S")
            << '.' << std::setfill('0') << std::setw(3) << ms.count()
            << " [" << levelStr << "] "
            << "[" << entry.file << ":" << entry.line << " " << entry.func << "] "
            << entry.message << std::endl;
    }

    void rotateLogFile() {
        std::string backupFile = logFile_ + "." + 
            std::to_string(std::time(nullptr)) + ".bak";

        try {
            std::filesystem::rename(logFile_, backupFile);
        } catch (const std::exception& e) {
            std::cerr << "Log rotation failed: " << e.what() << std::endl;
        }
    }

    void flush() {
        std::lock_guard<std::mutex> lock(fileMutex_);
        if (currentFile_.is_open()) {
            currentFile_.flush();
        }
    }

    static constexpr size_t MAX_QUEUE_SIZE = 10000;

    std::string logFile_;
    LogLevel minLevel_;
    size_t maxFileSize_;

    std::queue<LogEntry> logQueue_;
    std::mutex queueMutex_;
    std::condition_variable queueCv_;

    std::mutex fileMutex_;
    std::ofstream currentFile_;

    std::atomic<bool> running_;
    std::thread worker_;
};

// 日志宏定义（支持__FILE__、__LINE__、__func__）
#define LOG_DEBUG(msg) Logger::getInstance().log(Logger::LogLevel::DEBUG, __FILE__, __LINE__, __func__, msg)
#define LOG_INFO(msg)  Logger::getInstance().log(Logger::LogLevel::INFO, __FILE__, __LINE__, __func__, msg)
#define LOG_WARN(msg)  Logger::getInstance().log(Logger::LogLevel::WARN, __FILE__, __LINE__, __func__, msg)
#define LOG_ERROR(msg) Logger::getInstance().log(Logger::LogLevel::ERROR, __FILE__, __LINE__, __func__, msg)
#define LOG_FATAL(msg) Logger::getInstance().log(Logger::LogLevel::FATAL, __FILE__, __LINE__, __func__, msg)

// 使用示例
int main() {
    // 初始化日志系统
    Logger::getInstance().init("app.log", Logger::LogLevel::DEBUG, 10 * 1024 * 1024);

    std::thread t1([&]() {
        for (int i = 0; i < 1000; ++i) {
            LOG_INFO("Thread 1 message " + std::to_string(i));
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    });

    std::thread t2([&]() {
        for (int i = 0; i < 1000; ++i) {
            LOG_ERROR("Thread 2 error " + std::to_string(i));
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    });

    t1.join();
    t2.join();

    LOG_FATAL("Application finished");

    return 0;
}
