// 生成统计报告
void generateReport(const std::vector<ActivityData>& activities) {
    if (activities.empty()) {
        std::cout << "📈 暂无数据生成报告" << std::endl;
        return;
    }

    int totalSteps = 0;
    double totalDistance = 0.0, totalCalories = 0.0;
    int maxSteps = 0, minSteps = INT_MAX;

    for (const auto& activity : activities) {
        totalSteps += activity.steps;
        totalDistance += activity.distance;
        totalCalories += activity.caloriesBurned;

        if (activity.steps > maxSteps) maxSteps = activity.steps;
        if (activity.steps < minSteps) minSteps = activity.steps;
    }

    std::cout << "\n=== 健康统计报告 ===" << std::endl;
    std::cout << "总记录天数: " << activities.size() << std::endl;
    std::cout << "平均每日步数: " << totalSteps / activities.size() << std::endl;
    std::cout << "总距离: " << std::fixed << std::setprecision(2) << totalDistance << " KM" << std::endl;
    std::cout << "总消耗: " << std::fixed << std::setprecision(0) << totalCalories << " 卡路里" << std::endl;
    std::cout << "最高步数: " << maxSteps << std::endl;
