// 安全HTML转义函数
std::string htmlEscape(const std::string& input) {
    std::string result;
    for (char c : input) {
        switch (c) {
            case '&': result += "&amp;"; break;
            case '<': result += "&lt;"; break;
            case '>': result += "&gt;"; break;
            case '"': result += "&quot;"; break;
            case '\'': result += "&#39;"; break;
            default: result += c; break;
        }
    }
    return result;
}

// 提取链接并转换为HTML链接
std::string formatWithLinks(const std::string& text) {
    std::string result = htmlEscape(text);
    std::regex urlRegex(R"((https?://[^\s<>"']+))");
    std::sregex_iterator iter(result.begin(), result.end(), urlRegex);
    std::sregex_iterator end;

    std::string formatted;
    size_t lastPos = 0;

    for (; iter != end; ++iter) {
        std::smatch match = *iter;
        formatted += result.substr(lastPos, match.position() - lastPos);
        formatted += "<a href=\"" + match.str() + "\" target=\"_blank\">" + match.str() + "</a>";
        lastPos = match.position() + match.length();
    }
    formatted += result.substr(lastPos);
    return formatted;
}

