// 日志级别枚举
enum class LogLevel {
    DEBUG = 0,
    INFO = 1,
    WARN = 2,
    ERROR = 3,
    FATAL = 4
};

// 日志条目结构体
struct LogEntry {
    std::string timestamp;
    LogLevel level;
    std::string source;
    std::string message;
    std::string thread_id;

    LogEntry() = default;

    LogEntry(const std::string& ts, LogLevel lvl, const std::string& src,
             const std::string& msg, const std::string& tid = "")
        : timestamp(ts), level(lvl), source(src), message(msg), thread_id(tid) {}

    std::string toString() const {
        std::ostringstream oss;
        oss << "[" << timestamp << "] [" << levelToString(level) 
            << "] [" << source << "] [" << thread_id << "] " << message;
        return oss.str();
    }

private:
    static std::string levelToString(LogLevel level) {
        switch (level) {
            case LogLevel::DEBUG: return "DEBUG";
            case LogLevel::INFO: return "INFO";
            case LogLevel::WARN: return "WARN";
            case LogLevel::ERROR: return "ERROR";
            case LogLevel::FATAL: return "FATAL";
            default: return "UNKNOWN";
        }
    }
};

// 日志存储管理器（单例模式，线程安全）
class LogManager {
private:
    static std::unique_ptr<LogManager> instance_;
    static std::mutex instance_mutex_;

    std::vector<LogEntry> log_entries_;
    std::map<std::string, int> level_stats_;
    std::mutex log_mutex_;
    std::string log_file_path_;
    bool persist_to_file_;

    LogManager() : persist_to_file_(true), log_file_path_("app_logs.txt") {
        // 初始化统计
        level_stats_["DEBUG"] = 0;
        level_stats_["INFO"] = 0;
        level_stats_["WARN"] = 0;
        level_stats_["ERROR"] = 0;
        level_stats_["FATAL"] = 0;
    }

public:
    static LogManager& getInstance() {
        std::lock_guard<std::mutex> lock(instance_mutex_);
        if (!instance_) {
            instance_ = std::unique_ptr<LogManager>(new LogManager());
        }
        return *instance_;
    }

    // 解析并存储单个日志条目
    void readLogEntry(const std::string& logEntry) {
        LogEntry entry = parseLogEntry(logEntry);
        if (!entry.message.empty()) {
            storeLogEntry(entry);
        }
    }

    // 批量读取日志文件
    bool readLogFile(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            std::cerr << "无法打开日志文件: " << filePath << std::endl;
            return false;
        }

        std::string line;
        int lineCount = 0;
        while (std::getline(file, line)) {
            readLogEntry(line);
            lineCount++;
        }

        std::cout << "成功读取 " << lineCount << " 行日志" << std::endl;
        file.close();
        return true;
    }

    // 查询日志（支持级别过滤和时间范围）
    std::vector<LogEntry> queryLogs(LogLevel minLevel = LogLevel::DEBUG,
                                  const std::string& startTime = "",
                                  const std::string& endTime = "") {
        std::lock_guard<std::mutex> lock(log_mutex_);
        std::vector<LogEntry> result;

        for (const auto& entry : log_entries_) {
            if (static_cast<int>(entry.level) < static_cast<int>(minLevel)) {
                continue;
            }

            if (!startTime.empty() && entry.timestamp < startTime) {
                continue;
            }

            if (!endTime.empty() && entry.timestamp > endTime) {
                continue;
            }

            result.push_back(entry);
        }
        return result;
    }

    // 获取统计信息
    std::map<std::string, int> getStats() const {
        std::lock_guard<std::mutex> lock(log_mutex_);
        return level_stats_;
    }

    // 导出日志到文件
    bool exportLogs(const std::string& outputPath, LogLevel minLevel = LogLevel::DEBUG) {
        auto logs = queryLogs(minLevel);
        std::ofstream out(outputPath);
        if (!out.is_open()) {
            return false;
        }

        for (const auto& log : logs) {
            out << log.toString() << std::endl;
        }
        out.close();
        return true;
    }

    // 清空日志
    void clearLogs() {
        std::lock_guard<std::mutex> lock(log_mutex_);
        log_entries_.clear();
        for (auto& stat : level_stats_) {
            stat.second = 0;
        }
    }

    size_t getLogCount() const {
        std::lock_guard<std::mutex> lock(log_mutex_);
        return log_entries_.size();
    }

private:
    LogEntry parseLogEntry(const std::string& logEntry) {
        // 支持常见日志格式解析：[2023-12-01 10:30:45] [INFO] [main] message
        std::regex pattern(R"(\[([^\]]+)\]\s+\[([A-Z]+)\]\s+\[([^\]]+)\]\s+(.*))");
        std::smatch match;

        if (std::regex_match(logEntry, match, pattern)) {
            std::string timestamp = match[1].str();
            std::string levelStr = match[2].str();
            std::string source = match[3].str();
            std::string message = match[4].str();

            LogLevel level = stringToLevel(levelStr);
            return LogEntry(timestamp, level, source, message);
        }

        // 备用解析：简单的时间戳格式
        std::regex simplePattern(R"(^(\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2})\s+(.+))");
        if (std::regex_match(logEntry, match, simplePattern)) {
            return LogEntry(match[1].str(), LogLevel::INFO, "unknown", match[2].str());
        }

        return LogEntry("", LogLevel::INFO, "unknown", logEntry);
    }

    LogLevel stringToLevel(const std::string& levelStr) {
        if (levelStr == "DEBUG") return LogLevel::DEBUG;
        if (levelStr == "INFO") return LogLevel::INFO;
        if (levelStr == "WARN") return LogLevel::WARNING;
        if (levelStr == "ERROR") return LogLevel::ERROR;
        if (levelStr == "FATAL") return LogLevel::FATAL;
        return LogLevel::INFO;
    }

    void storeLogEntry(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(log_mutex_);

        // 限制内存使用，保留最近10万条日志
        if (log_entries_.size() >= 100000) {
            log_entries_.erase(log_entries_.begin());
        }

        log_entries_.push_back(entry);

        // 更新统计
        std::string levelName = LogEntry().levelToString(entry.level);
        level_stats_[levelName]++;

        // 持久化到文件
        if (persist_to_file_) {
            appendToFile(entry.toString());
        }
    }

    void appendToFile(const std::string& entry) {
        std::ofstream file(log_file_path_, std::ios::app);
        if (file.is_open()) {
            file << entry << std::endl;
            file.close();
        }
    }
};

