## 优化后的C++代码

```cpp
#include <iostream>
#include <unordered_map>
#include <memory>
#include <string>
#include <weak_ptr>

class SmartHomeDevice {
private:
    std::string device_id_;
    std::string name_;

public:
    SmartHomeDevice(const std::string& device_id, const std::string& name)
        : device_id_(device_id), name_(name) {
        std::cout << "Device " << name_ << " created." << std::endl;
    }

    virtual ~SmartHomeDevice() {
        std::cout << "Device " << name_ << " destroyed." << std::endl;
    }

    const std::string& getName() const { return name_; }
    const std::string& getDeviceId() const { return device_id_; }
};

class SmartHomeController {
private:
    std::unordered_map<std::string, std::shared_ptr<SmartHomeDevice>> strong_devices_;
    std::unordered_map<std::string, std::weak_ptr<SmartHomeDevice>> weak_devices_;

public:
    void addDevice(const std::string& device_id, const std::string& name) {
        auto device = std::make_shared<SmartHomeDevice>(device_id, name);
        strong_devices_[device_id] = device;  // 强引用，保持对象存活
        weak_devices_[device_id] = device;    // 弱引用，允许对象被垃圾回收
        std::cout << "Device '" << name << "' added successfully." << std::endl;
    }

    void removeDevice(const std::string& device_id) {
        auto it = strong_devices_.find(device_id);
        if (it != strong_devices_.end()) {
            strong_devices_.erase(it);  // 删除强引用，使对象可以被垃圾回收
            std::cout << "Device '" << device_id << "' removed." << std::endl;
        } else {
            std::cout << "Device '" << device_id << "' not found." << std::endl;
        }
    }

    void controlDevice(const std::string& device_id, const std::string& command) {
        auto it = strong_devices_.find(device_id);
        if (it != strong_devices_.end()) {
            std::cout << "Controlling device '" << it->second->getName() 
                      << "' with command: " << command << std::endl;
        } else {
            std::cout << "Device '" << device_id << "' not found." << std::endl;
        }
    }

    bool isWeakRefAlive(const std::string& device_id) const {
        auto weak_it = weak_devices_.find(device_id);
        if (weak_it != weak_devices_.end()) {
            return !weak_it->second.expired();
        }
        return false;
    }

    void printWeakRefStatus(const std::string& device_id) const {
        if (isWeakRefAlive(device_id)) {
            std::cout << "Weak reference to device '" << device_id 
                      << "' still exists." << std::endl;
        } else {
            std::cout << "Weak reference to device '" << device_id 
                      << "' has been garbage collected." << std::endl;
        }
    }
};

int main() {
    SmartHomeController controller;

    // 添加设备
    controller.addDevice("light1", "Living Room Light");
    controller.addDevice("thermostat", "Smart Thermostat");

    // 控制设备
    controller.controlDevice("light1", "turn on");

    // 移除设备
    controller.removeDevice("light1");

    // 尝试控制已被移除的设备
    controller.controlDevice("light1", "turn off");

    // 检查弱引用状态
    controller.printWeakRefStatus("light1");
    controller.printWeakRefStatus("thermostat");

    // 清理剩余设备（让析构函数触发）
    controller.removeDevice("thermostat");

    return 0;
}
```

## 关键修改点

1. **智能指针替代Python引用**：
   - `std::shared_ptr` 对应强引用（`strong_devices_`）
   - `std::weak_ptr` 对应弱引用（`weak_devices_`）

2. **RAII内存管理**：
   - 使用析构函数自动清理资源
   - `SmartHomeDevice`析构时自动打印销毁信息

3. **高效容器**：
   - `std::unordered_map` 替代Python字典，提供O(1)查找效率

4. **类型安全**：
   - 显式const引用参数，避免不必要拷贝
   - 添加getter方法封装私有成员

5. **增强功能**：
   - 添加`isWeakRefAlive()`和`printWeakRefStatus()`检查弱引用状态
   - 更详细的日志输出

6. **编译运行**：
```bash
g++ -std=c++17 -Wall -O2 -o smarthome main.cpp
./smarthome
```

