```cpp
#include <iostream>
#include <string>
#include <vector>
#include <curl/curl.h>
#include <sstream>

std::string base_url = "http://yourserver.com/embed_player";

struct ResponseData {
    std::string body;
    std::map<std::string, std::string> headers;
};

size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ResponseData* data = static_cast<ResponseData*>(userp);
    size_t total_size = size * nmemb;
    data->body.append(static_cast<char*>(contents), total_size);
    return total_size;
}

size_t HeaderCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    ResponseData* data = static_cast<ResponseData*>(userp);
    size_t total_size = size * nmemb;
    std::string header(static_cast<char*>(contents), total_size - 1); // -1 to remove \r\n

    // Parse header: "Key: Value"
    size_t colon_pos = header.find(':');
    if (colon_pos != std::string::npos) {
        std::string key = header.substr(0, colon_pos);
        std::string value = header.substr(colon_pos + 1);
        // Trim spaces
        key.erase(0, key.find_first_not_of(" \t"));
        key.erase(key.find_last_not_of(" \t") + 1);
        value.erase(0, value.find_first_not_of(" \t"));
        value.erase(value.find_last_not_of(" \t") + 1);

        data->headers[key] = value;
    }
    return total_size;
}

std::string check_csp_headers(const ResponseData& response) {
    auto it = response.headers.find("Content-Security-Policy");
    if (it != response.headers.end()) {
        std::string csp_header = it->second;
        std::cout << "CSP Header found: " << csp_header << std::endl;

        std::istringstream iss(csp_header);
        std::string directive;
        while (std::getline(iss, directive, ';')) {
            std::string lower_dir = directive;
            // Simple lowercase conversion for matching
            for (char& c : lower_dir) {
                c = std::tolower(c);
            }
            if (lower_dir.find("frame-ancestors") != std::string::npos) {
                std::cout << "Frame-Ancestors Directive: " << directive << std::endl;
                return directive;
            }
        }
    }

    std::cout << "No Frame-Ancestors Directive found." << std::endl;
    return "";
}

int test_embed_from_domain(const std::string& domain, const std::string& referrer = "") {
    CURL* curl;
    CURLcode res;
    ResponseData response_data;

    curl = curl_easy_init();
    if (!curl) {
        std::cout << "Failed to initialize curl for domain: " << domain << std::endl;
        return 1;
    }

    // Set URL
    curl_easy_setopt(curl, CURLOPT_URL, base_url.c_str());

    // Set timeout
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);

    // Set Referer header
    if (!referrer.empty()) {
        struct curl_slist* headers = nullptr;
        std::string referer_header = "Referer: http://" + referrer + "/page.html";
        headers = curl_slist_append(headers, referer_header.c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    }

    // Set callbacks
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response_data);
    curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, HeaderCallback);
    curl_easy_setopt(curl, CURLOPT_HEADERDATA, &response_data);

    // Follow redirects
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    res = curl_easy_perform(curl);

    if (!referrer.empty()) {
        curl_slist_free_all(static_cast<curl_slist*>(curl_easy_getinfo(curl, CURLINFO_PRIVATE, nullptr)));
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        std::cout << "Curl error for domain: " << domain << ", error: " 
                  << curl_easy_strerror(res) << std::endl;
        return 1;
    }

    if (http_code == 200) {
        std::cout << "Request from " << domain << " succeeded." << std::endl;

        std::string csp_directive = check_csp_headers(response_data);

        if (!csp_directive.empty() && 
            csp_directive.find(domain) == std::string::npos && 
            domain != "trusted-source.com") {
            std::cout << "Potential CSP violation detected when loading from " << domain << "." << std::endl;
        } else {
            std::cout << "No apparent CSP violation detected when loading from " << domain << "." << std::endl;
        }
    } else {
        std::cout << "Failed to retrieve data from " << domain 
                  << ", status code: " << http_code << std::endl;
    }

    return 0;
}

