class HttpSession : public std::enable_shared_from_this<HttpSession> {
    net::ip::tcp::socket socket_;
    boost::beast::flat_buffer buffer_;

public:
    explicit HttpSession(net::ip::tcp::socket socket) : socket_(std::move(socket)) {}

    void run() {
        do_read();
    }

private:
    void do_read() {
        auto self = shared_from_this();
        http::async_read(socket_, buffer_, beast_req_,
            [self](boost::beast::error_code ec, [[maybe_unused]] std::size_t n) {
                if (!ec) self->do_write();
            });
    }

    void do_write() {
        auto self = shared_from_this();
        LearningPlatformHandler::handle_request(beast_req_, beast_res_);

        beast_res_.keep_alive(beast_req_.keep_alive());
        http::async_write(socket_, beast_res_,
            [self](boost::beast::error_code ec, [[maybe_unused]] std::size_t n) {
                if (!ec) self->socket_.shutdown(tcp::socket::shutdown_send);
            });
    }

    http::request<http::string_body> beast_req_;
    http::response<http::string_body> beast_res_;
};

// HTTP服务器
class HttpServer {
    net::io_context& ioc_;
    tcp::acceptor acceptor_;

public:
    HttpServer(net::io_context& ioc, tcp::endpoint endpoint)
        : ioc_(ioc), acceptor_(ioc) {
        acceptor_.open(endpoint.protocol());
        acceptor_.set_option(net::socket_base::reuse_address(true));
        acceptor_.bind(endpoint);
        acceptor_.listen();
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            net::make_strand(ioc_),
            [this](boost::beast::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::make_shared<HttpSession>(std::move(socket))->run();
                }
                do_accept();
            });
    }
};

