// 捕获 stdout 输出用于测试
class QuestionTest : public ::testing::Test {
protected:
    void SetUp() override {
        // 清空 stdout 缓冲区
        fflush(stdout);
        // 保存原始 stdout
        original_stdout = stdout;
        // 重定向到管道
        char buf[1024] = {0};
        pipe(pipefd);
        stdout_pipe = fdopen(pipefd[1], "w");
        setbuf(stdout_pipe, nullptr);
    }

    void TearDown() override {
        // 恢复 stdout
        fclose(stdout_pipe);
        close(pipefd[0]);
        stdout = original_stdout;
        fflush(stdout);
    }

    FILE* original_stdout;
    FILE* stdout_pipe;
    int pipefd[2];

    std::string captureOutput() {
        fflush(stdout_pipe);
        close(pipefd[1]);

        char buf[1024] = {0};
        ssize_t bytes = read(pipefd[0], buf, sizeof(buf) - 1);
        if (bytes > 0) {
            buf[bytes] = '\0';
        }

        // 重新打开管道用于下次测试
        pipe(pipefd);
        stdout_pipe = fdopen(pipefd[1], "w");
        setbuf(stdout_pipe, nullptr);

