```cpp
#include <iostream>
#include <string>
#include <regex>
#include <stdexcept>
#include <limits>
#include <cstdint>

class MoneyConverter {
private:
    static constexpr int64_t MAX_CENTS = std::numeric_limits<int64_t>::max() / 100;
    static constexpr int64_t MIN_CENTS = std::numeric_limits<int64_t>::min() / 100;

    // 金额格式：可选负号 + 数字 + 可选小数点 + 最多2位小数
    static const std::regex AMOUNT_REGEX;

public:
    /**
     * 将金额字符串转换为美分（cent）整数
     * @param amountStr 用户输入的金额字符串，如 "123.45", "-0.99", "100"
     * @return 美分整数值
     * @throws std::invalid_argument 格式错误或超出范围
     */
    static int64_t toCents(const std::string& amountStr) {
        if (amountStr.empty()) {
            throw std::invalid_argument("金额不能为空");
        }

        std::string cleaned = cleanAmountString(amountStr);
        if (!std::regex_match(cleaned, AMOUNT_REGEX)) {
            throw std::invalid_argument("无效的金额格式: " + amountStr);
        }

        bool isNegative = (cleaned[0] == '-');
        std::string absAmount = isNegative ? cleaned.substr(1) : cleaned;

        size_t dotPos = absAmount.find('.');
        std::string integerPart, decimalPart;

        if (dotPos != std::string::npos) {
            integerPart = absAmount.substr(0, dotPos);
            decimalPart = absAmount.substr(dotPos + 1);

            // 补齐到2位小数
            while (decimalPart.length() < 2) {
                decimalPart += '0';
            }
            if (decimalPart.length() > 2) {
                decimalPart = decimalPart.substr(0, 2);
            }
        } else {
            integerPart = absAmount;
            decimalPart = "00";
        }

        // 组合整数部分和小数部分
        std::string fullAmount = integerPart + decimalPart;

        // 转换为整数
        int64_t cents = std::stoll(fullAmount);
        if (isNegative) {
            cents = -cents;
        }

        // 范围检查
        if (cents > MAX_CENTS || cents < MIN_CENTS) {
            throw std::invalid_argument("金额超出范围: " + amountStr);
        }

        return cents;
    }

    /**
     * 美分转可读金额字符串
     */
    static std::string fromCents(int64_t cents) {
        bool isNegative = cents < 0;
        int64_t absCents = std::llabs(cents);

        int64_t dollars = absCents / 100;
        int64_t remainingCents = absCents % 100;

        char buffer[64];
        if (isNegative) {
            snprintf(buffer, sizeof(buffer), "-%lld.%02lld", dollars, remainingCents);
        } else {
            snprintf(buffer, sizeof(buffer), "%lld.%02lld", dollars, remainingCents);
        }
        return std::string(buffer);
    }

private:
    static std::string cleanAmountString(const std::string& input) {
        std::string result;
        bool seenDigit = false;
        bool seenDot = false;
        int decimalCount = 0;

        for (char c : input) {
            if (c == '-' && result.empty()) {
                result += '-';
                continue;
            }
            if (c == '+' && result.empty()) {
                continue; // 忽略正号
            }
            if (c >= '0' && c <= '9') {
                result += c;
                seenDigit = true;
                if (seenDot) {
                    decimalCount++;
                    if (decimalCount > 2) {
                        break; // 只保留2位小数
                    }
                }
            } else if (c == '.' && !seenDot && seenDigit) {
                result += '.';
                seenDot = true;
            } else if (c == 'e' || c == 'E') {
                break; // 停止科学计数法处理
            }
            // 忽略空格、逗号等
        }

        if (result.empty() || (!seenDigit && result != "-")) {
            throw std::invalid_argument("无效数字: " + input);
        }

        return result;
    }
};

