class MediaPlayer {
public:
    struct PlayRequest {
        int requestId;
        std::string mediaType;  // "music" or "video"
        std::string fileName;
        std::chrono::steady_clock::time_point startTime;

        PlayRequest(int id, const std::string& type, const std::string& name)
            : requestId(id), mediaType(type), fileName(name),
              startTime(std::chrono::steady_clock::now()) {}
    };

    struct PlayStatus {
        int requestId;
        std::string status;  // "playing", "paused", "stopped", "error"
        std::string currentFile;
        double progress;     // 0.0 - 1.0
        std::chrono::steady_clock::time_point startTime;
    };

    MediaPlayer() : nextRequestId(1), isRunning(true) {
        workerThread = std::thread(&MediaPlayer::processQueue, this);
    }

    ~MediaPlayer() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            isRunning = false;
        }
        queueCV.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    // 发送播放请求
    int sendPlayRequest(const std::string& mediaType, const std::string& fileName) {
        auto request = std::make_shared<PlayRequest>(nextRequestId++, mediaType, fileName);

        {
            std::lock_guard<std::mutex> lock(queueMutex);
            requestQueue.push(request);
        }
        queueCV.notify_one();

        std::cout << "[请求发送] ID:" << request->requestId 
                  << " 类型:" << mediaType 
                  << " 文件:" << fileName << std::endl;
        return request->requestId;
    }

    // 获取播放状态
    std::vector<PlayStatus> getAllStatus() {
        std::lock_guard<std::mutex> lock(statusMutex);
        std::vector<PlayStatus> statuses;
        for (const auto& [id, status] : activePlayers) {
            statuses.push_back(status);
        }
        return statuses;
    }

    // 停止指定播放
    void stopPlayback(int requestId) {
        std::lock_guard<std::mutex> lock(statusMutex);
        auto it = activePlayers.find(requestId);
        if (it != activePlayers.end()) {
            it->second.status = "stopped";
            std::cout << "[播放停止] ID:" << requestId << std::endl;
        }
    }

private:
    void processQueue() {
        while (isRunning) {
            std::shared_ptr<PlayRequest> request;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                queueCV.wait(lock, [this] { return !requestQueue.empty() || !isRunning; });

                if (!isRunning && requestQueue.empty()) break;
                if (!requestQueue.empty()) {
                    request = requestQueue.front();
                    requestQueue.pop();
                }
            }

            if (request) {
                startPlayback(request);
            }
        }
    }

    void startPlayback(const std::shared_ptr<PlayRequest>& request) {
        // 模拟文件匹配和播放
        std::string fullPath = findMediaFile(request->fileName, request->mediaType);

        auto playerThread = std::thread([this, request, fullPath]() {
            PlayStatus status{
                request->requestId,
                "playing",
                fullPath,
                0.0,
                request->startTime
            };

            {
                std::lock_guard<std::mutex> lock(statusMutex);
                activePlayers[request->requestId] = status;
            }

            // 模拟播放过程（实际使用FFmpeg/SDL等）
            simulatePlayback(request->requestId, fullPath);

            // 播放结束清理
            {
                std::lock_guard<std::mutex> lock(statusMutex);
                activePlayers.erase(request->requestId);
            }
            std::cout << "[播放完成] ID:" << request->requestId << std::endl;
        });
        playerThread.detach();
    }

    std::string findMediaFile(const std::string& fileName, const std::string& mediaType) {
        // 模拟文件系统匹配
        std::string extensions[] = {"mp3", "mp4", "avi", "mkv", "wav"};
        for (const auto& ext : extensions) {
            std::string path = "./media/" + mediaType + "/" + fileName + "." + ext;
            if (fileExists(path)) {  // 实际检查文件存在
                return path;
            }
        }
        return "./media/default.mp3";  // 默认文件
    }

    bool fileExists(const std::string& path) {
        // 模拟文件存在检查
        static const std::vector<std::string> mockFiles = {
            "./media/music/rock.mp3", "./media/music/pop.mp4",
            "./media/video/action.mp4", "./media/video/drama.mkv"
        };
        return std::find(mockFiles.begin(), mockFiles.end(), path) != mockFiles.end();
    }

    void simulatePlayback(int requestId, const std::string& filePath) {
        // 模拟不同时长的播放
        std::string fileName = filePath.substr(filePath.find_last_of('/') + 1);
        int duration = (fileName.find("rock") != std::string::npos) ? 5 : 
                      (fileName.find("action") != std::string::npos) ? 8 : 6;

        for (int i = 0; i <= duration && isRunning; ++i) {
            std::this_thread::sleep_for(std::chrono::seconds(1));

            PlayStatus status;
            {
                std::lock_guard<std::mutex> lock(statusMutex);
                auto it = activePlayers.find(requestId);
                if (it == activePlayers.end()) return;
                status = it->second;
            }

            if (status.status != "playing") break;

            status.progress = static_cast<double>(i) / duration;
            {
                std::lock_guard<std::mutex> lock(statusMutex);
                activePlayers[requestId] = status;
            }
        }
    }

    std::queue<std::shared_ptr<PlayRequest>> requestQueue;
    std::unordered_map<int, PlayStatus> activePlayers;

    mutable std::mutex queueMutex;
    mutable std::mutex statusMutex;
    std::condition_variable queueCV;

    int nextRequestId;
    std::atomic<bool> isRunning;
    std::thread workerThread;
};

