class ImageMemoryPool {
private:
    std::vector<cv::Mat> pool_;
    std::mutex mutex_;
    std::queue<size_t> available_;

public:
    explicit ImageMemoryPool(size_t capacity, int width, int height, int channels) {
        pool_.reserve(capacity);
        for (size_t i = 0; i < capacity; ++i) {
            pool_.emplace_back(width, height, CV_8UC3);
            available_.push(i);
        }
    }

    std::span<cv::Mat> acquire() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (available_.empty()) {
            pool_.emplace_back(pool_[0].size(), pool_[0].type());
            available_.push(pool_.size() - 1);
        }
        size_t idx = available_.front();
        available_.pop();
        return std::span{&pool_[idx], 1};
    }

    void release(std::span<const cv::Mat> mats) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto* mat : mats) {
            available_.push(&mat - pool_.data());
        }
    }
};

class ImageFilter {
