public:
    std::string name() const override { return "Grayscale"; }
    void apply(const cv::Mat& src, cv::Mat& dst) const override {
        cv::cvtColor(src, dst, cv::COLOR_BGR2GRAY);
        cv::cvtColor(dst, dst, cv::COLOR_GRAY2BGR);
    }
};

