```go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/gorilla/mux"
)

// Car represents a used car listing
type Car struct {
	ID       string  `json:"id"`
	Brand    string  `json:"brand"`
	Model    string  `json:"model"`
	Price    int     `json:"price"`
	Year     int     `json:"year,omitempty"`
	Mileage  int     `json:"mileage,omitempty"`
	Location string  `json:"location,omitempty"`
}

// CarStore manages car data
type CarStore interface {
	GetAll() ([]Car, error)
	GetByID(id string) (*Car, error)
}

// InMemoryCarStore is a simple in-memory store for demo
type InMemoryCarStore struct {
	cars map[string]Car
}

func NewInMemoryCarStore() *InMemoryCarStore {
	return &InMemoryCarStore{
		cars: map[string]Car{
			"1": {ID: "1", Brand: "Toyota", Model: "Camry", Price: 15000, Year: 2019, Mileage: 45000, Location: "Beijing"},
			"2": {ID: "2", Brand: "Honda", Model: "Civic", Price: 12000, Year: 2020, Mileage: 32000, Location: "Shanghai"},
			"3": {ID: "3", Brand: "Ford", Model: "Focus", Price: 11000, Year: 2018, Mileage: 65000, Location: "Guangzhou"},
			"4": {ID: "4", Brand: "Volkswagen", Model: "Golf", Price: 13500, Year: 2021, Mileage: 28000, Location: "Shenzhen"},
		},
	}
}

func (s *InMemoryCarStore) GetAll() ([]Car, error) {
	var result []Car
	for _, car := range s.cars {
		result = append(result, car)
	}
	return result, nil
}

func (s *InMemoryCarStore) GetByID(id string) (*Car, error) {
	car, exists := s.cars[id]
	if !exists {
		return nil, fmt.Errorf("car not found: %s", id)
	}
	return &car, nil
}

// CarHandler handles car-related HTTP requests
type CarHandler struct {
	store CarStore
}

// getCarsHandler returns all cars
func (h *CarHandler) getCarsHandler(w http.ResponseWriter, r *http.Request) {
	cars, err := h.store.GetAll()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(cars); err != nil {
		log.Printf("Error encoding cars: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
	}
}

// getCarHandler returns a specific car by ID
func (h *CarHandler) getCarHandler(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars["id"]

	car, err := h.store.GetByID(id)
	if err != nil {
		if err.Error() == fmt.Sprintf("car not found: %s", id) {
			http.Error(w, err.Error(), http.StatusNotFound)
			return
		}
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(car); err != nil {
		log.Printf("Error encoding car: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
	}
}

// searchCarsHandler searches cars by query parameters
func (h *CarHandler) searchCarsHandler(w http.ResponseWriter, r *http.Request) {
	// Simple search by brand or model (can be extended for recommendation logic)
	brand := r.URL.Query().Get("brand")
	model := r.URL.Query().Get("model")
	minPrice, _ := parseInt(r.URL.Query().Get("min_price"))
	maxPrice, _ := parseInt(r.URL.Query().Get("max_price"))

	allCars, err := h.store.GetAll()
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	var filtered []Car
	for _, car := range allCars {
		if (brand == "" || containsIgnoreCase(car.Brand, brand)) &&
			(model == "" || containsIgnoreCase(car.Model, model)) &&
			(minPrice == 0 || car.Price >= minPrice) &&
			(maxPrice == 0 || car.Price <= maxPrice) {
			filtered = append(filtered, car)
		}
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(filtered)
}

func parseInt(s string) (int, error) {
	if s == "" {
		return 0, nil
	}
	return strconv.Atoi(s)
}

func containsIgnoreCase(s, substr string) bool {
	sLower, substrLower := strings.ToLower(s), strings.ToLower(substr)
	return strings.Contains(sLower, substrLower)
}

func main() {
	// Initialize store and handler
	store := NewInMemoryCarStore()
	handler := &CarHandler{store: store}

	// Setup router
	r := mux.NewRouter()
	r.HandleFunc("/api/cars", handler.getCarsHandler).Methods("GET")
	r.HandleFunc("/api/cars/{id}", handler.getCarHandler).Methods("GET")
	r.HandleFunc("/api/cars/search", handler.searchCarsHandler).Methods("GET")

	// Add CORS middleware
	r.Use(mux.CORSMethodMiddleware(r))

	// Setup server
	srv := &http.Server{
		Addr:         ":8080",
		Handler:      r,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	// Start server
	go func() {
		log.Println("Server starting on :8080")
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server failed: %v", err)
		}
	}()

	// Graceful shutdown
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit
	log.Println("Shutting down server...")

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := srv.Shutdown(ctx); err != nil {
		log.Fatal("Server forced to shutdown:", err)
	}

	log.Println("Server stopped gracefully")
}
