// 模拟爬取页面的商品信息
func crawlPage(url string, depth int) {
 if depth <= 0 {
  return
 }

 // 模拟发送 HTTP 请求
 resp, err := http.Get(url)
 if err != nil {
  fmt.Println("Error fetching URL:", err)
  return
 }
 defer resp.Body.Close()

 // 模拟从页面提取商品名称、价格和库存等信息
 body := make([]byte, 1000)
 resp.Body.Read(body)
 pageContent := string(body)

 // 假设每个页面包含多个商品信息
 re := regexp.MustCompile(`(?i)<div class="product">.*?name="(.*?)".*?price="(.*?)".*?stock="(.*?)"`)
 matches := re.FindAllStringSubmatch(pageContent, -1)

 // 模拟处理商品数据
 for _, match := range matches {
  productName := match[1]
  price := match[2]
  stock := match[3]
  fmt.Printf("商品名称: %s, 价格: %s, 库存: %s\n", productName, price, stock)
 }

 // 模拟递归爬取下一层级的页面
 // 假设页面包含“下一页”的链接
 nextPage := url + "?page=" + fmt.Sprintf("%d", depth)
 time.Sleep(1 * time.Second) // 模拟延迟，避免过快的请求
 crawlPage(nextPage, depth-1)
}

func main() {
