package main

import (
    "fmt"
    "os"
    "strconv"
    "strings"
)

// Course represents a course in the platform
type Course struct {
    ID    int    `json:"id"`
    Title string `json:"title"`
    Price float64 `json:"price"`
}

// Global course database
var courses = []Course{
    {ID: 1, Title: "Go Programming", Price: 99.99},
    {ID: 2, Title: "Web Development", Price: 129.99},
    {ID: 3, Title: "Data Science", Price: 159.99},
}

// ListCourses displays all available courses
func ListCourses() {
    fmt.Println("\n=== Available Courses ===")
    fmt.Printf("%-4s | %-25s | %8s\n", "ID", "Title", "Price")
    fmt.Println("-----------------------------------------")
    for _, course := range courses {
        fmt.Printf("%-4d | %-25s | $%7.2f\n", course.ID, course.Title, course.Price)
    }
    fmt.Println()
}

// GetCourseDetails returns course by ID or error if not found
func GetCourseDetails(courseID int) (Course, error) {
    for _, course := range courses {
        if course.ID == courseID {
            return course, nil
        }
    }
    return Course{}, fmt.Errorf("course with ID %d not found", courseID)
}

func main() {
    scanner := makeScanner()

    // Display course list first
    ListCourses()

    // Get course ID input
    fmt.Print("Enter course ID to view details (or 'q' to quit): ")
    input := scanner.Text()

    if strings.ToLower(strings.TrimSpace(input)) == "q" {
        fmt.Println("Goodbye!")
        return
    }

    // Parse course ID
    courseID, err := strconv.Atoi(strings.TrimSpace(input))
    if err != nil {
        fmt.Printf("Error: Invalid course ID '%s'. Please enter a number.\n", input)
        return
    }

    // Get course details
    course, err := GetCourseDetails(courseID)
    if err != nil {
        fmt.Fprintln(os.Stderr, "Error:", err)
        return
    }

    // Display course details
    fmt.Printf("\n=== Course Details ===\n")
    fmt.Printf("ID: %d\n", course.ID)
    fmt.Printf("Title: %s\n", course.Title)
    fmt.Printf("Price: $%.2f\n", course.Price)
    fmt.Println("\nThank you for using our course platform!")
}

// makeScanner creates a scanner that properly handles input
func makeScanner() *InputScanner {
    return &InputScanner{
        scanner: makeScannerInternal(),
    }
}

// InputScanner wraps bufio.Scanner for better input handling
type InputScanner struct {
    scanner *bufio.Scanner
}

func (s *InputScanner) Text() string {
    s.scanner.Scan()
    return s.scanner.Text()
}
```

## 关键修改点

1. **修复零值输出bug**：`getCourseDetails` 返回空 `Course{}` 时，程序会打印空标题和 `$0.00`，现在改为返回 `error` 并正确处理未找到情况。

2. **改进输入处理**：
   - 使用 `bufio.Scanner` 替代 `fmt.Scan`，避免空格和换行问题
   - 添加输入验证，支持退出功能（输入 'q'）
   - 正确解析字符串输入为整数

