```go
package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
)

const maxRequestSize = 10 << 20 // 10MB

func uploadProduct(w http.ResponseWriter, r *http.Request) {
	// 检查请求方法
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 检查 Content-Type
	contentType := r.Header.Get("Content-Type")
	if !isMultipartFormData(contentType) {
		http.Error(w, "Content-Type must be multipart/form-data", http.StatusBadRequest)
		return
	}

	// 限制请求体大小
	r.Body = http.MaxBytesReader(w, r.Body, maxRequestSize)
	defer r.Body.Close()

	// 解析 multipart 表单
	if err := r.ParseMultipartForm(maxRequestSize); err != nil {
		http.Error(w, fmt.Sprintf("Failed to parse multipart form: %v", err), http.StatusBadRequest)
		return
	}

	// 获取表单数据（示例：name 和 description）
	name := r.FormValue("name")
	description := r.FormValue("description")

	// 处理文件上传（示例）
	file, header, err := r.FormFile("image")
	if err != nil {
		// 文件非必填，继续处理
		fmt.Printf("Product: Name=%s, Description=%s\n", name, description)
	} else {
		defer file.Close()
		fmt.Printf("Product: Name=%s, Description=%s, File=%s (Size=%d)\n", 
			name, description, header.Filename, header.Size)
	}

	// 返回成功响应
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, `{"status":"success","message":"Product uploaded successfully"}`)
}

func isMultipartFormData(contentType string) bool {
	return contentType != "" && (contentType == "multipart/form-data" || 
		len(contentType) >= 19 && contentType[:19] == "multipart/form-data;")
}

func main() {
	http.HandleFunc("/upload", uploadProduct)

	// 添加简单的健康检查端点
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		fmt.Fprint(w, `{"status":"healthy"}`)
	})

	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```

