package main

import (
	"fmt"
	"errors"
)

// Listing 表示房源信息
type Listing struct {
	ID       int     `json:"id"`
	Name     string  `json:"name"`
	Location string  `json:"location"`
	Price    float64 `json:"price"`
}

// ListingService 管理房源的服务
type ListingService struct {
	listings map[int]Listing // 使用map确保ID唯一性，查询O(1)
	nextID   int
}

// NewListingService 创建新的房源服务
func NewListingService() *ListingService {
	return &ListingService{
		listings: make(map[int]Listing),
		nextID:   1,
	}
}

// AddListing 添加房源（自动生成ID或使用提供的ID）
func (s *ListingService) AddListing(name, location string, price float64) (int, error) {
	listing := Listing{
		ID:       s.nextID,
		Name:     name,
		Location: location,
		Price:    price,
	}
	s.listings[s.nextID] = listing
	s.nextID++
	return s.nextID - 1, nil
}

// GetListing 获取指定ID的房源
func (s *ListingService) GetListing(id int) (Listing, error) {
	if listing, exists := s.listings[id]; exists {
		return listing, nil
	}
	return Listing{}, fmt.Errorf("listing with ID %d not found", id)
}

// ListListings 获取所有房源
func (s *ListingService) ListListings() []Listing {
	result := make([]Listing, 0, len(s.listings))
	for _, listing := range s.listings {
		result = append(result, listing)
	}
	return result
}

// DeleteListing 删除指定ID的房源
func (s *ListingService) DeleteListing(id int) error {
	if _, exists := s.listings[id]; !exists {
		return fmt.Errorf("listing with ID %d not found", id)
	}
	delete(s.listings, id)
	return nil
}

func main() {
	service := NewListingService()

	// 添加房源
	id1, err := service.AddListing("Cozy Apartment", "New York", 120.5)
	if err != nil {
		fmt.Printf("Error adding listing1: %v\n", err)
		return
	}

	id2, err := service.AddListing("Beach House", "Miami", 250.0)
	if err != nil {
