## 优化后的代码

```go
package main

import (
	"fmt"
	"log"
	"net/http"
	"strings"
	"time"
)

// Config 配置参数
type Config struct {
	Addr           string
	ReadTimeout    time.Duration
	WriteTimeout   time.Duration
	IdleTimeout    time.Duration
	MaxHeaderBytes int
}

// AllowedCommands 允许的命令白名单
var AllowedCommands = map[string]bool{
	"on":         true,
	"off":        true,
	"status":     true,
	"brightness": true,
	"color":      true,
}

// AllowedDevices 允许的设备ID前缀白名单
var AllowedDevices = map[string]bool{
	"lamp_":    true,
	"fan_":     true,
	"ac_":      true,
	"curtain_": true,
}

func handleCommand(w http.ResponseWriter, r *http.Request) {
	// 设置请求超时和最大请求体大小
	w.Header().Set("Content-Type", "application/json")

	// 检查HTTP方法
	if r.Method != http.MethodGet {
		http.Error(w, `{"error":"Method not allowed"}`, http.StatusMethodNotAllowed)
		return
	}

	// 参数获取和验证
	deviceID := strings.TrimSpace(r.URL.Query().Get("deviceID"))
	command := strings.TrimSpace(r.URL.Query().Get("command"))

	if deviceID == "" || command == "" {
		http.Error(w, `{"error":"Missing deviceID or command"}`, http.StatusBadRequest)
		return
	}

	// 输入验证 - 防止注入攻击
	if len(deviceID) > 64 || len(command) > 32 {
		http.Error(w, `{"error":"Parameter too long"}`, http.StatusBadRequest)
		return
	}

	// 设备ID格式验证（只允许字母数字下划线）
	if !isValidDeviceID(deviceID) {
		http.Error(w, `{"error":"Invalid deviceID format"}`, http.StatusBadRequest)
		return
	}

	// 命令白名单验证
	if !AllowedCommands[command] {
		http.Error(w, `{"error":"Invalid command"}`, http.StatusBadRequest)
		return
	}

	// 设备前缀白名单验证
	if !isValidDevicePrefix(deviceID) {
		http.Error(w, `{"error":"Unauthorized device"}`, http.StatusForbidden)
		return
	}

	// 模拟设备控制逻辑（实际项目中替换为真实设备控制）
	if err := executeDeviceCommand(deviceID, command); err != nil {
		log.Printf("Failed to execute command for %s: %v", deviceID, err)
		http.Error(w, `{"error":"Command execution failed"}`, http.StatusInternalServerError)
		return
	}

	// 安全响应
	response := fmt.Sprintf(`{"status":"success","device":"%s","command":"%s","timestamp":"%s"}`, 
		escapeJSON(deviceID), escapeJSON(command), time.Now().Format(time.RFC3339))
	fmt.Fprint(w, response)
}

// isValidDeviceID 验证设备ID格式
func isValidDeviceID(id string) bool {
	for _, r := range id {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '_') {
			return false
		}
	}
	return true
}

// isValidDevicePrefix 验证设备前缀
func isValidDevicePrefix(deviceID string) bool {
	for prefix := range AllowedDevices {
		if strings.HasPrefix(deviceID, prefix) {
			return true
		}
	}
	return false
}

// executeDeviceCommand 模拟执行设备命令
func executeDeviceCommand(deviceID, command string) error {
	// TODO: 集成实际的设备控制逻辑
	// 例如 MQTT、WebSocket、数据库操作等
	log.Printf("Executing command '%s' on device '%s'", command, deviceID)
	time.Sleep(100 * time.Millisecond) // 模拟处理时间
	return nil
}

// escapeJSON JSON转义
func escapeJSON(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	s = strings.ReplaceAll(s, "\n", "\\n")
	return s
}

func main() {
	config := &Config{
		Addr:           ":8080",
		ReadTimeout:    10 * time.Second,
		WriteTimeout:   10 * time.Second,
		IdleTimeout:    120 * time.Second,
		MaxHeaderBytes: 1 << 20, // 1MB
	}

	server := &http.Server{
		Addr:           config.Addr,
		ReadTimeout:    config.ReadTimeout,
		WriteTimeout:   config.WriteTimeout,
		IdleTimeout:    config.IdleTimeout,
		MaxHeaderBytes: config.MaxHeaderBytes,
		Handler:        nil,
	}

	// 添加中间件进行额外的安全检查
	http.HandleFunc("/control", securityMiddleware(handleCommand))

	log.Printf("Smart Home Control Server starting on %s", config.Addr)
	log.Printf("Test endpoints:")
	log.Printf("  GET /control?deviceID=lamp_001&command=on")
	log.Printf("  GET /control?deviceID=fan_002&command=off")

	if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("Server failed: %v", err)
	}
}

// securityMiddleware 安全中间件
func securityMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// 速率限制（简单实现）
		// 实际生产环境使用专业的限流器如 golang.org/x/time/rate

		// 检查User-Agent（可选）
		ua := r.UserAgent()
		if strings.Contains(ua, "bot") || strings.Contains(ua, "crawler") {
			http.Error(w, `{"error":"Access denied"}`, http.StatusForbidden)
			return
		}

		next.ServeHTTP(w, r)
	}
}
```

## 关键修改点

### 🔒 **安全修复**
1. **输入验证**：长度限制、字符集白名单、命令白名单、设备前缀验证
2. **XSS防护**：JSON转义输出，防止脚本注入
3. **HTTP方法限制**：只允许GET请求
4. **参数清理**：`strings.TrimSpace()`去除多余空格

### 🛡️ **稳定性增强**
1. **配置化超时**：读写空闲超时防止资源耗尽
2. **错误处理**：结构化JSON错误响应
3. **日志记录**：详细操作日志便于调试和审计
4. **优雅启动**：清晰的启动信息和测试示例

### 🏗️ **架构优化**
1. **模块化设计**：分离验证逻辑、命令执行、安全中间件
2. **白名单机制**：`AllowedCommands`和`AllowedDevices`
3. **标准响应**：统一的JSON响应格式
4. **扩展性**：`executeDeviceCommand`接口便于集成真实设备控制

### 🧪 **测试建议**
```bash
