## 优化后的代码

```go
package main

import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)

// Review represents a single review for a location
type Review struct {
    Location string `json:"location"`
    Rating   int    `json:"rating"`
    Comment  string `json:"comment"`
}

// Reviews is the global slice of reviews (consider using a struct with mutex for concurrency)
var Reviews []Review

// AddReview adds a new review with basic validation
func AddReview(location string, rating int, comment string) error {
    // Validate rating (1-5 scale, TripAdvisor standard)
    if rating < 1 || rating > 5 {
        return fmt.Errorf("rating must be between 1 and 5, got %d", rating)
    }

    review := Review{
        Location: strings.TrimSpace(location),
        Rating:   rating,
        Comment:  strings.TrimSpace(comment),
    }

    // Validate required fields
    if review.Location == "" || review.Comment == "" {
        return fmt.Errorf("location and comment cannot be empty")
    }

    Reviews = append(Reviews, review)
    return nil
}

// GetAverageRating calculates the average rating for a specific location
func GetAverageRating(location string) float64 {
    if len(Reviews) == 0 {
        return 0.0
    }

    total := 0
    count := 0
    for _, review := range Reviews {
        if strings.EqualFold(review.Location, location) {
            total += review.Rating
            count++
        }
    }

    if count == 0 {
        return 0.0
    }
    return float64(total) / float64(count)
}

// PrintReviews displays all reviews with optional filtering
func PrintReviews(filterLocation string) {
    if len(Reviews) == 0 {
        fmt.Println("No reviews available.")
        return
    }

    for i, review := range Reviews {
        if filterLocation == "" || strings.EqualFold(review.Location, filterLocation) {
            fmt.Printf("Review #%d\n", i+1)
            fmt.Printf("  Location: %s\n", review.Location)
            fmt.Printf("  Rating: %d/5 ⭐\n", review.Rating)
            fmt.Printf("  Comment: %s\n", review.Comment)
            fmt.Printf("  Average for %s: %.1f/5\n\n", review.Location, GetAverageRating(review.Location))
        }
    }
}

func main() {
    // Add initial reviews
    if err := AddReview("Paris", 5, "Beautiful city!"); err != nil {
        fmt.Printf("Error adding review: %v\n", err)
    }
    if err := AddReview("New York", 4, "Great experience, but crowded."); err != nil {
        fmt.Printf("Error adding review: %v\n", err)
    }
    if err := AddReview("Tokyo", 3, "Good food, but expensive."); err != nil {
        fmt.Printf("Error adding review: %v\n", err)
    }

    // Display all reviews
    fmt.Println("=== ALL REVIEWS ===")
    PrintReviews("")

    // Interactive mode
    scanner := bufio.NewScanner(os.Stdin)
    for {
        fmt.Print("\nEnter location to add review (or 'quit' to exit): ")
        if !scanner.Scan() {
            break
        }
        input := strings.TrimSpace(scanner.Text())

        if input == "quit" || input == "q" {
            break
        }

        fmt.Print("Enter rating (1-5): ")
        scanner.Scan()
        ratingStr := strings.TrimSpace(scanner.Text())
        rating, err := strconv.Atoi(ratingStr)
        if err != nil {
            fmt.Printf("Invalid rating: %v\n", err)
            continue
        }

        fmt.Print("Enter comment: ")
        scanner.Scan()
        comment := strings.TrimSpace(scanner.Text())

        if err := AddReview(input, rating, comment); err != nil {
            fmt.Printf("Error: %v\n", err)
        } else {
            fmt.Println("Review added successfully!")
            PrintReviews(input)
        }
    }
}
```

## 关键修改点

1. **✅ 修复命名规范**：`reviews` → `Reviews`，函数首字母大写公开API
2. **✅ 添加输入验证**：评分限制1-5，防止空字段
3. **✅ 错误处理**：所有`AddReview`调用返回`error`，优雅处理失败
4. **✅ 增强功能**：
   - 计算每个景点的平均评分
   - 支持按地点过滤显示评论
   - 交互式添加评论功能
5. **✅ 改进输出格式**：更美观的显示，带序号和星级
6. **✅ 输入清理**：`strings.TrimSpace()`去除多余空格
7. **✅ 添加JSON标签**：便于未来序列化到数据库/API
8. **✅ 文档注释**：标准Go文档风格
9. **✅ 健壮性**：空切片检查，避免panic

**运行效果**：现在是一个完整的交互式TripAdvisor系统，支持添加、查看、平均评分计算！

