	ID        string    `json:"id"`
	Content   string    `json:"content"`
	Timestamp time.Time `json:"timestamp"`
}

type App struct {
	mu           sync.RWMutex
	messages     map[string]Message
	limiters     map[string]*rate.Limiter
	authToken    string
	maxMessages  int
	maxMsgSize   int
}

func NewApp() *App {
	return &App{
		messages:    make(map[string]Message, maxMessages),
		limiters:    make(map[string]*rate.Limiter),
		authToken:   authToken,
		maxMessages: maxMessages,
		maxMsgSize:  maxMessageSize,
	}
}

func (a *App) authenticate(r *http.Request) bool {
	token := r.Header.Get("Authorization")
	return token == "Bearer "+a.authToken
}

func (a *App) getLimiter(clientIP string) *rate.Limiter {
	a.mu.Lock()
	defer a.mu.Unlock()

	if limiter, exists := a.limiters[clientIP]; exists {
		return limiter
	}

	limiter = rate.NewLimiter(rate.Every(time.Minute/rateLimitPerMin), rateLimitPerMin)
	a.limiters[clientIP] = limiter
	return limiter
}

func (a *App) cleanOldMessages() {
	a.mu.Lock()
	defer a.mu.Unlock()

	now := time.Now()
	var toDelete []string

	for id, msg := range a.messages {
		if now.Sub(msg.Timestamp) > 24*time.Hour {
			toDelete = append(toDelete, id)
		}
	}

	for _, id := range toDelete {
		delete(a.messages, id)
	}

	// 限制总数量
	if len(a.messages) > a.maxMessages {
		var ids []string
		for id := range a.messages {
			ids = append(ids, id)
		}
		for i := a.maxMessages; i < len(ids); i++ {
			delete(a.messages, ids[i])
		}
	}
}

func (a *App) postMessage(w http.ResponseWriter, r *http.Request) {
	if !a.authenticate(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	clientIP := getClientIP(r)
	if !a.getLimiter(clientIP).Allow() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if r.ContentLength > int64(a.maxMsgSize) {
		http.Error(w, "Message too large", http.StatusRequestEntityTooLarge)
		return
	}

	if err := r.ParseForm(); err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	message := strings.TrimSpace(r.FormValue("message"))
	if len(message) == 0 || len(message) > a.maxMsgSize {
		http.Error(w, "Invalid message length", http.StatusBadRequest)
		return
	}

	// XSS防护 - 简单清理
	safeMsg := strings.ReplaceAll(message, "<script", "")
	safeMsg = strings.ReplaceAll(safeMsg, "</script", "")

	id := fmt.Sprintf("%d", time.Now().UnixNano())
	msg := Message{
		ID:        id,
		Content:   safeMsg,
		Timestamp: time.Now(),
	}

	a.mu.Lock()
	a.messages[id] = msg
	a.mu.Unlock()

	a.cleanOldMessages()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "success", "id": id})
}

func (a *App) getMessages(w http.ResponseWriter, r *http.Request) {
	clientIP := getClientIP(r)
	if !a.getLimiter(clientIP).Allow() {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	// 可选：只允许授权用户获取完整消息
	if !a.authenticate(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	a.mu.RLock()
	defer a.mu.RUnlock()

	messages := make([]Message, 0, len(a.messages))
	for _, msg := range a.messages {
		messages = append(messages, msg)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(messages)
}

func getClientIP(r *http.Request) string {
	if ip := r.Header.Get("X-Forwarded-For"); ip != "" {
		return strings.Split(ip, ",")[0]
	}
	return strings.Split(r.RemoteAddr, ":")[0]
}

func (a *App) healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":     "healthy",
		"messages":   len(a.messages),
		"maxMessages": a.maxMessages,
	})
}

func main() {
	app := NewApp()
	r := mux.NewRouter()

	r.HandleFunc("/health", app.healthCheck).Methods("GET")
	r.HandleFunc("/post", app.postMessage).Methods("POST")
	r.HandleFunc("/get", app.getMessages).Methods("GET")

	// CORS
	r.Use(mux.CORSMethodMiddleware(r))

	// 中间件：日志和恢复
	loggedRouter := middleware(app, r)

	fmt.Println("Server started at :8080")
	log.Fatal(http.ListenAndServe(":8080", loggedRouter))
}

func middleware(app *App, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				log.Printf("Panic recovered: %v", err)
				http.Error(w, "Internal server error", http.StatusInternalServerError)
			}
		}()

		app.cleanOldMessages()
		next.ServeHTTP(w, r)
	})
}
```

## 关键修改点

1. **✅ 身份验证** - Bearer Token认证
2. **✅ 速率限制** - IP级别60次/分钟
3. **✅ 输入验证** - 长度限制+XSS清理
4. **✅ 并发安全** - sync.RWMutex保护
5. **✅ 内存管理** - 最大1000条，24小时过期
6. **✅ JSON API** - 结构化响应
7. **✅ 严格路由** - Gorilla Mux + 方法限制
8. **✅ 错误处理** - 全面panic恢复
9. **✅ 监控** - Health check端点
10. **✅ 中间件** - 日志、清理、CORS

