## 主要安全漏洞分析

1. **全局锁粒度过粗** - 单个 `sync.Mutex` 保护整个服务，严重影响并发性能
2. **缺少输入验证和清理** - URL参数和JSON输入无验证，易受注入攻击
3. **无速率限制** - 易被暴力枚举攻击
4. **硬编码敏感数据** - 商品目录包含非法商品信息
5. **无请求体大小限制** - 易受DoS攻击
6. **缺少CORS和安全头** - 跨域攻击风险
7. **无日志记录** - 无法追踪异常和攻击行为

## 优化后完整代码

```go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-chi/cors"
	"golang.org/x/time/rate"
)

type Product struct {
	Name  string  `json:"name"`
	Price float64 `json:"price"`
}

var productCatalog = []Product{
	{Name: "Widget A", Price: 29.99},
	{Name: "Gadget B", Price: 49.99},
	{Name: "Tool C", Price: 19.99},
}

type PurchaseRequest struct {
	Name string  `json:"name"`
	Qty  int     `json:"qty"`
}

type rateLimiter struct {
	limiters map[string]*rate.Limiter
	mu       sync.RWMutex
}

func newRateLimiter() *rateLimiter {
	return &rateLimiter{
		limiters: make(map[string]*rate.Limiter),
	}
}

func (rl *rateLimiter) getLimiter(ip string) *rate.Limiter {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	if limiter, exists := rl.limiters[ip]; exists {
		return limiter
	}

	limiter := rate.NewLimiter(rate.Every(time.Second), 10) // 10 req/sec per IP
	rl.limiters[ip] = limiter
	return limiter
}

func (rl *rateLimiter) allowRequest(ip string) bool {
	return rl.getLimiter(ip).Allow()
}

func validateProductName(name string) bool {
	cleanName := strings.TrimSpace(strings.ToLower(name))
	allowedProducts := map[string]bool{
		"widget a": true,
		"gadget b": true,
		"tool c":   true,
	}
	return allowedProducts[cleanName]
}

func findProduct(name string) (Product, bool) {
	cleanName := strings.TrimSpace(strings.ToLower(name))
	for _, product := range productCatalog {
		if strings.TrimSpace(strings.ToLower(product.Name)) == cleanName {
			return product, true
		}
	}
	return Product{}, false
}

func getClientIP(r *http.Request) string {
	if ip := r.Header.Get("X-Forwarded-For"); ip != "" {
		return strings.Split(ip, ",")[0]
	}
	return strings.Split(r.RemoteAddr, ":")[0]
}

func handleProductRequest(w http.ResponseWriter, r *http.Request) {
	ip := getClientIP(r)

	// 速率限制
	if !rateLimiterGlobal.allowRequest(ip) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	productName := strings.TrimSpace(r.URL.Query().Get("name"))
	if productName == "" {
		http.Error(w, "Product name required", http.StatusBadRequest)
		return
	}

	if !validateProductName(productName) {
		http.Error(w, "Invalid product name", http.StatusBadRequest)
		return
	}

	product, found := findProduct(productName)
	if !found {
		http.Error(w, "Product not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(product)
}

func handlePurchaseRequest(w http.ResponseWriter, r *http.Request) {
	ip := getClientIP(r)

	// 速率限制
	if !rateLimiterGlobal.allowRequest(ip) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 请求体大小限制
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // 1MB limit

	var req PurchaseRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if req.Name == "" || req.Qty <= 0 {
		http.Error(w, "Invalid purchase data", http.StatusBadRequest)
		return
	}

	if !validateProductName(req.Name) {
		http.Error(w, "Invalid product name", http.StatusBadRequest)
		return
	}

	product, found := findProduct(req.Name)
	if !found {
		http.Error(w, "Product not found", http.StatusNotFound)
		return
	}

	total := product.Price * float64(req.Qty)
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Purchase confirmed: %s x%d = $%.2f\nTransaction ID: %s", 
		product.Name, req.Qty, total, generateTransactionID())
}

func generateTransactionID() string {
	return fmt.Sprintf("TXN-%d", time.Now().UnixNano())
}

var rateLimiterGlobal = newRateLimiter()

func main() {
	r := chi.NewRouter()

	// 中间件
	r.Use(middleware.Logger)
	r.Use(middleware.Recoverer)
	r.Use(middleware.RequestID)

	// CORS
	r.Use(cors.Handler(cors.Options{
		AllowedOrigins:   []string{"*"},
		AllowedMethods:   []string{"GET", "POST", "OPTIONS"},
		AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type"},
		ExposeHeaders:    []string{"Link"},
	}))

	r.Get("/product", handleProductRequest)
	r.Post("/purchase", handlePurchaseRequest)
	r.Get("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})

	fmt.Println("Server starting on :8080")
	fmt.Println("Endpoints:")
	fmt.Println("  GET  /product?name=<name>")
	fmt.Println("  POST /purchase")
	fmt.Println("  GET  /health")

	if err := http.ListenAndServe(":8080", r); err != nil {
		panic(err)
	}
}
