// Order 订单结构体
type Order struct {
	ID          int       `json:"id"`
	OrderNo     string    `json:"order_no"`
	CustomerID  int       `json:"customer_id"`
	TotalAmount float64   `json:"total_amount"`
	Status      string    `json:"status"`
	CreatedAt   time.Time `json:"created_at"`
	UpdatedAt   time.Time `json:"updated_at"`
}

// OrderResponse 统一响应格式
type OrderResponse struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    *Order      `json:"data,omitempty"`
}

// ErrorResponse 错误响应格式
type ErrorResponse struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// DB 数据库连接
var db *sql.DB

// initDB 初始化数据库连接
func initDB() {
	var err error
	// PostgreSQL连接字符串（生产环境建议使用环境变量）
	connStr := "host=localhost port=5432 user=postgres password=postgres dbname=ecommerce sslmode=disable"
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal("数据库连接失败:", err)
	}

	if err = db.Ping(); err != nil {
		log.Fatal("数据库Ping失败:", err)
	}
	log.Println("数据库连接成功")
}

// getOrderByOrderNo 根据订单号查询订单
func getOrderByOrderNo(orderNo string) (*Order, error) {
	query := `
		SELECT id, order_no, customer_id, total_amount, status, created_at, updated_at 
		FROM orders 
		WHERE order_no = $1 AND deleted_at IS NULL
		LIMIT 1`

	row := db.QueryRow(query, orderNo)

	var order Order
	err := row.Scan(
		&order.ID,
		&order.OrderNo,
		&order.CustomerID,
		&order.TotalAmount,
		&order.Status,
		&order.CreatedAt,
		&order.UpdatedAt,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("订单不存在")
		}
		return nil, fmt.Errorf("查询订单失败: %w", err)
	}

	return &order, nil
}

// validateOrderNo 验证订单号格式
func validateOrderNo(orderNo string) bool {
	// 订单号格式: ORD-YYYYMMDD-XXXXXXXX (示例)
	if len(orderNo) < 10 || len(orderNo) > 50 {
		return false
	}
	return true
}

// orderQueryHandler 订单查询HTTP处理器
func orderQueryHandler(w http.ResponseWriter, r *http.Request) {
	// 设置响应头
	w.Header().Set("Content-Type", "application/json; charset=utf-8")

	// 获取订单号
	vars := mux.Vars(r)
	orderNo := vars["order_no"]

	// 参数验证
	if !validateOrderNo(orderNo) {
		resp := ErrorResponse{
			Code:    400,
			Message: "订单号格式不正确",
		}
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(resp)
		return
	}

	// 查询订单
	order, err := getOrderByOrderNo(orderNo)
	if err != nil {
		log.Printf("查询订单失败 order_no=%s, err=%v", orderNo, err)
		resp := ErrorResponse{
			Code:    404,
			Message: err.Error(),
		}
		w.WriteHeader(http.StatusNotFound)
		json.NewEncoder(w).Encode(resp)
		return
	}

	// 成功响应
	resp := OrderResponse{
		Code:    200,
		Message: "查询成功",
		Data:    order,
	}
	json.NewEncoder(w).Encode(resp)
}

// healthCheckHandler 健康检查
func healthCheckHandler(w http.ResponseWriter, r *http.Request) {
	resp := OrderResponse{
		Code:    200,
		Message: "服务正常",
	}
	json.NewEncoder(w).Encode(resp)
}

func main() {
	// 初始化数据库
	initDB()
	defer db.Close()

	// 创建路由器
	r := mux.NewRouter()

	// 订单查询路由 (GET /api/orders/{order_no})
	r.HandleFunc("/api/orders/{order_no}", orderQueryHandler).Methods("GET")

	// 健康检查路由
	r.HandleFunc("/health", healthCheckHandler).Methods("GET")

	// 中间件：请求日志
	r.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			start := time.Now()
			next.ServeHTTP(w, r)
			log.Printf("%s %s %v", r.Method, r.RequestURI, time.Since(start))
		})
	})

	// 启动服务器
	port := ":8080"
	log.Printf("订单查询服务启动在端口 %s", port)
	log.Fatal(http.ListenAndServe(port, r))
}
