// 网络不稳定客户端
type UnstableClient struct {
	client    *http.Client
	baseURL   string
	failureCh chan error
}

func NewUnstableClient(server *httptest.Server) *UnstableClient {
	transport := &http.Transport{
		MaxIdleConns:        100,
		IdleConnTimeout:     30 * time.Second,
		TLSHandshakeTimeout: 10 * time.Second,
	}

	// 模拟网络不稳定：随机超时、重连失败
	client := &http.Client{
		Transport: transport,
		Timeout:   5 * time.Second, // 较短超时模拟差网络
	}

	return &UnstableClient{
		client:  client,
		baseURL: server.URL,
	}
