// TestConcurrentBooking 测试高并发下的网络抖动场景
func TestConcurrentBookingUnderNetworkStress(t *testing.T) {
	service := NewMockBookingService(true, 0.1) // 10%失败率
	server := service.StartServer()
	defer server.Close()

	client := NewUnstableClient(server)

	const numGoroutines = 50
	const classID = "stress_class"
	var wg sync.WaitGroup
	successCount := 0
	var mu sync.Mutex

	for i := 0; i < numGoroutines; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()

			req := BookingRequest{
				UserID:    fmt.Sprintf("user_%d", id),
				ClassID:   classID,
				Timestamp: time.Now().Unix(),
			}

			// 每个请求最多重试2次
			for retry := 0; retry < 2; retry++ {
				success, err := client.BookClass(req)
				if success {
					mu.Lock()
					successCount++
					mu.Unlock()
					return
				}
				if err != nil && retry < 1 {
					time.Sleep(time.Duration(retry+1) * 200 * time.Millisecond)
				}
			}
		}(i)
	}

	wg.Wait()

	t.Logf("Concurrent test: %d/%d requests succeeded under network stress", successCount, numGoroutines)
	if successCount == 0 {
		t.Error("No requests succeeded in concurrent stress test")
	}
}

