以下是比特币钱包应用的用户换绑功能的完整Go代码实现：

```go
package main

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"
)

// User 结构体 - 用户信息
type User struct {
	ID           string    `json:"id"`
	Phone        string    `json:"phone"`
	Email        string    `json:"email"`
	WalletAddr   string    `json:"wallet_addr"`
	Status       string    `json:"status"`        // "active", "pending_change"
	NewPhone     string    `json:"new_phone,omitempty"`
	NewEmail     string    `json:"new_email,omitempty"`
	VerifyCode   string    `json:"verify_code,omitempty"`
	CodeExpiry   time.Time `json:"code_expiry,omitempty"`
	CreatedAt    time.Time `json:"created_at"`
	LastUpdated  time.Time `json:"last_updated"`
}

// WalletService 钱包服务接口
type WalletService interface {
	GenerateAddress() (string, error)
	ValidateAddress(addr string) bool
}

// MemoryWalletService 内存实现的钱包服务
type MemoryWalletService struct{}

func (s *MemoryWalletService) GenerateAddress() (string, error) {
	privKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return "", err
	}

	pubKeyBytes := elliptic.Marshal(elliptic.P256(), privKey.PublicKey.X, privKey.PublicKey.Y)
	hash := sha256.Sum256(pubKeyBytes)
	addr := hex.EncodeToString(hash[:20])
	return addr, nil
}

func (s *MemoryWalletService) ValidateAddress(addr string) bool {
	if len(addr) != 40 {
		return false
	}
	_, err := hex.DecodeString(addr)
	return err == nil
}

// UserService 用户服务
type UserService struct {
	users      map[string]*User
	walletSvc  WalletService
	mu         sync.RWMutex
	verifyCode map[string]string // 临时验证码存储
}

func NewUserService(walletSvc WalletService) *UserService {
	return &UserService{
		users:      make(map[string]*User),
		walletSvc:  walletSvc,
		verifyCode: make(map[string]string),
	}
}

// InitTestUser 初始化测试用户
func (s *UserService) InitTestUser() {
	user := &User{
		ID:        "user123",
		Phone:     "+8612345678901",
		Email:     "user@example.com",
		WalletAddr: "1a2b3c4d5e6f7890abcdef1234567890abcdef12",
		Status:    "active",
		CreatedAt: time.Now(),
		LastUpdated: time.Now(),
	}
	s.mu.Lock()
	s.users[user.ID] = user
	s.mu.Unlock()
}

// RequestChangeBinding 请求换绑
func (s *UserService) RequestChangeBinding(userID, newPhone, newEmail string) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	user, exists := s.users[userID]
	if !exists {
		return "", errors.New("user not found")
	}

	if user.Status == "pending_change" {
		return "", errors.New("change request already pending")
	}

	// 生成6位验证码
	code := fmt.Sprintf("%06d", rand.Intn(1000000))
	s.verifyCode[userID] = code

	user.NewPhone = newPhone
	user.NewEmail = newEmail
	user.Status = "pending_change"
	user.CodeExpiry = time.Now().Add(10 * time.Minute)
	user.LastUpdated = time.Now()

	log.Printf("验证码已发送至新手机号%s: %s (有效期10分钟)", newPhone, code)
	return code, nil
}

// VerifyChangeBinding 验证并完成换绑
func (s *UserService) VerifyChangeBinding(userID, inputCode string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	user, exists := s.users[userID]
	if !exists {
		return errors.New("user not found")
	}

	if user.Status != "pending_change" {
		return errors.New("no pending change request")
	}

	if time.Now().After(user.CodeExpiry) {
		user.Status = "active"
		delete(s.verifyCode, userID)
		return errors.New("verification code expired")
	}

	storedCode, exists := s.verifyCode[userID]
	if !exists || storedCode != inputCode {
		return errors.New("invalid verification code")
	}

	// 验证新联系方式格式
	if !isValidPhone(user.NewPhone) {
		return errors.New("invalid new phone number")
	}
	if user.NewEmail != "" && !isValidEmail(user.NewEmail) {
		return errors.New("invalid new email")
	}

	// 生成新的钱包地址（安全起见）
	newAddr, err := s.walletSvc.GenerateAddress()
	if err != nil {
		return fmt.Errorf("failed to generate new wallet address: %v", err)
	}

	// 更新用户信息
	user.Phone = user.NewPhone
	user.Email = user.NewEmail
	user.WalletAddr = newAddr
	user.Status = "active"
	user.NewPhone = ""
	user.NewEmail = ""
	user.CodeExpiry = time.Time{}
	user.LastUpdated = time.Now()

	// 清理验证码
	delete(s.verifyCode, userID)

	log.Printf("用户%s换绑成功，新钱包地址: %s", userID, newAddr)
	return nil
}

// CancelChangeBinding 取消换绑
func (s *UserService) CancelChangeBinding(userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	user, exists := s.users[userID]
	if !exists {
		return errors.New("user not found")
	}

	if user.Status != "pending_change" {
		return errors.New("no pending change request")
	}

	user.Status = "active"
	user.NewPhone = ""
