package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"time"
)

func fetchProductData(url string) ([]byte, error) {
	// 创建带超时的HTTP客户端，防止请求挂起
	client := &http.Client{
		Timeout: 30 * time.Second, // 30秒总超时
		Transport: &http.Transport{
			MaxIdleConns:        100,              // 最大空闲连接数
			MaxIdleConnsPerHost: 10,               // 每个主机最大空闲连接数
			IdleConnTimeout:     90 * time.Second, // 空闲连接超时
			TLSHandshakeTimeout: 10 * time.Second, // TLS握手超时
			ExpectContinueTimeout: 1 * time.Second,
		},
	}

	// 创建请求上下文，支持更细粒度的超时控制
	ctx, cancel := context.WithTimeout(context.Background(), 25*time.Second)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("创建请求失败: %w", err)
	}

	// 添加User-Agent，模拟真实浏览器请求
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; EcommerceBot/1.0)")
	req.Header.Set("Accept", "application/json, text/plain, */*")
	req.Header.Set("Connection", "keep-alive")

	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("请求失败: %w", err)
	}
	defer resp.Body.Close()

	// 检查HTTP状态码
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("HTTP状态码异常: %d", resp.StatusCode)
	}

	// 限制读取大小，防止内存溢出（适用于电商商品数据）
	limitedReader := io.LimitReader(resp.Body, 10*1024*1024) // 最大10MB
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return nil, fmt.Errorf("读取响应失败: %w", err)
	}

	return body, nil
}

func main() {
	// 示例用法
	url := "https://api.example.com/products/123"
	data, err := fetchProductData(url)
	if err != nil {
		fmt.Printf("获取商品数据失败: %v\n", err)
		return
	}
	fmt.Printf("成功获取商品数据，大小: %d bytes\n", len(data))
	fmt.Printf("数据预览: %s\n", string(data[:100]))
}
```

## 关键修改点：

1. **✅ 添加超时机制**：
   - `http.Client.Timeout: 30s` - 总超时
