	"strings"
)

const (
	maxFileSize     = 10 << 20 // 10MB
	allowedMimeType = "image/svg+xml"
)

func uploadSVG(w http.ResponseWriter, r *http.Request) {
	// 解析表单（必须在FormFile之前调用）
	if err := r.ParseMultipartForm(maxFileSize); err != nil {
		http.Error(w, fmt.Sprintf("Form parse error: %v", err), http.StatusBadRequest)
		return
	}

	// 检查Content-Length
	if r.ContentLength > maxFileSize {
		http.Error(w, fmt.Sprintf("File too large. Max size: %d bytes", maxFileSize), http.StatusRequestEntityTooLarge)
		return
	}

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, fmt.Sprintf("File upload error: %v", err), http.StatusBadRequest)
		return
	}
	defer file.Close()

	// 安全检查1: MIME类型验证
	if header.Header.Get("Content-Type") != allowedMimeType {
		http.Error(w, "Invalid file type. Only SVG files allowed.", http.StatusUnsupportedMediaType)
		return
	}

	// 安全检查2: 文件名扩展名验证
	ext := strings.ToLower(filepath.Ext(header.Filename))
	if ext != ".svg" {
		http.Error(w, "Invalid file extension. Only .svg files allowed.", http.StatusBadRequest)
		return
	}

	// 安全检查3: SVG内容安全扫描（防止XSS等攻击）
	svgContent, err := io.ReadAll(io.LimitReader(file, maxFileSize))
	if err != nil {
		http.Error(w, fmt.Sprintf("Failed to read file: %v", err), http.StatusInternalServerError)
		return
	}

	if !isSafeSVG(string(svgContent)) {
		http.Error(w, "Unsafe SVG content detected.", http.StatusBadRequest)
		return
	}

	// 重置文件指针以便后续处理
	_, err = file.Seek(0, io.SeekStart)
	if err != nil {
		http.Error(w, "Failed to process file", http.StatusInternalServerError)
		return
	}

	// 处理SVG文件（示例：保存到临时目录或数据库）
	projectID := r.FormValue("project_id")
	if projectID == "" {
		http.Error(w, "Missing project_id parameter", http.StatusBadRequest)
		return
	}

	// 示例：保存文件到内存或数据库（实际项目中替换为你的存储逻辑）
	err = saveSVGToProject(projectID, svgContent)
	if err != nil {
		http.Error(w, fmt.Sprintf("Failed to save SVG: %v", err), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintln(w, `{"status":"success","message":"SVG uploaded successfully","project_id":"`+projectID+`"}`)
}

func isSafeSVG(content string) bool {
	// SVG安全检查：防止XSS、脚本注入等
	unsafePatterns := []string{
		`<script`, `<SCRIPT`, `javascript:`, `vbscript:`, `data:`, `onload=`, `onerror=`,
		`xmlns:svg`, `xmlns:xlink`, `expression`, `behaviour`, `binding`,
	}

	contentUpper := strings.ToUpper(content)
	for _, pattern := range unsafePatterns {
		if strings.Contains(contentUpper, pattern) {
			return false
		}
	}

	// 检查是否为有效SVG（简单验证）
	return strings.HasPrefix(strings.TrimSpace(content), "<svg")
}

func saveSVGToProject(projectID string, svgContent []byte) error {
	// 实际项目中：保存到数据库、云存储等
