        button:hover { background: #2980b9; }
    </style>
</head>
<body>
    <h1>🌍 旅游评价网站</h1>

    <h2>提交评价</h2>
    <form id="reviewForm">
        <div class="form-group">
            <input type="text" id="name" placeholder="您的姓名" required>
        </div>
        <div class="form-group">
            <input type="text" id="place" placeholder="旅游地点" required>
        </div>
        <div class="form-group">
            <select id="rating" required>
                <option value="">选择评分 (1-5星)</option>
                <option value="5">⭐⭐⭐⭐⭐ 5星</option>
                <option value="4">⭐⭐⭐⭐ 4星</option>
                <option value="3">⭐⭐⭐ 3星</option>
                <option value="2">⭐⭐ 2星</option>
                <option value="1">⭐ 1星</option>
            </select>
        </div>
        <div class="form-group">
            <textarea id="content" rows="4" placeholder="分享您的旅游体验..." required></textarea>
        </div>
        <button type="submit">提交评价</button>
    </form>

    <h2>最新评价 ({{.Count}}条)</h2>
    <div id="reviewsList">
        {{range .Reviews}}
        <div class="review">
            <h4>{{.Place}} <span class="rating">{{.Rating}}⭐</span></h4>
            <p><strong>{{.Name}}:</strong> {{.Content}}</p>
        </div>
        {{else}}
        <p>暂无评价，快来提交第一条吧！</p>
        {{end}}
    </div>

    <script>
        document.getElementById('reviewForm').addEventListener('submit', async (e) => {
            e.preventDefault();
            const formData = {
                name: document.getElementById('name').value,
                place: document.getElementById('place').value,
                rating: parseInt(document.getElementById('rating').value),
                content: document.getElementById('content').value
            };

            try {
                const response = await fetch('/api/reviews', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify(formData)
                });

                if (response.ok) {
                    document.getElementById('reviewForm').reset();
                    loadReviews();
                } else {
                    alert('提交失败，请重试');
                }
            } catch (error) {
                alert('网络错误，请重试');
            }
        });

        async function loadReviews() {
            const response = await fetch('/api/reviews');
            const reviews = await response.json();
            const container = document.getElementById('reviewsList');
            container.innerHTML = reviews.map(r => 
                `<div class="review">
                    <h4>${r.place} <span class="rating">${r.rating}⭐</span></h4>
                    <p><strong>${r.name}:</strong> ${r.content}</p>
                </div>`
            ).join('');
        }

        // 页面加载时获取评价列表
        loadReviews();
    </script>
</body>
</html>
`

// indexHandler 主页处理函数
func indexHandler(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	data := struct {
		Reviews []Review
		Count   int
	}{
		Reviews: reviews,
		Count:   len(reviews),
	}
	mu.RUnlock()

	t, err := template.New("index").Parse(indexTmpl)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	t.Execute(w, data)
}

// getReviewsHandler 获取所有评价
func getReviewsHandler(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	data := make([]Review, len(reviews))
	copy(data, reviews)
	mu.RUnlock()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(data)
}

// submitReviewHandler 提交评价
func submitReviewHandler(w http.ResponseWriter, r *http.Request) {
	var review Review
	if err := json.NewDecoder(r.Body).Decode(&review); err != nil {
		http.Error(w, "无效的JSON数据", http.StatusBadRequest)
		return
	}

	// 简单验证
	if review.Name == "" || review.Place == "" || review.Content == "" || review.Rating < 1 || review.Rating > 5 {
		http.Error(w, "参数验证失败", http.StatusBadRequest)
		return
	}

	mu.Lock()
	review.ID = nextID
	nextID++
	reviews = append(reviews, review)
	mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(review)
}

func main() {
	// 使用gorilla/mux路由器
	r := mux.NewRouter()

	// 静态页面和API路由
	r.HandleFunc("/", indexHandler).Methods("GET")
	r.HandleFunc("/api/reviews", getReviewsHandler).Methods("GET")
	r.HandleFunc("/api/reviews", submitReviewHandler).Methods("POST")

	// 启动服务器
	fmt.Println("🚀 旅游评价网站启动成功！访问: http://localhost:8080")
	log.Fatal(http.ListenAndServe(":8080", r))
}
