// ReadFile 读取文件内容，返回字符串和错误
func ReadFile(filePath string) (string, error) {
    file, err := os.Open(filePath)
    if err != nil {
        return "", fmt.Errorf("无法打开文件 %s: %w", filePath, err)
    }
