## 优化后的Go代码

```go
package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	uploadDir  = "./uploads"
	maxFileSize = 10 << 20 // 10MB
)

func main() {
	// 创建上传目录
	if err := os.MkdirAll(uploadDir, 0755); err != nil {
		log.Fatal("Failed to create uploads directory:", err)
	}

	// 静态文件服务
	http.Handle("/images/", http.StripPrefix("/images/", http.FileServer(http.Dir(uploadDir))))

	// API路由
	http.HandleFunc("/api/upload", uploadImage)
	http.HandleFunc("/api/images", listImages)

	fmt.Println("Server starting on :8080")
	fmt.Println("Upload endpoint: POST /api/upload")
	fmt.Println("List images: GET /api/images")
	fmt.Println("View images: GET /images/<filename>")

	log.Fatal(http.ListenAndServe(":8080", nil))
}

func uploadImage(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 检查multipart form
	err := r.ParseMultipartForm(maxFileSize)
	if err != nil {
		http.Error(w, "File too large or invalid form", http.StatusBadRequest)
		return
	}

	file, header, err := r.FormFile("image")
	if err != nil {
		http.Error(w, "Missing image file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// 安全文件名处理
	safeFilename := sanitizeFilename(header.Filename)
	if safeFilename == "" {
		http.Error(w, "Invalid filename", http.StatusBadRequest)
		return
	}

	// 生成唯一文件名（避免覆盖）
	ext := filepath.Ext(safeFilename)
	timestamp := time.Now().Format("20060102_150405")
	uniqueFilename := fmt.Sprintf("%s_%s%s", strings.TrimSuffix(safeFilename, ext), timestamp, ext)

	// 保存文件
	dst, err := os.Create(filepath.Join(uploadDir, uniqueFilename))
	if err != nil {
		http.Error(w, "Failed to save file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	_, err = io.Copy(dst, file)
	if err != nil {
		http.Error(w, "Failed to save file", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"message": "Image %s uploaded successfully", "filename": "%s"}`, uniqueFilename, uniqueFilename)
}

func listImages(w http.ResponseWriter, r *http.Request) {
	files, err := os.ReadDir(uploadDir)
	if err != nil {
		http.Error(w, "Failed to read directory", http.StatusInternalServerError)
		return
	}

	var images []string
	for _, file := range files {
		if !file.IsDir() {
			images = append(images, file.Name())
		}
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"images": %s}`, formatImageList(images))
}

func sanitizeFilename(filename string) string {
	// 移除危险字符，只保留字母、数字、点、下划线
	clean := strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '.', r == '_', r == '-':
			return r
		default:
			return -1
		}
	}, filename)

	// 确保有扩展名且不超过255字符
	if ext := filepath.Ext(clean); ext == "" || len(clean) > 255 {
		return ""
	}
	return clean
}

func formatImageList(images []string) string {
	if len(images) == 0 {
		return "[]"
	}

	var sb strings.Builder
	sb.WriteString("[")
	for i, img := range images {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(fmt.Sprintf(`"%s"`, img))
	}
	sb.WriteString("]")
	return sb.String()
}
