// ListDirectory 列出指定路径的目录内容，返回输出结果和错误
func ListDirectory(path string) (string, error) {
	if path == "" {
		return "", fmt.Errorf("path cannot be empty")
	}

	// 清理路径，避免路径注入
	cleanPath := filepath.Clean(path)

	// 安全检查：拒绝访问系统敏感目录
	absPath, err := filepath.Abs(cleanPath)
	if err != nil {
		return "", fmt.Errorf("invalid path: %w", err)
	}

	// 检查是否尝试访问系统目录（可根据需求调整）
	if strings.HasPrefix(absPath, "/") && (strings.HasPrefix(absPath, "/etc") || 
		strings.HasPrefix(absPath, "/proc") || strings.HasPrefix(absPath, "/sys")) {
		return "", fmt.Errorf("access denied to system directory: %s", absPath)
	}

	// 使用context防止命令长时间挂起
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "ls", "-la", cleanPath)

	output, err := cmd.Output()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			return "", fmt.Errorf("command failed (exit code %d): %w", exitErr.ExitCode(), err)
		}
		return "", fmt.Errorf("failed to execute ls: %w", err)
	}

	return string(output), nil
}

func main() {
	path := os.Getenv("STORAGE_PATH")
	if path == "" {
		path = "." // 默认当前目录
	}

	output, err := ListDirectory(path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	fmt.Print(output)
}
