	temperature = make(map[string]int)
	controlRoom("Bedroom", false, 18)
	light, temp = getRoomStatus("Bedroom")
	if light || temp != 18 {
		t.Errorf("Bedroom expected light=false, temp=18, got light=%v, temp=%d", light, temp)
	}

	// Test case 3: Multiple rooms independent control
	lightStatus = make(map[string]bool)
	temperature = make(map[string]int)

	controlRoom("Kitchen", true, 24)
	controlRoom("Bathroom", false, 20)

	kitchenLight, kitchenTemp := getRoomStatus("Kitchen")
	bathroomLight, bathroomTemp := getRoomStatus("Bathroom")

	if !kitchenLight || kitchenTemp != 24 {
		t.Errorf("Kitchen expected light=true, temp=24, got light=%v, temp=%d", kitchenLight, kitchenTemp)
	}
	if bathroomLight || bathroomTemp != 20 {
		t.Errorf("Bathroom expected light=false, temp=20, got light=%v, temp=%d", bathroomLight, bathroomTemp)
	}

	// Test case 4: Non-existent room returns zero values
	light, temp = getRoomStatus("NonExistent")
	if light || temp != 0 {
		t.Errorf("Non-existent room expected light=false, temp=0, got light=%v, temp=%d", light, temp)
	}
}

func TestConcurrentControl(t *testing.T) {
	// Reset maps before test
	lightStatus = make(map[string]bool)
	temperature = make(map[string]int)

	// Simulate concurrent control (sequential for test simplicity)
	rooms := []struct {
		name  string
		light bool
		temp  int
	}{
		{"Living Room", true, 22},
		{"Bedroom", false, 18},
		{"Kitchen", true, 24},
	}

	for _, room := range rooms {
		controlRoom(room.name, room.light, room.temp)
	}

	// Verify all rooms maintain independent states
	for _, room := range rooms {
