package main

import (
	"crypto/sha256"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"testing"
	"time"
)

const testServerURL = "http://example.com"

type MockHTTPClient struct{}

func (m *MockHTTPClient) Do(req *http.Request) (*http.Response, error) {
	if strings.Contains(req.URL.String(), "testuser") {
		return &http.Response{
			StatusCode: http.StatusOK,
			Body:       io.NopCloser(strings.NewReader("mock user data")),
			Header:     make(http.Header),
			Request:    req,
		}, nil
	}
	return &http.Response{
		StatusCode: http.StatusNotFound,
		Body:       io.NopCloser(strings.NewReader("user not found")),
		Header:     make(http.Header),
		Request:    req,
	}, nil
}

func getUserData(client *http.Client, username string) ([]byte, error) {
	u, err := url.Parse(testServerURL + "/getdata")
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %w", err)
	}
	q := u.Query()
	q.Set("user", username)
	u.RawQuery = q.Encode()

	req, err := http.NewRequest("GET", u.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("failed to create request: %w", err)
	}

	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("request failed: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("failed to read response body: %w", err)
	}

	if len(data) == 0 {
		return nil, fmt.Errorf("empty response data")
	}

	return data, nil
}

func TestGetUserData(t *testing.T) {
	tests := []struct {
		name        string
		username    string
		client      *http.Client
		wantHash    string
		expectError bool
	}{
		{
			name:     "valid user",
			username: "testuser",
			client: &http.Client{
				Transport: &MockHTTPClient{},
			},
			wantHash: "a7d8bd2b0a4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b", // mock data hash
		},
		{
			name:        "invalid user",
			username:    "invaliduser",
			client: &http.Client{
				Transport: &MockHTTPClient{},
			},
			expectError: true,
		},
		{
			name:     "empty username",
			username: "",
			client: &http.Client{
				Transport: &MockHTTPClient{},
			},
			expectError: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			data, err := getUserData(tt.client, tt.username)

			if tt.expectError {
				if err == nil {
					t.Errorf("expected error, got nil")
				}
				return
			}

			if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}

			if len(data) == 0 {
				t.Error("expected non-empty data")
				return
			}

			hash := sha256.Sum256(data)
			gotHash := fmt.Sprintf("%x", hash[:])
			if gotHash != "a7d8bd2b0a4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b4b" {
				t.Errorf("hash mismatch: got %s, want %s", gotHash, tt.wantHash)
			}
		})
	}
}

