// main.go
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

const (
	// API配置
	apiBaseURL     = "https://api.realestate.com/v1"
	defaultTimeout = 30 * time.Second
	maxRetries     = 3
)

// Property 房源信息
type Property struct {
	ID          string   `json:"id"`
	Title       string   `json:"title"`
	Price       float64  `json:"price"`
	Address     string   `json:"address"`
	Area        float64  `json:"area"`
	Images      []string `json:"images"`
	Status      string   `json:"status"`
	Description string   `json:"description"`
}

// Agent 经纪人信息
type Agent struct {
	ID      string `json:"id"`
	Name    string `json:"name"`
	Phone   string `json:"phone"`
	Email   string `json:"email"`
	Avatar  string `json:"avatar"`
	Rating  float64 `json:"rating"`
}

// ListPropertiesRequest 房源列表请求参数
type ListPropertiesRequest struct {
	Page     int    `json:"page"`
	Limit    int    `json:"limit"`
	City     string `json:"city,omitempty"`
	MinPrice float64 `json:"min_price,omitempty"`
	MaxPrice float64 `json:"max_price,omitempty"`
}

// ListPropertiesResponse 房源列表响应
type ListPropertiesResponse struct {
	Properties []Property `json:"properties"`
	Total      int64      `json:"total"`
	Page       int        `json:"page"`
	TotalPages int        `json:"total_pages"`
}

// GetPropertyResponse 获取单个房源响应
type GetPropertyResponse struct {
	Property Property `json:"property"`
	Agent    Agent    `json:"agent"`
}

// SendMessageRequest 发送消息请求
type SendMessageRequest struct {
	PropertyID string `json:"property_id"`
	Message    string `json:"message"`
}

// SendMessageResponse 发送消息响应
type SendMessageResponse struct {
	MessageID string `json:"message_id"`
	Status    string `json:"status"`
}

// RealEstateService 房地产API服务接口
type RealEstateService interface {
	ListProperties(ctx context.Context, req ListPropertiesRequest) (*ListPropertiesResponse, error)
	GetProperty(ctx context.Context, propertyID string) (*GetPropertyResponse, error)
	SendMessage(ctx context.Context, req SendMessageRequest) (*SendMessageResponse, error)
}

// realEstateServiceImpl API服务实现
type realEstateServiceImpl struct {
	client     *http.Client
	baseURL    string
	apiKey     string
	httpClient *http.Client
}

// NewRealEstateService 创建服务实例
func NewRealEstateService(apiKey, baseURL string) RealEstateService {
	if baseURL == "" {
		baseURL = apiBaseURL
	}

	return &realEstateServiceImpl{
		baseURL: baseURL,
		apiKey:  apiKey,
		httpClient: &http.Client{
			Timeout: defaultTimeout,
		},
	}
}

// doRequest 通用HTTP请求方法
func (s *realEstateServiceImpl) doRequest(ctx context.Context, method, endpoint string, reqBody interface{}) (*http.Response, error) {
	url := s.baseURL + endpoint

	var body io.Reader
	if reqBody != nil {
		jsonData, err := json.Marshal(reqBody)
		if err != nil {
			return nil, fmt.Errorf("marshal request body: %w", err)
		}
		body = bytes.NewBuffer(jsonData)
	}

	req, err := http.NewRequestWithContext(ctx, method, url, body)
	if err != nil {
		return nil, fmt.Errorf("create request: %w", err)
	}

	// 设置请求头
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+s.apiKey)
	req.Header.Set("User-Agent", "RealEstateClient/1.0")

	// 执行请求，支持重试
	var resp *http.Response
	var err error
	for attempt := 0; attempt < maxRetries; attempt++ {
		resp, err = s.httpClient.Do(req)
		if err == nil && resp.StatusCode < 500 {
			break
		}
		if err != nil {
			log.Printf("attempt %d failed: %v", attempt+1, err)
		} else {
			log.Printf("attempt %d failed with status: %d", attempt+1, resp.StatusCode)
			resp.Body.Close()
		}
		if attempt < maxRetries-1 {
			time.Sleep(time.Duration(attempt+1) * 500 * time.Millisecond)
		}
	}

	if err != nil {
		return nil, fmt.Errorf("request failed after %d attempts: %w", maxRetries, err)
	}

	return resp, nil
}

// ListProperties 获取房源列表
func (s *realEstateServiceImpl) ListProperties(ctx context.Context, req ListPropertiesRequest) (*ListPropertiesResponse, error) {
	query := url.Values{}
	query.Set("page", fmt.Sprintf("%d", req.Page))
	query.Set("limit", fmt.Sprintf("%d", req.Limit))
	if req.City != "" {
		query.Set("city", req.City)
	}
	if req.MinPrice > 0 {
		query.Set("min_price", fmt.Sprintf("%.2f", req.MinPrice))
	}
	if req.MaxPrice > 0 {
		query.Set("max_price", fmt.Sprintf("%.2f", req.MaxPrice))
	}

	endpoint := fmt.Sprintf("/properties?%s", query.Encode())
	resp, err := s.doRequest(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("API error: %s", resp.Status)
	}

	var result ListPropertiesResponse
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, fmt.Errorf("decode response: %w", err)
	}

	return &result, nil
}

// GetProperty 获取单个房源详情
func (s *realEstateServiceImpl) GetProperty(ctx context.Context, propertyID string) (*GetPropertyResponse, error) {
	endpoint := fmt.Sprintf("/properties/%s", url.PathEscape(propertyID))
	resp, err := s.doRequest(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("API error: %s", resp.Status)
	}

	var result GetPropertyResponse
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, fmt.Errorf("decode response: %w", err)
	}

	return &result, nil
}

// SendMessage 发送咨询消息
func (s *realEstateServiceImpl) SendMessage(ctx context.Context, req SendMessageRequest) (*SendMessageResponse, error) {
	endpoint := "/messages"
	resp, err := s.doRequest(ctx, http.MethodPost, endpoint, req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusCreated {
		body, _ := io.ReadAll(resp.Body)
		return nil, fmt.Errorf("API error %d: %s", resp.StatusCode, string(body))
	}

	var result SendMessageResponse
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, fmt.Errorf("decode response: %w", err)
	}

	return &result, nil
}

