            if (!videoUrl) {
                alert('请输入有效的视频链接！');
                return;
            }

            // 支持常见的视频平台iframe嵌入格式转换
            let embedUrl = videoUrl;

            // YouTube 转换
            if (videoUrl.includes('youtube.com/watch') || videoUrl.includes('youtu.be/')) {
                embedUrl = videoUrl.replace(/youtube\.com\/watch\?v=/, 'youtube.com/embed/').replace(/youtu\.be\//, 'youtube.com/embed/');
            }
            // Bilibili 转换
            else if (videoUrl.includes('bilibili.com/video/')) {
                const bvMatch = videoUrl.match(/BV([a-zA-Z0-9]+)/);
                if (bvMatch) {
                    embedUrl = `https://player.bilibili.com/player.html?bvid=${bvMatch[1]}&page=1`;
                }
            }
            // TikTok 转换 (简化处理)
            else if (videoUrl.includes('tiktok.com/@')) {
                embedUrl = videoUrl.replace('www.tiktok.com', 'www.tiktok.com/embed');
            }

            iframe.src = embedUrl + (embedUrl.includes('?') ? '&' : '?') + 'autoplay=0';
            preview.style.display = 'block';
            preview.scrollIntoView({ behavior: 'smooth' });
        }

