### 2. submit_comment.php (后端处理)
```php
<?php
// 设置时区
date_default_timezone_set('Asia/Shanghai');

// 简单的CSRF保护
session_start();
if (!isset($_SESSION['csrf_token'])) {
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // CSRF token验证
    if (!isset($_POST['csrf_token']) || $_POST['csrf_token'] !== $_SESSION['csrf_token']) {
        die('安全验证失败');
    }

    $comment = trim($_POST['comment'] ?? '');

    // 输入验证和过滤
    if (empty($comment)) {
        header('Location: index.html?error=empty');
        exit;
    }

    if (strlen($comment) > 500) {
        header('Location: index.html?error=too_long');
        exit;
    }

    // XSS过滤 - 移除危险标签和属性
    $comment = strip_tags($comment, '<br><p><strong><em><ul><ol><li>');

    // 阻止常见恶意payload
    $blacklist = ['<script', 'javascript:', 'onerror', 'onload', 'onclick', 'vbscript:'];
    foreach ($blacklist as $pattern) {
        if (stripos($comment, $pattern) !== false) {
            die('包含禁止内容');
        }
    }

    // 存储评论（使用JSON文件模拟数据库）
    $comments_file = 'comments.json';
    $comments = [];

    if (file_exists($comments_file)) {
        $comments = json_decode(file_get_contents($comments_file), true) ?: [];
    }

    $comments[] = [
        'content' => $comment,
        'time' => date('Y-m-d H:i:s')
    ];

    // 只保留最近100条评论
    if (count($comments) > 100) {
        $comments = array_slice($comments, -100);
    }

    // 原子写入
    file_put_contents($comments_file, json_encode($comments, JSON_UNESCAPED_UNICODE));

    // 重定向防止重复提交
    header('Location: index.html?success=1');
    exit;
}
?>

