```html
<!DOCTYPE html>
<html lang="zh">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="图片分享平台 - 上传、浏览、评论你的图片">
    <title>图片分享平台</title>

    <!-- 现代化的库引入 - 现代jQuery + 轻量级库 -->
    <script src="https://cdn.jsdelivr.net/npm/jquery@3.7.1/dist/jquery.min.js"></script>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>

    <!-- 现代图片预览库 -->
    <link href="https://cdn.jsdelivr.net/npm/lightbox2@2.11.4/dist/css/lightbox.min.css" rel="stylesheet">
    <script src="https://cdn.jsdelivr.net/npm/lightbox2@2.11.4/dist/js/lightbox.min.js"></script>

    <style>
        .upload-area { border: 2px dashed #007bff; padding: 40px; text-align: center; border-radius: 10px; }
        .upload-area.dragover { background: #e3f2fd; border-color: #2196f3; }
        .image-preview { max-width: 300px; max-height: 300px; margin: 10px 0; border-radius: 8px; }
        .comment-section { margin-top: 15px; }
        .feed-container { max-width: 800px; margin: 20px auto; }
    </style>
</head>
<body class="bg-light">
    <div class="container-fluid feed-container">
        <!-- 上传区域 -->
        <div class="card mb-4">
            <div class="card-header">
                <h3 class="mb-0">📸 上传你的图片</h3>
            </div>
            <div class="card-body">
                <div class="upload-area" id="uploadArea">
                    <i class="fas fa-cloud-upload-alt fa-3x text-primary mb-3"></i>
                    <p class="mb-2">点击选择图片或拖拽上传</p>
                    <input type="file" name="image" id="imageInput" accept="image/*" class="d-none" required>
                    <label for="imageInput" class="btn btn-primary">选择图片</label>
                    <button type="button" id="uploadBtn" class="btn btn-success ms-2" disabled>上传图片</button>
                </div>
                <!-- 预览区域 -->
                <div id="previewArea" class="text-center mt-3" style="display: none;">
                    <img id="previewImg" class="image-preview" alt="预览">
                    <div class="mt-2">
                        <button type="button" id="removePreview" class="btn btn-outline-danger">取消</button>
                    </div>
                </div>
            </div>
        </div>

        <!-- 图片Feed -->
        <div id="feedContainer" class="row">
            <!-- 动态加载图片Feed -->
        </div>
    </div>

    <script>
        $(document).ready(function() {
            let selectedFile = null;

            // 拖拽上传
            const uploadArea = $('#uploadArea');
            uploadArea.on('dragover dragenter', function(e) {
                e.preventDefault();
                e.stopPropagation();
                $(this).addClass('dragover');
            }).on('dragleave dragend', function(e) {
                e.preventDefault();
                e.stopPropagation();
                $(this).removeClass('dragover');
            }).on('drop', function(e) {
                e.preventDefault();
                e.stopPropagation();
                $(this).removeClass('dragover');
                const files = e.originalEvent.dataTransfer.files;
                if (files.length > 0) {
                    handleFile(files[0]);
                }
            });

            // 文件选择
            $('#imageInput').on('change', function(e) {
                if (e.target.files.length > 0) {
                    handleFile(e.target.files[0]);
                }
            });

            function handleFile(file) {
                if (!file.type.startsWith('image/')) {
                    alert('请选择图片文件！');
                    return;
                }
                selectedFile = file;
                const reader = new FileReader();
                reader.onload = function(e) {
                    $('#previewImg').attr('src', e.target.result);
                    $('#uploadArea').hide();
                    $('#previewArea').show();
                    $('#uploadBtn').prop('disabled', false);
                };
                reader.readAsDataURL(file);
            }

            // 移除预览
            $('#removePreview').on('click', function() {
                selectedFile = null;
                $('#previewArea').hide();
                $('#uploadArea').show();
                $('#imageInput').val('');
                $('#uploadBtn').prop('disabled', true);
            });

            // 上传处理
            $('#uploadBtn').on('click', function() {
                if (!selectedFile) return;

                const formData = new FormData();
                formData.append('image', selectedFile);

                $.ajax({
                    url: '/upload',
                    type: 'POST',
                    data: formData,
                    processData: false,
                    contentType: false,
                    beforeSend: function() {
                        $('#uploadBtn').html('<span class="spinner-border spinner-border-sm me-2"></span>上传中...').prop('disabled', true);
