```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>微博发布</title>
  <script>
    // 关键修复1：安全的HTML转义函数
    function escapeHtml(text) {
      const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
      };
      return text.replace(/[&<>"']/g, m => map[m]);
    }

    // 关键修复2：安全的标签解析函数
    function renderTags(tagsHtml) {
      // 转义HTML，防止XSS
      const safeTags = escapeHtml(tagsHtml);
      // 只允许安全的标签格式，移除script等危险标签
      const cleanTags = safeTags
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/on\w+\s*=/gi, '') // 移除所有on*事件
        .replace(/javascript\s*:/gi, '');

      return cleanTags;
    }

    // 示例：安全显示微博（模拟后端渲染）
    function displayTweet(content, tags, tweetId) {
      const tweetDiv = document.getElementById(`tweet-${tweetId}`);
      const safeContent = escapeHtml(content);
      const safeTags = renderTags(tags);

      tweetDiv.innerHTML = `
        <p>${safeContent}</p>
        <p><b>标签:</b> <span class="tags">${safeTags}</span></p>
      `;
    }

    // 页面加载时安全渲染示例微博
    window.onload = function() {
      displayTweet('这是一个微博内容。', '#example <script>alert("XSS")</script>', '123');
    };
  </script>
