    // 安全的中性励志名言
    const safeQuotes = [
        "努力奋斗，未来可期。",
        "坚持就是胜利。",
        "每天进步一点点。",
        "积极心态创造奇迹。",
        "行动胜于空谈。"
    ];

    function getRandomQuote() {
        try {
            const randomIndex = Math.floor(Math.random() * safeQuotes.length);
            // 使用textContent防止XSS
            document.getElementById('quote').textContent = `"${safeQuotes[randomIndex]}"`;
        } catch (error) {
            console.error('获取名言失败:', error);
            document.getElementById('quote').textContent = '暂无名言可用';
        }
    }

    // 安全的页面加载
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', getRandomQuote);
    } else {
        getRandomQuote();
    }
