    <div class="upload-container">
        <h1>📱 发布动态</h1>

        <div class="file-input-wrapper">
            <input type="file" id="fileInput" accept="image/*,video/*" multiple>
            <label for="fileInput" class="file-input-label">
                📎 选择图片或视频
            </label>
        </div>

        <div id="fileInfo" class="file-info" style="display: none;"></div>
        <div id="errorMsg" class="error"></div>

        <img id="preview" alt="媒体预览">
    </div>

    <!-- 安全测试区域 -->
    <div class="security-test">
        <h3>🔒 安全测试</h3>
        <p>尝试在文件名中注入 <code>&lt;script&gt;alert('XSS')&lt;/script&gt;</code> 或其他恶意代码测试防护效果</p>
        <ul>
            <li><strong>CSP:</strong> 严格限制脚本执行</li>
            <li><strong>Blob URL:</strong> 安全预览，无需服务器</li>
            <li><strong>File Validation:</strong> 仅支持媒体文件</li>
            <li><strong>sandbox:</strong> 限制iframe权限</li>
        </ul>
    </div>

    <script>
        (function() {
            'use strict';

            const fileInput = document.getElementById('fileInput');
            const preview = document.getElementById('preview');
            const fileInfo = document.getElementById('fileInfo');
            const errorMsg = document.getElementById('errorMsg');

            // 文件验证正则（防止伪装文件）
            const allowedTypes = {
                image: ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/bmp'],
                video: ['video/mp4', 'video/webm', 'video/ogg']
            };

            function showError(message) {
                errorMsg.textContent = message;
                errorMsg.style.display = 'block';
                preview.style.display = 'none';
                fileInfo.style.display = 'none';
            }

            function hideError() {
                errorMsg.style.display = 'none';
            }

            function sanitizeFilename(filename) {
                // 移除危险字符，防止路径遍历和XSS
                return filename.replace(/[<>:"/\\|?*]+/g, '_').substring(0, 100);
            }

            function validateFile(file) {
                // 类型验证
                if (!allowedTypes.image.includes(file.type) && 
                    !allowedTypes.video.includes(file.type)) {
                    return '仅支持图片(JPG, PNG, GIF, WebP)和视频(MP4, WebM, OGG)';
                }

                // 大小限制：50MB
                if (file.size > 50 * 1024 * 1024) {
                    return '文件大小不能超过50MB';
                }

                // 文件名安全检查
                const suspiciousPatterns = [
                    /script/i, /javascript/i, /vbscript/i, /data:/i, /http:/i
                ];
                const sanitizedName = sanitizeFilename(file.name);
                for (const pattern of suspiciousPatterns) {
                    if (pattern.test(file.name) || pattern.test(sanitizedName)) {
                        return '文件名包含危险字符，已被阻止';
                    }
                }

                return null; // 无错误
            }

            function createPreview(file) {
                const url = URL.createObjectURL(file);
                preview.src = url;
                preview.style.display = 'block';

                // 自动播放视频（静音）
                if (preview.tagName === 'VIDEO') {
                    preview.muted = true;
                    preview.controls = true;
                    preview.play().catch(() => {}); // 忽略播放失败
                }

                // 清理旧的URL
                return () => URL.revokeObjectURL(url);
            }

            fileInput.addEventListener('change', (e) => {
                hideError();

                const files = Array.from(e.target.files);
                if (files.length === 0) return;

                const file = files[0]; // 只预览第一个文件
                const error = validateFile(file);

                if (error) {
                    showError(error);
                    return;
                }

                // 显示安全文件名
                const safeName = sanitizeFilename(file.name);
                fileInfo.innerHTML = `
                    ✅ 文件验证通过<br>
                    📄 名称: <strong>${safeName}</strong><br>
                    📏 大小: ${(file.size / 1024 / 1024).toFixed(1)} MB<br>
                    🕒 类型: ${file.type}
                `;
                fileInfo.style.display = 'block';

                // 创建预览
                const cleanup = createPreview(file);

                // 页面卸载时清理
                window.addEventListener('beforeunload', cleanup, { once: true });
            });

            // 防止拖放XSS
            document.addEventListener('dragover', e => e.preventDefault());
            document.addEventListener('drop', e => {
                e.preventDefault();
                showError('请使用选择文件按钮上传');
            });
        })();
    </script>
</body>
</html>
