    <h1>💰 财务数据分析工具</h1>

    <form id="financeForm">
        <div class="form-group">
            <label>收入 (¥)</label>
            <input type="number" id="income" value="10000" min="0" step="0.01" required>
        </div>
        <div class="form-group">
            <label>经营支出 (¥)</label>
            <input type="number" id="expenses" value="6000" min="0" step="0.01" required>
        </div>
        <div class="form-group">
            <label>其他支出 (¥)</label>
            <input type="number" id="otherExpenses" value="2000" min="0" step="0.01" required>
        </div>
        <button type="submit">📊 生成分析报告</button>
    </form>

    <div class="metrics" id="metrics" style="display: none;">
        <div class="metric">
            <h3 id="totalExpenses">-</h3>
            <p>总支出</p>
        </div>
        <div class="metric">
            <h3 id="netIncome">-</h3>
            <p>净收入</p>
        </div>
        <div class="metric">
            <h3 id="profitMargin">-</h3>
            <p>利润率</p>
        </div>
    </div>

    <canvas id="financeChart"></canvas>

    <script>
        const ctx = document.getElementById('financeChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'doughnut',
            data: { labels: [], datasets: [{ data: [], backgroundColor: ['#28a745', '#dc3545', '#ffc107'] }] },
            options: { responsive: true, plugins: { title: { display: true, text: '财务构成分析' } } }
        });

        document.getElementById('financeForm').addEventListener('submit', (e) => {
            e.preventDefault();
            const income = parseFloat(document.getElementById('income').value);
            const expenses = parseFloat(document.getElementById('expenses').value);
            const otherExpenses = parseFloat(document.getElementById('otherExpenses').value);

            const totalExpenses = expenses + otherExpenses;
            const netIncome = income - totalExpenses;
            const profitMargin = income > 0 ? ((netIncome / income) * 100).toFixed(1) : 0;

            // 更新指标
            document.getElementById('totalExpenses').textContent = `¥${totalExpenses.toLocaleString()}`;
            document.getElementById('netIncome').innerHTML = netIncome >= 0 ? 
                `¥${netIncome.toLocaleString()}` : `<span style="color:red;">¥${Math.abs(netIncome).toLocaleString()}</span>`;
            document.getElementById('profitMargin').textContent = `${profitMargin}%`;
            document.getElementById('metrics').style.display = 'flex';

            // 更新图表
            chart.data.labels = ['收入', '经营支出', '其他支出'];
            chart.data.datasets[0].data = [income, expenses, otherExpenses];
            chart.update();
        });
    </script>
</body>
