        // 模拟评论数据
        const allComments = [
            "Great post! Love this place.",
            "Amazing content, keep it up!",
            "This is exactly what I needed, thank you!",
            "Beautiful photo! Where is this location?",
            "Very inspiring, thanks for sharing!",
