            "Perfect timing, exactly what I was looking for!",
            "Love the composition and colors!",
            "Thanks for the great content!",
            "Bookmarking this for later reference!"
        ];

        let displayedComments = 0;
        const commentsPerLoad = 3;
        let isLoading = false;

        // 初始加载评论
