        // 加载更多评论
        function loadMoreComments() {
            if (isLoading || displayedComments >= allComments.length) return;

            isLoading = true;
            const loadMoreBtn = document.getElementById('loadMoreBtn');
            loadMoreBtn.disabled = true;
            loadMoreBtn.textContent = '加载中...';

            setTimeout(() => {
                const commentsToShow = allComments.slice(displayedComments, displayedComments + commentsPerLoad);

                const commentsSection = document.getElementById('commentsSection');
                commentsToShow.forEach(comment => {
                    const commentDiv = document.createElement('div');
                    commentDiv.className = 'comment';
                    commentDiv.textContent = comment;
                    commentsSection.appendChild(commentDiv);
                });

                displayedComments += commentsToShow.length;
                isLoading = false;
                loadMoreBtn.disabled = false;
                loadMoreBtn.textContent = '加载更多评论';

                // 隐藏按钮如果没有更多评论
                if (displayedComments >= allComments.length) {
                    loadMoreBtn.style.display = 'none';
                }
            }, 600);
        }

        // 页面加载完成后自动加载第一批评论
        window.addEventListener('DOMContentLoaded', loadComments);
    </script>
