        /**
         * 标签清理函数 - 防止XSS攻击
         * @param {Array<string>} tags - 用户输入的标签数组
         * @returns {Array<string>} 清理后的标签数组
         */
        function sanitizeTags(tags) {
            if (!Array.isArray(tags)) {
                throw new Error('标签必须是数组');
            }
            return tags.map(tag => {
                if (typeof tag !== 'string') {
                    return '';
                }
                return tag
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;')
                    .replace(/"/g, '&quot;')
                    .replace(/'/g, '&#x27;');
            });
        }

        // ==================== QUnit 测试套件 ====================
        QUnit.module('标签处理功能测试', {
            beforeEach: function() {
                // 测试前的准备工作
                console.log('开始执行标签处理测试...');
            }
        });

        // 测试1: 正常标签处理
        QUnit.test('正常标签处理 - 普通文本标签', function(assert) {
            const tags = ['summer', 'vacation', 'beach'];
            const result = sanitizeTags(tags);

            assert.deepEqual(result, ['summer', 'vacation', 'beach'], 
                '✓ 普通文本标签保持不变');
            assert.strictEqual(result.length, 3, 
                '✓ 返回数组长度正确');
        });

        // 测试2: XSS防护 - HTML标签转义
        QUnit.test('XSS防护测试 - HTML标签转义', function(assert) {
            const maliciousTags = [
                '<script>alert("xss")</script>',
                '<img src="x" onerror="alert(\'hacked\')">',
                '</div><script>evil()</script><div>'
            ];
            const result = sanitizeTags(maliciousTags);

            const expected = [
                '&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;',
                '&lt;img src=&quot;x&quot; onerror=&quot;alert(&#x27;hacked&#x27;)&quot;&gt;',
                '&lt;/div&gt;&lt;script&gt;evil()&lt;/script&gt;&lt;div&gt;'
            ];

            assert.deepEqual(result, expected, '✓ 所有HTML标签被正确转义');
            result.forEach((tag, i) => {
                assert.notOk(tag.includes('<script'), `✓ 第${i+1}个标签无script标签`);
            });
        });

        // 测试3: 特殊字符标签
        QUnit.test('特殊字符标签处理', function(assert) {
            const specialTags = ['#sunset', '@nature', '$100off', '2024🎉', '测试标签'];
            const result = sanitizeTags(specialTags);

            assert.deepEqual(result, specialTags, 
                '✓ 特殊字符、emoji、Unicode标签保持不变');
            assert.ok(result.every(tag => tag.length > 0), 
                '✓ 所有标签非空');
        });

        // 测试4: 边界情况测试
        QUnit.test('边界情况测试', function(assert) {
            // 空数组
            assert.deepEqual(sanitizeTags([]), [], '✓ 空数组返回空数组');

            // 单标签
            assert.deepEqual(sanitizeTags(['hello']), ['hello'], '✓ 单标签正常处理');

            // 超长标签
            const longTag = 'a'.repeat(200);
            assert.strictEqual(sanitizeTags([longTag])[0].length, 200, 
                '✓ 超长标签完整保留');
        });

        // 测试5: 错误输入处理
        QUnit.test('错误输入处理', function(assert) {
            assert.throws(() => sanitizeTags(null), /标签必须是数组/, 
                '✓ null输入抛出错误');
            assert.throws(() => sanitizeTags(undefined), /标签必须是数组/, 
                '✓ undefined输入抛出错误');
            assert.throws(() => sanitizeTags('string'), /标签必须是数组/, 
                '✓ 字符串输入抛出错误');

            // 非字符串元素
            assert.deepEqual(sanitizeTags(['hello', 123, null, true]), 
                ['hello', '', '', ''], '✓ 非字符串元素转为空字符串');
        });

        // 测试6: 引号转义测试
        QUnit.test('引号和特殊字符转义', function(assert) {
            const quoteTags = ['"double"', "'single'", `backtick\`test\``];
            const result = sanitizeTags(quoteTags);

            assert.strictEqual(result[0], '&quot;double&quot;', 
                '✓ 双引号被转义');
            assert.strictEqual(result[1], '&#x27;single&#x27;', 
                '✓ 单引号被转义');
        });

        // ==================== 性能测试 ====================
        QUnit.test('性能测试 - 大量标签处理', function(assert) {
            const largeTags = Array(1000).fill(0).map((_, i) => 
                `<tag${i}><script>malicious</script>`
            );
            const done = assert.async();

            setTimeout(() => {
                const result = sanitizeTags(largeTags);
                assert.strictEqual(result.length, 1000, 
                    '✓ 1000个恶意标签批量处理成功');
                assert.ok(result.every(tag => tag.includes('&lt;script&gt;')), 
                    '✓ 批量转义正确');
                done();
            }, 0);
        });

        // ==================== 集成测试 ====================
        QUnit.module('集成测试 - 完整上传流程', function() {
            QUnit.test('模拟用户上传完整流程', function(assert) {
                const userInput = {
                    image: 'beach.jpg',
                    tags: ['#summer2024', '<b>bold</b>', '🏖️']
                };

                const processedTags = sanitizeTags(userInput.tags);
                const safeDisplay = processedTags.map(tag => 
                    `<span class="tag">${tag}</span>`
                ).join('');

                assert.strictEqual(processedTags.length, 3, 
                    '✓ 标签数量正确');
                assert.ok(safeDisplay.includes('&lt;b&gt;'), 
                    '✓ 生成的安全HTML包含转义标签');
            });
        });

        // ==================== 测试完成回调 ====================
        QUnit.done(function(details) {
            console.log(`🎉 测试完成！通过: ${details.passed}, 失败: ${details.failed}, 总计: ${details.total}`);

            if (details.failed === 0) {
                console.log('✅ 所有标签处理测试通过！生产环境安全！');
            } else {
                console.error('❌ 测试失败，请修复sanitizeTags函数！');
            }
        });
    </script>
