import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.stream.Collectors;

// 不可变数据类，使用 record (Java 14+，兼容性更好)
record Counselor(int id, String name, String specialty, String password) {}
record Appointment(int id, int clientId, int counselorId, LocalDateTime time) {}
record Record(int id, int counselorId, int clientId, String contentSummary) {}

public class OnlineCounselingService {

    // 使用 ArrayList + Map 组合，查询O(1)，内存更高效
    private static final List<Counselor> counselors = new ArrayList<>();
    private static final Map<Integer, Counselor> counselorIndex = new HashMap<>();
    private static final List<Appointment> appointments = new ArrayList<>();
    private static final Map<Integer, Appointment> appointmentIndex = new HashMap<>();
    private static final List<Record> records = new ArrayList<>();
    private static final Map<Integer, Record> recordIndex = new HashMap<>();

    // 时间格式化器（线程安全复用）
    private static final DateTimeFormatter TIME_FORMATTER = 
        DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

    // ID生成器，避免每次size()计算
    private static int nextCounselorId = 1;
    private static int nextAppointmentId = 1;
    private static int nextRecordId = 1;

    public static void main(String[] args) {
        // 初始化测试数据
        initTestData();

        try (Scanner scanner = new Scanner(System.in)) {
            while (true) {
