                switch (choice) {
                    case 1 -> registerCounselor(scanner);
                    case 2 -> makeAppointment(scanner);
                    case 3 -> listCounselorSchedules();
                    case 4 -> storeRecord(scanner);
                    case 5 -> {
                        System.out.println("感谢使用，已退出平台。");
                        return;
                    }
                    default -> System.out.println("无效的选择，请重新输入。");
                }
            }
        }
