// 增强的反馈对象，适配新闻推荐场景
class FeedbackObject {
    private static final Logger logger = LoggerFactory.getLogger(FeedbackObject.class);
    private static final Pattern SAFE_CONTENT_PATTERN = Pattern.compile("^[\\p{ASCII}]*$");
    private static final int MAX_LENGTH = 1000;

    private String feedbackText;
    private String userId;
    private LocalDateTime timestamp;
    private Map<String, Double> interestScores; // 用户兴趣评分

    public FeedbackObject(String userId, String feedbackText) {
        this.userId = userId;
        this.feedbackText = validateFeedback(feedbackText);
        this.timestamp = LocalDateTime.now();
        this.interestScores = new HashMap<>();
    }

    private String validateFeedback(String text) {
        if (text == null || text.length() > MAX_LENGTH) {
            logger.warn("Feedback too long: {}", text != null ? text.length() : 0);
            throw new IllegalArgumentException("Feedback exceeds max length: " + MAX_LENGTH);
        }
        if (!SAFE_CONTENT_PATTERN.matcher(text).matches()) {
            logger.warn("Unsafe feedback content detected for user: {}", userId);
            throw new IllegalArgumentException("Feedback contains unsafe characters");
        }
        return text;
    }

    // 计算兴趣得分（新闻推荐算法核心）
    public void updateInterestScore(String topic, double score) {
        interestScores.put(topic, Math.max(0.0, Math.min(1.0, score)));
    }

    public Map<String, Double> getInterestScores() {
        return new HashMap<>(interestScores);
    }

    // JSON序列化/反序列化
    public String toJson() throws IOException {
        ObjectMapper mapper = createSafeMapper();
        return mapper.writeValueAsString(this);
    }

    public static FeedbackObject fromJson(String json, String userId) throws IOException {
        ObjectMapper mapper = createSafeMapper();
        FeedbackObject obj = mapper.readValue(json, FeedbackObject.class);
        if (!userId.equals(obj.userId)) {
            throw new SecurityException("User ID mismatch during deserialization");
        }
        return obj;
    }

    private static ObjectMapper createSafeMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, true);
        mapper.configure(DeserializationFeature.FAIL_ON_IGNORED_PROPERTIES, true);
        mapper.registerModule(new JavaTimeModule());
        return mapper;
    }

    // getter/setter
    public String getFeedbackText() { return feedbackText; }
    public String getUserId() { return userId; }
    public LocalDateTime getTimestamp() { return timestamp; }
}

