            logger.info("用户反馈: {}", loaded.getFeedbackText());
            logger.info("兴趣偏好: {}", loaded.getInterestScores());

        } catch (Exception e) {
            logger.error("处理反馈失败", e);
        }
    }

    public void saveFeedback(String userId, FeedbackObject feedback) {
        try {
            String json = feedback.toJson();
            Files.writeString(Paths.get("feedback_" + userId + ".json"), json);
            feedbackCache.put(userId, feedback);
