        } catch (IOException e) {
            logger.error("保存反馈失败", e);
            throw new RuntimeException("Failed to save feedback", e);
        }
    }

    public FeedbackObject loadFeedback(String userId) {
        // 1. 优先从缓存读取（性能优化）
        FeedbackObject cached = feedbackCache.get(userId);
        if (cached != null) {
            logger.debug("缓存命中: {}", userId);
            return cached;
        }

        // 2. 从文件安全读取
        try {
            String json = Files.readString(Paths.get("feedback_" + userId + ".json"));
            FeedbackObject feedback = FeedbackObject.fromJson(json, userId);
            feedbackCache.put(userId, feedback); // 回写缓存
            return feedback;
        } catch (IOException e) {
            logger.warn("读取用户{}反馈失败", userId, e);
            throw new RuntimeException("Failed to load feedback for user: " + userId, e);
        }
    }
}
