```java
import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Properties;

public class OptimizedHttpClient {
    private static final int TIMEOUT_MS = 10000;
    private static final String USER_AGENT = "OptimizedHttpClient/1.0";

    public static void main(String[] args) {
        HttpResponse response = sendPostRequest("https://some_fake_api.com/message", 
                                              "Dear customer, your account has issue, click here to fix...");
        if (response.isSuccess()) {
            System.out.println("Response: " + response.getBody());
        } else {
            System.err.println("Error: " + response.getStatusCode() + " - " + response.getErrorMessage());
        }
    }

    public static HttpResponse sendPostRequest(String url, String message) {
        HttpURLConnection connection = null;
        try {
            URL apiUrl = new URL(url);
            connection = (HttpURLConnection) apiUrl.openConnection();

            // 配置连接
            configureConnection(connection);

            // 发送请求体
            sendRequestBody(connection, message);

            // 读取响应
            return readResponse(connection);

        } catch (IOException e) {
            return HttpResponse.error(0, "Connection failed: " + e.getMessage());
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private static void configureConnection(HttpURLConnection connection) throws IOException {
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "text/plain; charset=UTF-8");
        connection.setRequestProperty("User-Agent", USER_AGENT);
        connection.setConnectTimeout(TIMEOUT_MS);
        connection.setReadTimeout(TIMEOUT_MS);
        connection.setDoOutput(true);
        connection.setUseCaches(false);
        connection.setInstanceFollowRedirects(false);
    }

    private static void sendRequestBody(HttpURLConnection connection, String message) throws IOException {
        try (OutputStream os = new BufferedOutputStream(connection.getOutputStream())) {
            byte[] requestBytes = message.getBytes(StandardCharsets.UTF_8);
            connection.setFixedLengthStreamingMode(requestBytes.length);
            os.write(requestBytes);
        }
    }

    private static HttpResponse readResponse(HttpURLConnection connection) throws IOException {
        int statusCode = connection.getResponseCode();

        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(statusCode >= 400 ? 
                    connection.getErrorStream() : connection.getInputStream(), 
                    StandardCharsets.UTF_8))) {

            StringBuilder responseBody = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                responseBody.append(line).append("\n");
            }

            String body = responseBody.toString().trim();
            return statusCode >= 200 && statusCode < 300 ?
                HttpResponse.success(statusCode, body) :
                HttpResponse.error(statusCode, body.isEmpty() ? "No response body" : body);
        }
    }

    // 响应封装类
    public static class HttpResponse {
        private final boolean success;
        private final int statusCode;
        private final String body;
        private final String errorMessage;

        private HttpResponse(boolean success, int statusCode, String body, String errorMessage) {
            this.success = success;
            this.statusCode = statusCode;
            this.body = body;
            this.errorMessage = errorMessage;
        }

        public static HttpResponse success(int statusCode, String body) {
            return new HttpResponse(true, statusCode, body, null);
        }

        public static HttpResponse error(int statusCode, String errorMessage) {
            return new HttpResponse(false, statusCode, null, errorMessage);
        }

        public boolean isSuccess() { return success; }
        public int getStatusCode() { return statusCode; }
        public String getBody() { return body; }
        public String getErrorMessage() { return errorMessage; }
    }
}
```

