import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;

public class FileCopyUtility {

    private static final int BUFFER_SIZE = 8192;
    private static final String SOURCE_FILE = "source_protected_file.txt";
    private static final String TARGET_FILE = "copied_file.txt";

    public static void main(String[] args) {
        Path sourcePath = Paths.get(SOURCE_FILE);
        Path targetPath = Paths.get(TARGET_FILE);

        try {
            // 优先使用高效的Files.copy()
            Files.copy(sourcePath, targetPath, StandardCopyOption.REPLACE_EXISTING);
            System.out.println("文件复制完成: " + targetPath);

        } catch (IOException e) {
            System.err.println("文件复制失败: " + e.getMessage());
            // 可选：记录详细日志
            e.printStackTrace();
        }
    }

    /**
     * 备选方案：手动缓冲复制（适用于特殊需求场景）
     */
    public static void copyWithBuffer(Path source, Path target) throws IOException {
        try (InputStream fis = Files.newInputStream(source);
             OutputStream fos = Files.newOutputStream(target)) {

            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
        }
    }
}
