import java.util.Scanner;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

class TransactionLog {
    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
    private final List<String> logs = new ArrayList<>();

    public void log(String message) {
        String timestamp = LocalDateTime.now().format(FORMATTER);
        String logEntry = String.format("[%s] %s", timestamp, message);
        logs.add(logEntry);
        System.out.println(logEntry);
    }

    public List<String> getLogs() {
        return new ArrayList<>(logs);
    }
}

class SecureAccount {
    private double balance;
    private final TransactionLog logger;
    private final double MAX_WITHDRAW_LIMIT = 1000000.0; // 单笔最大限额

    public SecureAccount(double initialBalance, TransactionLog logger) {
        if (initialBalance < 0) {
            throw new IllegalArgumentException("初始余额不能为负数");
        }
        this.balance = initialBalance;
        this.logger = logger;
        logger.log("账户初始化，初始余额: " + initialBalance);
    }

    public double getBalance() {
        return balance;
    }

    /**
     * 安全的取款方法 - 金融级事务处理
     * @return true表示取款成功，false表示失败（事务回滚）
