```java
import java.security.SecureRandom;
import java.util.Scanner;

public class PasswordGeneratorSecure {

    private static final SecureRandom SECURE_RANDOM = new SecureRandom();
    private static final int DEFAULT_LENGTH = 12;
    private static final String ALLOWED_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*";

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("请输入密码长度 (默认12): ");
        String input = scanner.nextLine().trim();
        int length = DEFAULT_LENGTH;

        try {
            if (!input.isEmpty()) {
                length = Integer.parseInt(input);
                if (length < 4 || length > 32) {
                    System.out.println("密码长度必须在4-32之间，使用默认长度12");
                    length = DEFAULT_LENGTH;
                }
            }
        } catch (NumberFormatException e) {
            System.out.println("输入无效，使用默认长度12");
        }

        String password = generateSecurePassword(length);
        System.out.println("生成的密码 (" + length + "位): " + password);
        System.out.println("密码强度: 高 (包含大小写字母、数字、特殊字符)");

        scanner.close();
    }

    /**
     * 生成安全的随机密码
     */
    public static String generateSecurePassword(int length) {
        StringBuilder password = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            int randomIndex = SECURE_RANDOM.nextInt(ALLOWED_CHARS.length());
            password.append(ALLOWED_CHARS.charAt(randomIndex));
        }
        return password.toString();
    }

    /**
     * 生成指定字符集的密码
     */
    public static String generateCustomPassword(int length, String charset) {
        if (charset == null || charset.isEmpty()) {
            throw new IllegalArgumentException("字符集不能为空");
        }
        StringBuilder password = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            int randomIndex = SECURE_RANDOM.nextInt(charset.length());
            password.append(charset.charAt(randomIndex));
        }
        return password.toString();
    }
}
