```java
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Scanner;
import java.util.regex.Pattern;

public class OnlineResumeBuilder {

    private static final String RESUME_DIR = "resumes/";
    private static final Pattern SAFE_FILENAME_PATTERN = Pattern.compile("[^a-zA-Z0-9\u4e00-\u9fa5_-]");

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            // 创建简历目录
            createResumeDirectory();

            System.out.println("=== 专业在线简历构建器 ===");

            // 安全输入处理
            String name = getSafeInput(scanner, "请输入您的姓名：");
            String education = getMultiLineInput(scanner, "请输入您的教育背景（多行输入，输入空行结束）：");
            String skills = getMultiLineInput(scanner, "请输入您的技能专长（多行输入，输入空行结束）：");
            String projects = getMultiLineInput(scanner, "请输入您的项目经历（多行输入，输入空行结束）：");

            // 选择简历风格
            int style = selectResumeStyle(scanner);

            // 生成安全文件名
            String safeFileName = generateSafeFileName(name);
            String filePath = RESUME_DIR + safeFileName;

            // 生成不同风格简历
            generateResume(filePath, name, education, skills, projects, style);

            System.out.println("✅ 简历生成成功！文件路径：" + filePath);

        } catch (Exception e) {
            System.err.println("❌ 生成简历失败：" + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    private static String getSafeInput(Scanner scanner, String prompt) {
        System.out.print(prompt);
        String input = scanner.nextLine().trim();
        return input.isEmpty() ? "未填写" : input;
    }

    private static String getMultiLineInput(Scanner scanner, String prompt) {
        System.out.println(prompt);
        StringBuilder sb = new StringBuilder();
        String line;
        while (scanner.hasNextLine()) {
            line = scanner.nextLine().trim();
            if (line.isEmpty()) break;
            sb.append(line).append("\n");
        }
        return sb.toString().trim();
    }

    private static int selectResumeStyle(Scanner scanner) {
        System.out.println("\n请选择简历风格：");
        System.out.println("1. 经典风格");
        System.out.println("2. 现代风格");
        System.out.println("3. 创意风格");
        System.out.print("请输入编号(1-3，默认1)：");

        try {
            String input = scanner.nextLine().trim();
            return input.isEmpty() ? 1 : Integer.parseInt(input);
        } catch (NumberFormatException e) {
            return 1;
        }
    }

    private static String generateSafeFileName(String name) {
        String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
        String safeName = SAFE_FILENAME_PATTERN.matcher(name).replaceAll("_");
        return safeName + "_" + timestamp + ".txt";
    }

    private static void createResumeDirectory() throws IOException {
        Path resumeDir = Paths.get(RESUME_DIR);
        if (!Files.exists(resumeDir)) {
            Files.createDirectory(resumeDir);
        }
    }

    private static void generateResume(String filePath, String name, String education, 
                                    String skills, String projects, int style) throws IOException {

        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath))) {
            switch (style) {
                case 2 -> writeModernStyle(writer, name, education, skills, projects);
                case 3 -> writeCreativeStyle(writer, name, education, skills, projects);
                default -> writeClassicStyle(writer, name, education, skills, projects);
            }
        }
    }

    private static void writeClassicStyle(BufferedWriter writer, String name, String education, 
                                        String skills, String projects) throws IOException {
        writer.write("═══════════════════════════════════════════\n");
        writer.write("                    个人简历\n");
        writer.write("═══════════════════════════════════════════\n\n");
        writeBasicInfo(writer, name, education, skills, projects);
    }

    private static void writeModernStyle(BufferedWriter writer, String name, String education, 
                                       String skills, String projects) throws IOException {
        writer.write("┌──────────────────────────────────────────┐\n");
        writer.write("│               专业简历                    │\n");
        writer.write("└──────────────────────────────────────────┘\n\n");
        writeBasicInfo(writer, name, education, skills, projects);
    }

    private static void writeCreativeStyle(BufferedWriter writer, String name, String education, 
                                         String skills, String projects) throws IOException {
        writer.write("★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★\n");
        writer.write("            ✨ 创意简历 ✨\n");
        writer.write("★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★☆★\n\n");
        writeBasicInfo(writer, name, education, skills, projects);
    }

    private static void writeBasicInfo(BufferedWriter writer, String name, String education, 
                                     String skills, String projects) throws IOException {
        writer.write("📌 姓名     : " + name + "\n\n");
        writer.write("🎓 教育背景 :\n" + formatContent(education) + "\n");
        writer.write("💻 技能专长 :\n" + formatContent(skills) + "\n");
        writer.write("🚀 项目经历 :\n" + formatContent(projects) + "\n");
        writer.write("\n生成时间: " + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
    }

    private static String formatContent(String content) {
        return "   " + content.replace("\n", "\n   ");
    }
}
