## 主要漏洞分析

1. **路径遍历漏洞**：`doGet`直接使用`fileName`构造文件路径，可访问任意文件
2. **任意文件覆盖**：`doPost`未验证`fileName`，可覆盖`../`等敏感文件
3. **目录遍历**：攻击者可写入/读取目录外文件
4. **缺少文件类型验证**：可上传恶意文件
5. **硬编码存储路径**：不安全，缺少权限控制
6. **缺少大小限制**：可导致DoS攻击

## 优化后代码

```java
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import java.util.regex.Pattern;

@WebServlet("/data")
public class PrivacyDataPlatform extends HttpServlet {
    private static final String DATA_STORAGE_FOLDER = "data_storage";
    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
    private static final List<String> ALLOWED_EXTENSIONS = Arrays.asList(".txt", ".pdf", ".docx", ".jpg", ".png");
    private static final Pattern SAFE_FILENAME_PATTERN = Pattern.compile("[a-zA-Z0-9._-]+");

    @Override
    public void init() throws ServletException {
        // 确保目录存在且安全
        Path storagePath = Paths.get(DATA_STORAGE_FOLDER);
        try {
            Files.createDirectories(storagePath);
            storagePath.toFile().setWritable(true, false); // 只允许所有者写入
            storagePath.toFile().setReadable(true, true);
        } catch (IOException e) {
            throw new ServletException("Failed to initialize storage directory", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        response.setContentType("application/json");

        // 验证文件名
        String fileName = request.getParameter("fileName");
        if (!isSafeFileName(fileName)) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid filename");
            return;
        }

        // 检查文件扩展名
        String extension = getFileExtension(fileName);
        if (!ALLOWED_EXTENSIONS.contains(extension.toLowerCase())) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "File type not allowed");
            return;
        }

        // 生成安全的唯一文件名
        String safeFileName = UUID.randomUUID().toString() + extension;
        Path filePath = Paths.get(DATA_STORAGE_FOLDER, safeFileName);

        // 检查文件大小
        long contentLength = request.getContentLengthLong();
        if (contentLength > MAX_FILE_SIZE || contentLength < 0) {
            response.sendError(HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE, "File too large");
            return;
        }

        try (OutputStream fos = Files.newOutputStream(filePath);
             InputStream inputStream = request.getInputStream()) {

            byte[] buffer = new byte[8192];
            long totalRead = 0;
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                totalRead += bytesRead;
                if (totalRead > MAX_FILE_SIZE) {
                    throw new IOException("File size exceeds limit");
                }
                fos.write(buffer, 0, bytesRead);
            }

            // 设置适当的文件权限
            filePath.toFile().setReadable(true, false);
            filePath.toFile().setWritable(false, true);

            response.setStatus(HttpServletResponse.SC_CREATED);
            response.getWriter().write("{\"status\":\"success\",\"filename\":\"" + safeFileName + "\"}");

        } catch (IOException e) {
            if (Files.exists(filePath)) {
                Files.delete(filePath); // 清理不完整文件
            }
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Upload failed");
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        String fileId = request.getParameter("fileId"); // 使用fileId而非fileName
        if (fileId == null || !SAFE_FILENAME_PATTERN.matcher(fileId).matches()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid file ID");
            return;
        }

        Path storagePath = Paths.get(DATA_STORAGE_FOLDER);
        Path filePath = storagePath.resolve(fileId);

        // 严格路径验证 - 防止路径遍历
        if (!filePath.startsWith(storagePath) || Files.isDirectory(filePath)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
            return;
        }

        if (!Files.exists(filePath) || !Files.isRegularFile(filePath)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
            return;
        }

        // 设置合理的超时和缓存控制
        response.setContentType("application/octet-stream");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileId + "\"");
        response.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
        response.setHeader("Pragma", "no-cache");
        response.setDateHeader("Expires", 0);

        try (InputStream fis = Files.newInputStream(filePath);
             OutputStream outputStream = response.getOutputStream()) {

            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }
            outputStream.flush();

        } catch (IOException e) {
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Download failed");
        }
    }

    private boolean isSafeFileName(String fileName) {
        return fileName != null && SAFE_FILENAME_PATTERN.matcher(fileName).matches() 
               && !fileName.contains("..") && fileName.length() <= 100;
    }

    private String getFileExtension(String fileName) {
        if (fileName == null) return "";
        int lastDot = fileName.lastIndexOf('.');
        return lastDot > 0 && lastDot < fileName.length() - 1 ? 
               fileName.substring(lastDot).toLowerCase() : "";
    }
}
```

## 关键修改点

1. **✅ 修复路径遍历**：使用`Path.startsWith()`严格验证路径，UUID随机文件名
2. **✅ 文件名白名单**：正则验证`[a-zA-Z0-9._-]+`，拒绝`../`等危险字符
3. **✅ 文件类型限制**：只允许指定扩展名
4. **✅ 大小限制**：10MB限制，实时监控上传大小
5. **✅ 安全存储**：初始化时设置目录权限，上传后移除写权限
6. **✅ 参数隔离**：`doGet`使用`fileId`而非`fileName`
7. **✅ 错误处理**：统一JSON响应，清理不完整文件
8. **✅ 性能优化**：增大缓冲区到8KB，使用NIO.2 API
9. **✅ 安全头**：添加缓存控制，防止敏感信息缓存

**测试用例**：
```
