public void displayMessage(String message) {
    // 防止XSS攻击：清理用户输入，移除危险的HTML/JS代码
    String cleanMessage = Jsoup.clean(message, Safelist.none());

    // 转义特殊HTML字符，防止注入
    String escapedMessage = cleanMessage
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&#x27;");

    // 构建安全的HTML片段，支持换行显示
    String html = "<html><head>" +
        "<meta charset=\"UTF-8\">" +
        "<style>" +
        "body { font-family: Arial, sans-serif; margin: 20px; line-height: 1.5; }" +
        "p { white-space: pre-wrap; word-wrap: break-word; max-width: 600px; }" +
        "</style>" +
        "</head>" +
        "<body><p>" + escapedMessage + "</p></body></html>";

    // 发送响应（根据实际环境选择方式）
    sendResponse(html);
}

