```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Paths;
import org.apache.http.HttpEntity;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.ContentType;
import org.apache.http.entity.mime.MultipartEntityBuilder;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class FileUploader {

    public static boolean uploadFile(String filePath, String targetUrl) {
        File file = new File(filePath);

        // 1. 文件存在性检查
        if (!file.exists()) {
            System.err.println("❌ 文件不存在: " + filePath);
            return false;
        }
        if (file.length() == 0) {
            System.err.println("❌ 文件为空: " + filePath);
            return false;
        }

        try (CloseableHttpClient httpClient = HttpClients.createDefault();
             InputStream inputStream = new FileInputStream(file);
             CloseableHttpResponse response = null) {  // 提前声明用于finally

            // 2. 构建多部分实体
            MultipartEntityBuilder builder = MultipartEntityBuilder.create();
            builder.addBinaryBody("file", inputStream, ContentType.APPLICATION_OCTET_STREAM, file.getName());
            HttpEntity entity = builder.build();

            // 3. 创建并执行POST请求
            HttpPost httpPost = new HttpPost(targetUrl);
            httpPost.setEntity(entity);

            response = httpClient.execute(httpPost);
            int statusCode = response.getStatusLine().getStatusCode();

            // 4. 详细响应处理
            HttpEntity responseEntity = response.getEntity();
            String responseBody = responseEntity != null ? 
                EntityUtils.toString(responseEntity, "UTF-8") : "无响应体";

            if (statusCode == 200) {
                System.out.println("✅ 文件上传成功: " + file.getName());
                System.out.println("响应: " + responseBody);
                return true;
            } else {
                System.err.println("❌ 上传失败 [HTTP " + statusCode + "]");
                System.err.println("响应: " + responseBody);
                return false;
            }

        } catch (IOException e) {
            System.err.println("❌ 上传异常: " + e.getMessage());
            e.printStackTrace();
            return false;
        }
    }

    public static void main(String[] args) {
        // 支持命令行参数或默认值
        String filePath = args.length > 0 ? args[0] : "example.pdf";
        String targetUrl = args.length > 1 ? args[1] : "https://httpbin.org/post";

        System.out.println("📤 开始上传文件: " + filePath);
        System.out.println("🎯 目标地址: " + targetUrl);

        boolean success = uploadFile(filePath, targetUrl);
        System.out.println(success ? "🎉 上传完成!" : "💥 上传失败!");
    }
}
```

