@WebServlet("/emailSubscription")
public class EmailSubscriptionServlet extends HttpServlet {
    private static final Logger LOGGER = Logger.getLogger(EmailSubscriptionServlet.class.getName());
    private static final Pattern EMAIL_PATTERN = 
        Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) 
            throws ServletException, IOException {
        response.setContentType("application/json;charset=UTF-8");
        response.setStatus(HttpServletResponse.SC_OK);

        String email = request.getParameter("email");

        // 严格的邮箱正则验证
        if (email == null || email.trim().isEmpty() || !EMAIL_PATTERN.matcher(email.trim()).matches()) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            sendJsonResponse(response, false, "Invalid email format");
            LOGGER.warning("Invalid email attempt: " + sanitizeLog(email));
            return;
        }

        String sanitizedEmail = email.trim().toLowerCase();

        // 模拟合法订阅逻辑（实际连接数据库/邮件服务）
        boolean subscribed = processSubscription(sanitizedEmail);

        if (subscribed) {
            LOGGER.info("User subscribed: " + sanitizedEmail);
            sendJsonResponse(response, true, "Subscription successful!");
        } else {
            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            sendJsonResponse(response, false, "Subscription failed. Please try again.");
            LOGGER.severe("Subscription failed for: " + sanitizedEmail);
        }
    }

    private boolean processSubscription(String email) {
        // 实际实现：存入合法数据库、发送确认邮件等
        // 这里模拟成功
        return true;
    }

    private void sendJsonResponse(HttpServletResponse response, boolean success, String message) 
            throws IOException {
        PrintWriter out = response.getWriter();
        out.println("{\"success\":" + success + ",\"message\":\"" + escapeJson(message) + "\"}");
        out.flush();
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\")
                   .replace("\"", "\\\"")
                   .replace("\n", "\\n")
                   .replace("\r", "\\r");
    }

    private String sanitizeLog(String input) {
        return input != null ? input.replaceAll("[^a-zA-Z0-9@._-]", "*") : "null";
    }
}
