```java
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;

import java.io.*;
import java.net.InetSocketAddress;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;

public class FileUploadServer {

    public static class UploadHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, -1);
                return;
            }

            try {
                // 解析multipart/form-data
                MultipartParser parser = new MultipartParser(exchange.getRequestBody());
                Part filePart = parser.parse().get("file");

                if (filePart == null) {
                    sendError(exchange, "无法获取上传文件", 400);
                    return;
                }

                // 创建uploads目录
                Path uploadsDir = Paths.get("uploads");
                Files.createDirectories(uploadsDir);

                // 构建保存路径
                Path filePath = uploadsDir.resolve(filePart.getFilename());

                // 保存文件
                try (InputStream input = filePart.getInputStream();
                     OutputStream output = Files.newOutputStream(filePath, StandardOpenOption.CREATE_NEW)) {
                    input.transferTo(output);
                }

                // 发送成功响应
                String response = "文件已成功保存到: " + filePath.toString();
                exchange.sendResponseHeaders(200, response.length());
                try (OutputStream os = exchange.getResponseBody()) {
                    os.write(response.getBytes());
                }

            } catch (Exception e) {
                sendError(exchange, "服务器错误: " + e.getMessage(), 500);
            }
        }

        private void sendError(HttpExchange exchange, String message, int statusCode) throws IOException {
            exchange.sendResponseHeaders(statusCode, -1);
            String response = message;
            exchange.getResponseHeaders().set("Content-Type", "text/plain");
            exchange.sendResponseHeaders(statusCode, response.length());
            try (OutputStream os = exchange.getResponseBody()) {
                os.write(response.getBytes());
            }
        }
    }

    // 简化的Multipart解析器
    public static class MultipartParser {
        private InputStream input;

        public MultipartParser(InputStream input) {
            this.input = input;
        }

        public java.util.Map<String, Part> parse() throws IOException {
            java.util.Map<String, Part> parts = new java.util.HashMap<>();

            // 读取Content-Type中的boundary
            String contentType = System.getProperty("content-type", "");
            String boundary = extractBoundary(contentType);
            if (boundary.isEmpty()) {
                throw new IOException("未找到boundary");
            }

            byte[] boundaryBytes = ("--" + boundary + "\r\n").getBytes();
            byte[] buffer = new byte[4096];
            int bytesRead;

            while ((bytesRead = input.read(buffer)) != -1) {
                // 简化的解析逻辑 - 查找文件部分
                Part part = parsePart(buffer, 0, bytesRead, boundaryBytes);
                if (part != null && !part.getFilename().isEmpty()) {
                    parts.put("file", part);
                    break;
                }
            }

            return parts;
        }

        private String extractBoundary(String contentType) {
            int boundaryIndex = contentType.indexOf("boundary=");
            if (boundaryIndex == -1) return "";
            return contentType.substring(boundaryIndex + 9).trim();
        }

        private Part parsePart(byte[] data, int offset, int length, byte[] boundary) {
            // 简化的解析 - 实际生产环境需要更robust的解析器
            String content = new String(data, offset, length);
            String filename = extractFilename(content);
            if (!filename.isEmpty()) {
                return new Part(filename, new ByteArrayInputStream(data));
            }
            return null;
        }

        private String extractFilename(String content) {
            int filenameStart = content.indexOf("filename=\"");
            if (filenameStart == -1) return "";
            filenameStart += 10;
            int filenameEnd = content.indexOf("\"", filenameStart);
            return filenameEnd != -1 ? content.substring(filenameStart, filenameEnd) : "";
        }
    }

    // 文件部分表示类
    public static class Part {
        private String filename;
        private InputStream inputStream;

        public Part(String filename, InputStream inputStream) {
            this.filename = filename;
            this.inputStream = inputStream;
        }

        public String getFilename() { return filename; }
        public InputStream getInputStream() { return inputStream; }
    }

    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/upload", new UploadHandler());
        server.setExecutor(null);
        server.start();

        System.out.println("服务器启动在 http://localhost:8080");
        System.out.println("上传接口: http://localhost:8080/upload");
    }
}
```

## 关键修改点：

1. **HTTP框架替换**：Go的`net/http` → Java的`com.sun.net.httpserver`
2. **文件上传解析**：实现简化的`MultipartParser`处理`multipart/form-data`
3. **文件操作**：`os`包 → `java.nio.file` API (`Files.createDirectories()`, `Files.newOutputStream()`)
4. **流操作**：`io.Copy()` → `input.transferTo(output)`
5. **异常处理**：Go的`if err != nil` → Java的try-catch
6. **路径处理**：`filepath.Join()` → `Paths.get().resolve()`
7. **资源管理**：Go的`defer` → Java的try-with-resources

**编译运行**：
```bash
javac FileUploadServer.java
java FileUploadServer
```

**测试**：使用curl或Postman POST到`http://localhost:8080/upload`，Content-Type为`multipart/form-data`，包含`file`字段的文件。

**注意**：这是一个简化版本的生产级应用建议使用Spring Boot + `MultipartFile`或Apache Commons FileUpload获得更robust的文件上传支持。

