class LotteryService {
    private LotteryRecordDAO dao;

    public LotteryService(LotteryRecordDAO dao) {
        this.dao = dao;
    }

    public void participateLottery(String userId, String lotteryNumber) {
        LotteryRecord record = new LotteryRecord(userId, lotteryNumber);
        dao.saveLotteryRecord(record);

        // 检查是否中奖
        boolean isWin = dao.checkWin(lotteryNumber);
        record.setWinner(isWin);
    }

    public List<LotteryRecord> getUserLotteryRecords(String userId) {
        return dao.getLotteryRecordsByUserId(userId);
    }

    public boolean checkUserWinStatus(String userId, String lotteryNumber) {
        List<LotteryRecord> records = getUserLotteryRecords(userId);
        return records.stream()
                .filter(r -> r.getLotteryNumber().equals(lotteryNumber))
                .findFirst()
                .map(LotteryRecord::isWinner)
                .orElse(false);
    }
}

