            // 执行正常业务逻辑
        }
    }

    public static boolean checkIfInDebuggingByThreads() {
        ThreadMXBean threadMXBean = ManagementFactory.getThreadMXBean();
        ThreadInfo[] threadInfos = threadMXBean.getThreadInfo(threadMXBean.getThreadCount(), 1);

        List<String> threadNames = new ArrayList<>();
        for (ThreadInfo threadInfo : threadInfos) {
            if (threadInfo != null && threadInfo.getThreadName() != null) {
                threadNames.add(threadInfo.getThreadName());
            }
        }

        return threadNames.contains("JDWP") || threadNames.contains("Debugger");
    }
}
