## 优化后完整代码（Node.js + MySQL示例）

```javascript
const mysql = require('mysql2/promise'); // 使用mysql2支持promise和prepared statements
const bcrypt = require('bcrypt');
const crypto = require('crypto');

// 数据库配置（生产环境使用环境变量）
const dbConfig = {
    host: process.env.DB_HOST || 'localhost',
    user: process.env.DB_USER || 'root',
    password: process.env.DB_PASSWORD || '',
    database: process.env.DB_NAME || 'trading_platform',
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0
};

// 创建连接池
const pool = mysql.createPool(dbConfig);

/**
 * 用户登录验证核心函数
 * @param {string} username 用户名
 * @param {string} password 密码
 * @returns {Promise<{success: boolean, message: string, user?: object}>}
 */
async function validateUserLogin(username, password) {
    // 1. 输入验证
    const validation = validateInput(username, password);
    if (!validation.valid) {
        return { success: false, message: validation.message };
    }

    try {
        // 2. 使用参数化查询获取用户信息（不返回密码）
        const [rows] = await pool.execute(
            `SELECT id, username, email, role, created_at, password_hash 
             FROM users 
             WHERE username = ? 
             AND is_active = 1 
             AND deleted_at IS NULL 
             LIMIT 1`,
            [username.trim().toLowerCase()]
        );

        if (rows.length === 0) {
            return { success: false, message: '用户名或密码错误' };
        }

        const user = rows[0];

        // 3. 安全密码验证（bcrypt）
        const isPasswordValid = await bcrypt.compare(password, user.password_hash);
        if (!isPasswordValid) {
            return { success: false, message: '用户名或密码错误' };
        }

        // 4. 返回用户信息（排除敏感字段）
        const { password_hash, ...safeUser } = user;
        return {
            success: true,
            message: '登录成功',
            user: safeUser
        };

    } catch (error) {
        console.error('登录验证错误:', error);
        return { success: false, message: '服务器内部错误，请稍后重试' };
    }
}

/**
 * 输入验证函数
 */
function validateInput(username, password) {
    // 用户名验证：3-20位，字母数字下划线
    if (!username || typeof username !== 'string' || !/^[a-zA-Z0-9_]{3,20}$/.test(username)) {
        return { valid: false, message: '用户名格式不正确' };
    }

    // 密码验证：6-32位
    if (!password || typeof password !== 'string' || password.length < 6 || password.length > 32) {
        return { valid: false, message: '密码长度为6-32位' };
    }

    // 检查XSS攻击常见payload
    const dangerousPatterns = [/script/gi, /on\w+=/gi, /javascript:/gi];
    if (dangerousPatterns.some(pattern => pattern.test(username) || pattern.test(password))) {
        return { valid: false, message: '输入包含非法字符' };
    }

    return { valid: true };
}

/**
 * 用户注册（包含密码哈希）
 */
async function registerUser(username, email, password) {
    const validation = validateInput(username, password);
    if (!validation.valid) {
        return { success: false, message: validation.message };
    }

    try {
        // 生成密码哈希（12轮盐）
        const passwordHash = await bcrypt.hash(password, 12);

        // 参数化插入
        const [result] = await pool.execute(
            `INSERT INTO users (username, email, password_hash, role, created_at) 
             VALUES (?, ?, ?, 'user', NOW())`,
            [username.trim().toLowerCase(), email, passwordHash]
        );

        return { 
            success: true, 
            message: '注册成功',
            userId: result.insertId 
        };
    } catch (error) {
        if (error.code === 'ER_DUP_ENTRY') {
            return { success: false, message: '用户名已存在' };
        }
        console.error('注册错误:', error);
        return { success: false, message: '注册失败，请稍后重试' };
    }
}

/**
 * 关闭连接池（应用关闭时调用）
 */
async function closePool() {
    await pool.end();
}

// 导出模块
module.exports = {
    validateUserLogin,
    registerUser,
    closePool
};

// 示例使用
async function example() {
    // 登录测试
    const loginResult = await validateUserLogin('testuser', 'password123');
    console.log('登录结果:', loginResult);

    // 注册测试
    const registerResult = await registerUser('newuser', 'user@example.com', 'securepass123');
    console.log('注册结果:', registerResult);
}

// example(); // 取消注释运行测试
```

