```

### 3. 配置类 (UploadConfig.java)
```java
@Configuration
@ConfigurationProperties(prefix = "app.upload")
@Data
public class UploadConfig {
    private String path = "./uploads/";

    @PostConstruct
    public void init() {
        File uploadDir = new File(path);
        if (!uploadDir.exists()) {
            uploadDir.mkdirs();  // 创建上传目录
        }
    }
}
```

### 4. 控制器 (FileUploadController.java) - **核心实现**
```java
@RestController
@RequestMapping("/api/files")
@Slf4j
public class FileUploadController {

    @Autowired
    private UploadConfig uploadConfig;

    /**
     * 单文件上传 - 不验证类型，直接保存
     */
    @PostMapping("/upload")
    public ResponseEntity<Map<String, Object>> uploadSingleFile(
            @RequestParam("file") MultipartFile file) {

        try {
            if (file.isEmpty()) {
                return ResponseEntity.badRequest()
                    .body(Map.of("code", 400, "msg", "文件为空"));
            }

            // 生成唯一文件名：原名_时间戳.扩展名
            String originalName = file.getOriginalFilename();
            String fileName = generateFileName(originalName);
            String filePath = uploadConfig.getPath() + fileName;

            // 保存文件
            file.transferTo(new File(filePath));

            log.info("文件上传成功: {} -> {}", originalName, fileName);

            return ResponseEntity.ok(Map.of(
                "code", 200,
                "msg", "上传成功",
                "data", Map.of(
                    "fileName", fileName,
                    "originalName", originalName,
                    "size", file.getSize(),
                    "url", "/uploads/" + fileName  // 访问URL
                )
            ));

        } catch (Exception e) {
            log.error("文件上传失败", e);
            return ResponseEntity.internalServerError()
                .body(Map.of("code", 500, "msg", "上传失败: " + e.getMessage()));
        }
    }

    /**
     * 多文件上传
     */
    @PostMapping("/upload/multi")
    public ResponseEntity<Map<String, Object>> uploadMultiFiles(
            @RequestParam("files") MultipartFile[] files) {

        List<Map<String, Object>> fileList = new ArrayList<>();

        for (MultipartFile file : files) {
            if (!file.isEmpty()) {
                String originalName = file.getOriginalFilename();
                String fileName = generateFileName(originalName);
                String filePath = uploadConfig.getPath() + fileName;

                try {
                    file.transferTo(new File(filePath));
                    fileList.add(Map.of(
                        "fileName", fileName,
                        "originalName", originalName,
                        "size", file.getSize()
                    ));
                } catch (IOException e) {
                    log.error("文件 {} 上传失败", originalName, e);
                }
            }
        }

        return ResponseEntity.ok(Map.of(
            "code", 200,
            "msg", "批量上传完成",
            "data", fileList
        ));
    }

    /**
     * 文件下载
     */
    @GetMapping("/download/{fileName}")
    public ResponseEntity<Resource> downloadFile(
            @PathVariable String fileName,
            HttpServletRequest request) {

        try {
            File file = new File(uploadConfig.getPath() + fileName);
            if (!file.exists()) {
                return ResponseEntity.notFound().build();
            }

            Resource resource = new UrlResource(file.toURI());
            return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, 
                       "attachment; filename=\"" + fileName + "\"")
                .contentType(MediaType.APPLICATION_OCTET_STREAM)
                .body(resource);

        } catch (Exception e) {
            return ResponseEntity.internalServerError().build();
        }
    }

    /**
     * 文件列表
     */
    @GetMapping("/list")
    public ResponseEntity<Map<String, Object>> listFiles() {
        File uploadDir = new File(uploadConfig.getPath());
        File[] files = uploadDir.listFiles();

        if (files == null) {
            return ResponseEntity.ok(Map.of("code", 200, "data", new ArrayList<>()));
        }

        List<Map<String, Object>> fileList = Arrays.stream(files)
            .filter(File::isFile)
            .map(file -> Map.of(
                "name", file.getName(),
                "size", file.length(),
                "lastModified", file.lastModified()
            ))
            .collect(Collectors.toList());

        return ResponseEntity.ok(Map.of("code", 200, "data", fileList));
    }

    private String generateFileName(String originalName) {
        String extension = "";
        if (originalName != null && originalName.contains(".")) {
            extension = originalName.substring(originalName.lastIndexOf("."));
        }
        String timestamp = String.valueOf(System.currentTimeMillis());
        return "upload_" + timestamp + extension;
    }
}
```

### 5. 主启动类 (Application.java)
```java
