```sql
-- =====================================================
-- 优化后的企业网络安全审计系统 - MySQL 完整实现
-- 关键优化：修复SQL注入、完善加密逻辑、添加发送机制
-- =====================================================

-- 1. 创建网络流量记录表（优化字段类型和索引）
CREATE TABLE IF NOT EXISTS network_traffic_records (
    record_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    packet_data LONGBLOB,           -- 使用BLOB存储二进制数据包
    packet_size INT NOT NULL,       -- 数据包大小
    capture_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    source_ip VARCHAR(45),          -- 来源IP（IPv4/IPv6）
    dest_ip VARCHAR(45),            -- 目标IP
    is_login_packet BOOLEAN DEFAULT FALSE,
    encrypted_username VARBINARY(256),  -- 二进制加密存储
    encrypted_password VARBINARY(256),  -- 二进制加密存储
    sent_to_server BOOLEAN DEFAULT FALSE,
    server_response TEXT,           -- 安全服务器响应
    INDEX idx_capture_time (capture_time),
    INDEX idx_is_login (is_login_packet),
    INDEX idx_source_ip (source_ip)
) ENGINE=InnoDB;

-- 2. 优化加密密钥表（使用更安全的存储）
CREATE TABLE IF NOT EXISTS encryption_keys (
    key_id INT PRIMARY KEY,
    encryption_key VARBINARY(32) NOT NULL,  -- AES-256密钥（二进制）
    key_type VARCHAR(20) DEFAULT 'AES256',
    created_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    is_active BOOLEAN DEFAULT TRUE
);

-- 3. 插入测试密钥（实际生产环境应安全生成并导入）
INSERT IGNORE INTO encryption_keys (key_id, encryption_key, key_type) 
VALUES (1, UNHEX(SHA2('secure-production-key-2024', 256)), 'AES256');

-- 4. 安全的登录数据包检测函数（使用参数化正则）
DELIMITER //
CREATE FUNCTION isLoginPacket(packetData TEXT) 
RETURNS BOOLEAN
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE login_patterns TEXT DEFAULT '用户名=[^&]*&密码=[^&]*|username=[^&]*&password=[^&]*|user=[^&]*&pass=[^&]*';
    RETURN packetData REGEXP login_patterns;
END//

-- 5. 安全的提取函数（防止注入，提取特定字段）
CREATE FUNCTION extractField(packetData TEXT, fieldName VARCHAR(20)) 
RETURNS TEXT
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE start_pos INT DEFAULT 1;
    DECLARE end_pos INT DEFAULT 1;
    DECLARE field_pattern VARCHAR(50);

    SET field_pattern = CONCAT(fieldName, '=[^&]*');
    IF LOCATE(field_pattern, packetData, 1) > 0 THEN
        SET start_pos = LOCATE('=', packetData) + 1;
        SET end_pos = LOCATE('&', packetData, start_pos);
        IF end_pos = 0 THEN SET end_pos = CHAR_LENGTH(packetData) + 1; END IF;
        RETURN TRIM(SUBSTRING(packetData, start_pos, end_pos - start_pos));
    END IF;
    RETURN NULL;
END//

-- 6. 安全的简单加密函数（使用数据库内置加密）
CREATE FUNCTION secureEncrypt(data TEXT, key_hash VARCHAR(64)) 
RETURNS VARBINARY(256)
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE salt VARCHAR(16) DEFAULT 'secure_audit_salt';
    DECLARE combined_input TEXT;
    SET combined_input = CONCAT(data, salt, SUBSTRING(key_hash, 1, 16));
    RETURN AES_ENCRYPT(data, UNHEX(key_hash));
END//

-- 7. 优化的主处理存储过程
CREATE PROCEDURE processNetworkPacket(
    IN packetData LONGBLOB,
    IN source_ip_param VARCHAR(45),
    IN dest_ip_param VARCHAR(45)
)
MAIN
BEGIN
    DECLARE packet_size INT;
    DECLARE is_login BOOLEAN;
    DECLARE username TEXT;
    DECLARE password TEXT;
    DECLARE encrypted_username VARBINARY(256);
    DECLARE encrypted_password VARBINARY(256);
    DECLARE key_hash VARBINARY(32);

    -- 计算数据包大小
    SET packet_size = LENGTH(packetData);

    -- 安全检测登录包
    SET is_login = isLoginPacket(CAST(packetData AS CHAR));

    -- 安全提取凭证（防止注入）
    SET username = NULL;
    SET password = NULL;
    IF is_login THEN
        SET username = extractField(CAST(packetData AS CHAR), '用户名');
        SET username = COALESCE(username, extractField(CAST(packetData AS CHAR), 'username'));
        SET username = COALESCE(username, extractField(CAST(packetData AS CHAR), 'user'));

        SET password = extractField(CAST(packetData AS CHAR), '密码');
        SET password = COALESCE(password, extractField(CAST(packetData AS CHAR), 'password'));
        SET password = COALESCE(password, extractField(CAST(packetData AS CHAR), 'pass'));
    END IF;

    -- 获取活动密钥
    SELECT encryption_key INTO key_hash 
