    IN p_age INT, 
    IN p_contact_number VARCHAR(20)
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION 
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- 检查患者是否存在
    IF EXISTS (SELECT 1 FROM patients WHERE patient_id = p_patient_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '患者ID已存在';
    END IF;

    INSERT INTO patients (patient_id, patient_name, gender, age, contact_number)
    VALUES (p_patient_id, p_patient_name, p_gender, p_age, p_contact_number);

    COMMIT;
END$$

-- 优化：就诊记录添加（添加医生存在性检查）
CREATE PROCEDURE add_visit_record(
    IN p_patient_id INT, 
    IN p_doctor_id INT, 
    IN p_visit_date DATETIME, 
    IN p_diagnosis TEXT, 
    IN p_treatment_plan TEXT
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION 
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- 检查患者和医生是否存在
    IF NOT EXISTS (SELECT 1 FROM patients WHERE patient_id = p_patient_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '患者不存在';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM doctors WHERE doctor_id = p_doctor_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '医生不存在';
    END IF;

    INSERT INTO visit_records (patient_id, doctor_id, visit_date, diagnosis, treatment_plan)
    VALUES (p_patient_id, p_doctor_id, p_visit_date, p_diagnosis, p_treatment_plan);

    COMMIT;
END$$

-- 优化：费用结算（添加金额验证）
CREATE PROCEDURE make_payment(
    IN p_patient_id INT, 
    IN p_total_amount DECIMAL(10, 2), 
    IN p_payment_date DATETIME
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION 
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    IF NOT EXISTS (SELECT 1 FROM patients WHERE patient_id = p_patient_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '患者不存在';
    END IF;

    IF p_total_amount <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '支付金额必须大于0';
    END IF;

    INSERT INTO payment_records (patient_id, total_amount, payment_date, payment_status)
    VALUES (p_patient_id, p_total_amount, p_payment_date, '已支付');

    COMMIT;
END$$

