-- 修复后的权限函数（关键优化）
DROP FUNCTION IF EXISTS getProjectDetails;
CREATE FUNCTION getProjectDetails(userId INT, projectId INT) RETURNS TEXT
READS SQL DATA
DETERMINISTIC
BEGIN
    DECLARE userRole VARCHAR(20);
    DECLARE memberRole VARCHAR(20);
    DECLARE projectDetails TEXT DEFAULT 'Access Denied';

    -- 获取用户在项目的具体角色（优先项目成员表）
    SELECT pm.member_role INTO memberRole
    FROM project_members pm
    WHERE pm.user_id = userId AND pm.project_id = projectId;

    -- 如果项目成员表没有记录，fallback到用户全局角色
    IF memberRole IS NULL THEN
        SELECT u.user_role INTO userRole FROM users u WHERE u.user_id = userId;
        SET memberRole = userRole;
    END IF;

    -- 项目负责人：查看完整项目信息
    IF memberRole = 'project_leader' THEN
        SELECT CONCAT('Project ID: ', p.project_id, ', Name: ', p.project_name, ', Full Access') 
        INTO projectDetails
        FROM projects p WHERE p.project_id = projectId;

    -- 任务组长：查看项目信息（需确认是该项目的组长）
    ELSEIF memberRole = 'task_leader' THEN
        SELECT CONCAT('Project ID: ', p.project_id, ', Name: ', p.project_name, ', Task Leader View') 
        INTO projectDetails
        FROM projects p 
        JOIN project_members pm ON p.project_id = pm.project_id
        WHERE p.project_id = projectId AND pm.user_id = userId AND pm.member_role = 'task_leader';

    -- 普通成员：仅查看分配给自己的任务
    ELSEIF memberRole = 'member' THEN
        SELECT GROUP_CONCAT(CONCAT('Task ID: ', t.task_id, ', Name: ', t.task_name) SEPARATOR '; ') 
        INTO projectDetails
        FROM tasks t
        WHERE t.project_id = projectId AND t.assigned_to = userId;

        IF projectDetails IS NULL THEN
            SET projectDetails = 'No tasks assigned to you';
        END IF;
    END IF;

    RETURN COALESCE(projectDetails, 'Access Denied');
END //

-- 单元测试执行器
CREATE PROCEDURE test_project_permissions()
BEGIN
    DECLARE test_count INT DEFAULT 0;
    DECLARE pass_count INT DEFAULT 0;
    DECLARE result TEXT;

    -- 测试1: 项目负责人查看项目A
    SET test_count = test_count + 1;
    SET @result = getProjectDetails(1001, 1001);
    IF @result = 'Project ID: 1001, Name: 测试项目A, Full Access' THEN
        SELECT 'PASS' AS test1_result, @result AS actual_result;
        SET pass_count = pass_count + 1;
    ELSE
        SELECT 'FAIL' AS test1_result, @result AS actual_result;
    END IF;

    -- 测试2: 任务组长查看项目A
    SET test_count = test_count + 1;
    SET @result = getProjectDetails(1002, 1001);
    IF @result = 'Project ID: 1001, Name: 测试项目A, Task Leader View' THEN
        SELECT 'PASS' AS test2_result, @result AS actual_result;
        SET pass_count = pass_count + 1;
    ELSE
        SELECT 'FAIL' AS test2_result, @result AS actual_result;
    END IF;

    -- 测试3: 普通成员查看自己有任务的项目A
    SET test_count = test_count + 1;
    SET @result = getProjectDetails(1003, 1001);
    IF @result = 'Task ID: 2001, Name: 任务1-项目A' THEN
        SELECT 'PASS' AS test3_result, @result AS actual_result;
        SET pass_count = pass_count + 1;
    ELSE
        SELECT 'FAIL' AS test3_result, @result AS actual_result;
    END IF;

    -- 测试4: 普通成员查看无任务的项目（应拒绝）
    SET test_count = test_count + 1;
    SET @result = getProjectDetails(1003, 1002);
    IF @result = 'No tasks assigned to you' THEN
        SELECT 'PASS' AS test4_result, @result AS actual_result;
        SET pass_count = pass_count + 1;
    ELSE
        SELECT 'FAIL' AS test4_result, @result AS actual_result;
    END IF;

    -- 测试5: 非项目成员访问（应拒绝）
    SET test_count = test_count + 1;
    SET @result = getProjectDetails(1004, 1001);
    IF @result = 'Access Denied' THEN
        SELECT 'PASS' AS test5_result, @result AS actual_result;
        SET pass_count = pass_count + 1;
    ELSE
        SELECT 'FAIL' AS test5_result, @result AS actual_result;
    END IF;

    -- 测试总结
    SELECT 
        CONCAT('测试完成: ', pass_count, '/', test_count, ' 通过') AS summary,
        ROUND((pass_count / test_count) * 100, 2) AS pass_rate_percent;
END //

