import java.sql.*;
import java.util.List;
import java.util.ArrayList;

public class SecureJdbcExample {

    // 数据库连接配置（生产环境使用连接池）
    private static final String DB_URL = "jdbc:mysql://localhost:3306/tech_forum?useSSL=false&serverTimezone=UTC";
    private static final String DB_USER = "forum_user";
    private static final String DB_PASS = "secure_password";

    public static void main(String[] args) {
        SecureJdbcExample example = new SecureJdbcExample();

        // 模拟用户输入
        String userSearch = "Java' OR '1'='1"; // 恶意注入测试
        String userTag = "SQL; DROP TABLE users --"; // 恶意注入测试

        // ❌ 错误示例：直接拼接SQL（SQL注入风险）
        System.out.println("=== ❌ 错误示例：直接拼接SQL ===");
        insecureQuery(userSearch);

        // ✅ 正确示例1：使用PreparedStatement参数化查询
        System.out.println("\n=== ✅ 正确示例1：PreparedStatement参数化查询 ===");
        List<UserPost> results1 = secureSearchPosts(userSearch);
        printResults(results1);

        // ✅ 正确示例2：使用IN子句批量查询
        System.out.println("\n=== ✅ 正确示例2：批量标签查询 ===");
        List<String> tags = List.of("Java", "SQL", "安全");
        List<UserPost> results2 = secureSearchByTags(tags);
        printResults(results2);

        // ✅ 正确示例3：存储过程调用（高级用法）
        System.out.println("\n=== ✅ 正确示例3：存储过程调用 ===");
        List<UserPost> results3 = secureSearchByProc(userSearch);
        printResults(results3);
    }

    // ❌ 错误示例：直接拼接SQL（演示SQL注入漏洞）
    private static void insecureQuery(String userInput) {
        String sql = "SELECT * FROM user_posts WHERE title LIKE '%" + userInput + "%'";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            System.out.println("执行SQL: " + sql);
            while (rs.next()) {
                System.out.println("找到记录: " + rs.getString("title"));
            }
        } catch (SQLException e) {
            System.err.println("SQL注入攻击成功！错误: " + e.getMessage());
        }
    }

    // ✅ 正确示例1：PreparedStatement参数化查询（核心推荐）
    public List<UserPost> secureSearchPosts(String searchTerm) {
        List<UserPost> results = new ArrayList<>();
        String sql = """
            SELECT id, title, content, user_id, create_time 
            FROM user_posts 
            WHERE title LIKE ? OR content LIKE ?
            ORDER BY create_time DESC 
            LIMIT 20
            """;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            // 参数化绑定，自动转义特殊字符
            String likePattern = "%" + searchTerm.replaceAll("[^a-zA-Z0-9\\u4e00-\\u9fa5\\s]", "") + "%";
            pstmt.setString(1, likePattern);
            pstmt.setString(2, likePattern);

            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    results.add(new UserPost(
                        rs.getInt("id"),
                        rs.getString("title"),
                        rs.getString("content"),
                        rs.getInt("user_id"),
                        rs.getTimestamp("create_time")
                    ));
                }
            }
        } catch (SQLException e) {
            System.err.println("查询失败: " + e.getMessage());
        }
        return results;
    }

    // ✅ 正确示例2：使用IN子句批量查询
    public List<UserPost> secureSearchByTags(List<String> tags) {
        List<UserPost> results = new ArrayList<>();

        if (tags.isEmpty()) return results;

        // 动态构建参数化IN查询
        String placeholders = String.join(",", tags.stream().limit(10).map(t -> "?").toList());
        String sql = """
            SELECT p.id, p.title, p.content, p.user_id, p.create_time
            FROM user_posts p
            JOIN post_tags pt ON p.id = pt.post_id
            WHERE pt.tag_name IN (%s)
            GROUP BY p.id
            ORDER BY p.create_time DESC
            LIMIT 50
            """.formatted(placeholders);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            // 安全绑定参数
            for (int i = 0; i < tags.size() && i < 10; i++) {
                pstmt.setString(i + 1, tags.get(i).trim());
            }

            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    results.add(new UserPost(
                        rs.getInt("id"),
                        rs.getString("title"),
                        rs.getString("content"),
                        rs.getInt("user_id"),
                        rs.getTimestamp("create_time")
                    ));
                }
            }
        } catch (SQLException e) {
            System.err.println("批量查询失败: " + e.getMessage());
        }
        return results;
    }

    // ✅ 正确示例3：调用存储过程
    public List<UserPost> secureSearchByProc(String searchTerm) {
        List<UserPost> results = new ArrayList<>();
        String sql = "{CALL sp_search_posts(?, 20)}";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             CallableStatement cstmt = conn.prepareCall(sql)) {

            cstmt.setString(1, searchTerm);
            try (ResultSet rs = cstmt.executeQuery()) {
                while (rs.next()) {
                    results.add(new UserPost(
                        rs.getInt("id"),
                        rs.getString("title"),
                        rs.getString("content"),
                        rs.getInt("user_id"),
                        rs.getTimestamp("create_time")
                    ));
                }
            }
        } catch (SQLException e) {
            System.err.println("存储过程调用失败: " + e.getMessage());
        }
        return results;
    }

    private static void printResults(List<UserPost> posts) {
        if (posts.isEmpty()) {
