        }
        posts.forEach(post -> 
            System.out.printf("ID:%d | 标题:%s | 作者:%d%n", 
                post.id, post.title, post.userId));
    }

    // 数据模型类
    public static class UserPost {
        public final int id;
        public final String title;
        public final String content;
        public final int userId;
