-- 创建安全表结构
CREATE TABLE user_posts (
    id INT PRIMARY KEY AUTO_INCREMENT,
    title VARCHAR(200) NOT NULL,
    content TEXT,
    user_id INT NOT NULL,
    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_title (title),
    INDEX idx_user (user_id)
);

-- 推荐存储过程（MySQL示例）
DELIMITER //
CREATE PROCEDURE sp_search_posts(
    IN search_term VARCHAR(100),
    IN limit_count INT
)
BEGIN
    SET @like_pattern = CONCAT('%', REGEXP_REPLACE(search_term, '[^a-zA-Z0-9\u4e00-\u9fa5\s]', ''), '%');

    SELECT id, title, content, user_id, create_time
    FROM user_posts
    WHERE title LIKE @like_pattern OR content LIKE @like_pattern
    ORDER BY create_time DESC
    LIMIT limit_count;
END //
DELIMITER ;
